// Generated by tools/generate_striver_sheet.py from Striver-180-Java-Notes.pdf.
(() => {
  const problems = [{"id":1,"title":"Set Matrix Zeroes","module":"Arrays","approaches":[{"label":"Brute force","explanation":"Copy the matrix, scan the copy for zeros, and for each zero in the copy write entire row and column to zero in the original. Safe because reads use the copy, but O(mn) extra space.","complexity":"O(mn) time, O(mn) space.","code":"void setZeroesBrute(int[][] a) {\n     int n = a.length, m = a[0].length;\n     int[][] cp = new int[n][m];\n     for (int i = 0; i < n; i++)\n         System.arraycopy(a[i], 0, cp[i], 0, m);\n     for (int i = 0; i < n; i++)\n         for (int j = 0; j < m; j++)\n             if (cp[i][j] == 0) {\n                 for (int r = 0; r < n; r++) a[r][j] = 0;\n                 for (int c = 0; c < m; c++) a[i][c] = 0;\n             }\n }"},{"label":"Better","explanation":"Use  boolean  arrays  rowMark[n]  and  colMark[m].  First  pass  records  which  rows  and  columns  must  be  zeroed, second pass applies them. Linear time with O(m + n) auxiliary bits.","complexity":"O(mn) time, O(m + n) space.","code":"void setZeroesMarks(int[][] a) {\n     int n = a.length, m = a[0].length;\n     boolean[] row = new boolean[n], col = new boolean[m];\n     for (int i = 0; i < n; i++)\n         for (int j = 0; j < m; j++)\n             if (a[i][j] == 0) { row[i] = true; col[j] = true; }\n     for (int i = 0; i < n; i++)\n         for (int j = 0; j < m; j++)\n             if (row[i] || col[j]) a[i][j] = 0;\n }"},{"label":"Optimal","explanation":"Use the first row and first column as markers. If matrix[i][j] is 0, row i and column j must become 0. Writing those zeros immediately destroys later information, so record the row and column in matrix[i][0] and matrix[0][j]. The first cell is shared by row 0 and column 0, so keep two booleans for whether that row and column originally contained a zero. After the markers are set, clear the inner cells, then clear row 0 and column 0 if needed.","complexity":"O(mn) time, O(1) extra space.","code":"void setZeroes(int[][] a) {\n     int n = a.length, m = a[0].length;\n     boolean row0 = false, col0 = false;\n     for (int j = 0; j < m; j++) if (a[0][j] == 0) row0 = true;\n     for (int i = 0; i < n; i++) if (a[i][0] == 0) col0 = true;\n     for (int i = 1; i < n; i++)\n         for (int j = 1; j < m; j++)\n             if (a[i][j] == 0) { a[i][0] = 0; a[0][j] = 0; }\n     for (int i = 1; i < n; i++)\n         for (int j = 1; j < m; j++)\n             if (a[i][0] == 0 || a[0][j] == 0) a[i][j] = 0;\n     if (row0) for (int j = 0; j < m; j++) a[0][j] = 0;\n     if (col0) for (int i = 0; i < n; i++) a[i][0] = 0;\n }"}]},{"id":2,"title":"Pascal's Triangle","module":"Arrays","approaches":[{"label":"Brute force","explanation":"For each cell (r, c) compute C(r, c) with the multiplicative formula using long arithmetic. Correct but recomputes many overlapping combinations.","complexity":"O(numRows^3) time, O(numRows^2) space for output.","code":"List<List<Integer>> generateBrute(int numRows) {\n     List<List<Integer>> tri = new ArrayList<>();\n     for (int r = 0; r < numRows; r++) {\n         List<Integer> row = new ArrayList<>();\n         for (int c = 0; c <= r; c++) row.add((int) nCr(r, c));\n         tri.add(row);\n     }\n     return tri;\n }\n long nCr(int n, int r) {\n     if (r > n - r) r = n - r;\n     long ans = 1;\n     for (int i = 1; i <= r; i++) ans = ans * (n - r + i) / i;\n     return ans;\n }"},{"label":"Optimal","explanation":"Each value is the sum of the two values above it. Row r has r + 1 entries. The ends are 1. Every inner entry is the sum of the two neighbors in the previous row, which is the same recurrence as C(r, c) = C(r - 1, c - 1) + C(r - 1, c). Building row by row avoids factorial overflow and produces every row the problem asks for.","complexity":"O(numRows^2) time and space.","code":"List<List<Integer>> generate(int numRows) {\n     List<List<Integer>> tri = new ArrayList<>();\n     for (int r = 0; r < numRows; r++) {\n         List<Integer> row = new ArrayList<>();\n         for (int c = 0; c <= r; c++) {\n             if (c == 0 || c == r) row.add(1);\n             else row.add(tri.get(r - 1).get(c - 1) + tri.get(r - 1).get(c));\n         }\n         tri.add(row);\n     }\n     return tri;\n }"}]},{"id":3,"title":"Next Permutation","module":"Arrays","approaches":[{"label":"Brute force","explanation":"Generate permutations in lexicographic order (next_permutation on index array) until the sequence matches the current array, then take the following permutation. Factorial time.","complexity":"O(n! * n) time, O(n) space.","code":"void nextPermutationBrute(int[] a) {\n     int n = a.length;\n     Integer[] idx = new Integer[n];\n     for (int i = 0; i < n; i++) idx[i] = i;\n     int[] b = a.clone();\n     do {\n         for (int i = 0; i < n; i++) a[i] = b[idx[i]];\n         if (Arrays.equals(a, b)) break;\n     } while (nextPerm(idx));\n     do {\n         for (int i = 0; i < n; i++) a[i] = b[idx[i]];\n     } while (nextPerm(idx));\n }\n boolean nextPerm(Integer[] p) {\n     int i = p.length - 2;\n     while (i >= 0 && p[i] >= p[i + 1]) i--;\n     if (i < 0) return false;\n     int j = p.length - 1;\n     while (p[j] <= p[i]) j--;\n     int t = p[i]; p[i] = p[j]; p[j] = t;\n     for (int l = i + 1, r = p.length - 1; l < r; l++, r--) {\n         t = p[l]; p[l] = p[r]; p[r] = t;\n     }\n     return true;\n }"},{"label":"Optimal","explanation":"Find the longest non-increasing suffix, then the next pivot. The next permutation is the smallest rearrangement that is still larger than the current one. Scan from the right for the first descent: index i where a[i] < a[i + 1]. The suffix after i is descending, so it is the last permutation of those values. Swap a[i] with the smallest value to its right that is still  larger  than  a[i],  then  reverse  the  suffix  so  it  becomes  ascending.  If  no  descent  exists,  the  array  is  the  last permutation; reverse the whole array.","complexity":"O(n) time, O(1) space.","code":"void nextPermutation(int[] a) {\n     int i = a.length - 2;\n     while (i >= 0 && a[i] >= a[i + 1]) i--;\n     if (i >= 0) {\n         int j = a.length - 1;\n         while (a[j] <= a[i]) j--;\n         int t = a[i]; a[i] = a[j]; a[j] = t;\n     }\n     for (int l = i + 1, r = a.length - 1; l < r; l++, r--) {\n         int t = a[l]; a[l] = a[r]; a[r] = t;\n     }\n }"}]},{"id":4,"title":"Kadane's Algorithm","module":"Arrays","approaches":[{"label":"Brute force","explanation":"For every subarray [i, j], compute the sum and track the maximum. All O(n^2) segments are examined.","complexity":"O(n^2) time, O(1) extra space.","code":"int maxSubArrayBrute(int[] a) {\n     int best = Integer.MIN_VALUE;\n     for (int i = 0; i < a.length; i++) {\n         int sum = 0;\n         for (int j = i; j < a.length; j++) {\n             sum += a[j];\n             best = Math.max(best, sum);\n         }\n     }\n     return best;\n }"},{"label":"Optimal","explanation":"Best subarray ending at i extends the previous ending or starts fresh. Any maximum subarray ends at some index. The best one ending at i is a[i] plus the best ending at i - 1, unless that previous sum is negative, in which case it only hurts and we start at a[i]. Tracking that running choice and the best seen so far covers every ending. If every value is negative, the answer is the largest single element, because the running sum restarts at each element.","complexity":"O(n) time, O(1) space.","code":"int maxSubArray(int[] a) {\n     int best = a[0], cur = a[0];\n     for (int i = 1; i < a.length; i++) {\n         cur = Math.max(a[i], cur + a[i]);\n         best = Math.max(best, cur);\n     }\n     return best;\n }"}]},{"id":5,"title":"Sort an Array of 0s, 1s, and 2s","module":"Arrays","approaches":[{"label":"Brute force","explanation":"Use nested loops to bubble 2s to the end and 0s to the front (or run a generic O(n^2) sort). Correct but quadratic.","complexity":"O(n^2) time, O(1) space.","code":"void sortColorsBrute(int[] a) {\n     for (int i = 0; i < a.length; i++)\n         for (int j = i + 1; j < a.length; j++)\n             if (a[i] > a[j]) {\n                 int t = a[i]; a[i] = a[j]; a[j] = t;\n             }\n }"},{"label":"Better","explanation":"Count how many 0s, 1s, and 2s appear, then overwrite the array with three blocks. Two passes, constant extra space besides three counters.","complexity":"O(n) time, O(1) extra space.","code":"void sortColorsCount(int[] a) {\n     int c0 = 0, c1 = 0, c2 = 0;\n     for (int x : a) {\n         if (x == 0) c0++;\n         else if (x == 1) c1++;\n         else c2++;\n     }\n     int i = 0;\n     while (c0-- > 0) a[i++] = 0;\n     while (c1-- > 0) a[i++] = 1;\n     while (c2-- > 0) a[i++] = 2;\n }"},{"label":"Optimal","explanation":"Dutch national flag: three regions in one pass. Keep the invariant that [0, low) is 0s, [low, mid) is 1s, and (high, n) is 2s. mid walks the unknown middle. A 0 swaps into the zero region and both low and mid advance. A 1 is already in place, so only mid advances. A 2 swaps into the two region and high shrinks; mid stays, because the swapped-in value is still unknown.","complexity":"O(n) time, O(1) space.","code":"void sortColors(int[] a) {\n     int low = 0, mid = 0, high = a.length - 1;\n     while (mid <= high) {\n         if (a[mid] == 0) {\n             int t = a[low]; a[low] = a[mid]; a[mid] = t;\n             low++; mid++;\n         } else if (a[mid] == 1) {\n             mid++;\n         } else {\n             int t = a[mid]; a[mid] = a[high]; a[high] = t;\n             high--;\n         }\n     }\n }"}]},{"id":6,"title":"Best Time to Buy and Sell Stock","module":"Arrays","approaches":[{"label":"Brute force","explanation":"For each buy day i and sell day j > i, maximize prices[j] - prices[i]. Every transaction pair is checked.","complexity":"O(n^2) time, O(1) space.","code":"int maxProfitBrute(int[] prices) {\n     int best = 0;\n     for (int i = 0; i < prices.length; i++)\n         for (int j = i + 1; j < prices.length; j++)\n             best = Math.max(best, prices[j] - prices[i]);\n     return best;\n }"},{"label":"Optimal","explanation":"One pass: cheapest buy so far, best sell after it. A sale on day i must use some earlier day as the buy. The best buy for that sale is the minimum price on days 0 through i - 1. Scanning left to right, keep that minimum and the best difference. One transaction means we never need a second buy after the sell.","complexity":"O(n) time, O(1) space.","code":"int maxProfit(int[] prices) {\n     int best = 0, buy = prices[0];\n     for (int i = 1; i < prices.length; i++) {\n         best = Math.max(best, prices[i] - buy);\n         buy = Math.min(buy, prices[i]);\n     }\n     return best;\n }"}]},{"id":7,"title":"Rotate Image","module":"Arrays","approaches":[{"label":"Brute force","explanation":"Allocate a new n x n matrix and fill result[j][n - 1 - i] = a[i][j]. Then copy back into a if in-place output is required.","complexity":"O(n^2) time, O(n^2) extra space.","code":"void rotateBrute(int[][] a) {\n     int n = a.length;\n     int[][] b = new int[n][n];\n     for (int i = 0; i < n; i++)\n         for (int j = 0; j < n; j++)\n             b[j][n - 1 - i] = a[i][j];\n     for (int i = 0; i < n; i++)\n         System.arraycopy(b[i], 0, a[i], 0, n);\n }"},{"label":"Optimal","explanation":"Transpose, then reverse each row. A 90-degree clockwise rotation sends (i, j) to (j, n - 1 - i). Doing that with a cycle of four cells works, and so does a two-step rewrite: transpose turns (i, j) into (j, i), then reversing each row turns (j, i) into (j, n - 1 - i). Both steps are in place.","complexity":"O(n^2) time, O(1) space.","code":"void rotate(int[][] a) {\n     int n = a.length;\n     for (int i = 0; i < n; i++)\n         for (int j = i + 1; j < n; j++) {\n             int t = a[i][j]; a[i][j] = a[j][i]; a[j][i] = t;\n         }\n     for (int i = 0; i < n; i++)\n         for (int l = 0, r = n - 1; l < r; l++, r--) {\n             int t = a[i][l]; a[i][l] = a[i][r]; a[i][r] = t;\n         }\n }"}]},{"id":8,"title":"Merge Intervals","module":"Arrays","approaches":[{"label":"Brute force","explanation":"Repeatedly scan for two overlapping intervals, merge them into one, and restart until no overlap remains. Simple but can degrade to O(n^2) merges.","complexity":"O(n^2) time, O(n) space for the working list.","code":"int[][] mergeBrute(int[][] intervals) {\n     List<int[]> list = new ArrayList<>();\n     for (int[] iv : intervals) list.add(new int[]{iv[0], iv[1]});\n     boolean changed = true;\n     while (changed) {\n         changed = false;\n         for (int i = 0; i < list.size(); i++) {\n             for (int j = i + 1; j < list.size(); j++) {\n                 int[] a = list.get(i), b = list.get(j);\n                 if (a[0] <= b[1] && b[0] <= a[1]) {\n                     int[] m = new int[]{Math.min(a[0], b[0]), Math.max(a[1], b[1])};\n                     list.remove(j);\n                     list.remove(i);\n                     list.add(m);\n                     changed = true;\n                     break;\n                 }\n             }\n             if (changed) break;\n         }\n     }\n     return list.toArray(new int[list.size()][]);\n }"},{"label":"Optimal","explanation":"Sort by start, then absorb overlaps into the last interval. After sorting by start time, an interval overlaps the previous merged interval exactly when its start is no later than that interval's end. Extend the end to the farther of the two ends. If it starts after the current end, it is a new disjoint interval. Sorting makes one left-to-right pass enough.","complexity":"O(n log n) time, O(n) space for the answer.","code":"int[][] merge(int[][] intervals) {\n     Arrays.sort(intervals, (x, y) -> Integer.compare(x[0], y[0]));\n     List<int[]> out = new ArrayList<>();\n     int[] cur = intervals[0];\n     for (int i = 1; i < intervals.length; i++) {\n         if (intervals[i][0] <= cur[1]) cur[1] = Math.max(cur[1], intervals[i][1]);\n         else { out.add(cur); cur = intervals[i]; }\n     }\n     out.add(cur);\n     return out.toArray(new int[out.size()][]);\n }"}]},{"id":9,"title":"Merge Two Sorted Arrays Without Extra Space","module":"Arrays","approaches":[{"label":"Brute force","explanation":"Copy both arrays into a third buffer, merge with two pointers into that buffer, then copy the sorted result back into a and b. Uses O(n + m) auxiliary space.","complexity":"O(n + m) time, O(n + m) extra space.","code":"void mergeExtraSpace(int[] a, int[] b) {\n     int n = a.length, m = b.length;\n     int[] tmp = new int[n + m];\n     int i = 0, j = 0, k = 0;\n     while (i < n && j < m)\n         tmp[k++] = a[i] <= b[j] ? a[i++] : b[j++];\n     while (i < n) tmp[k++] = a[i++];\n     while (j < m) tmp[k++] = b[j++];\n     for (int t = 0; t < n; t++) a[t] = tmp[t];\n     for (int t = 0; t < m; t++) b[t] = tmp[n + t];\n }"},{"label":"Optimal","explanation":"Gap method: compare elements a fixed distance apart. Treat the two arrays as one logical sequence of length n + m. Start with gap = ceil((n + m) / 2). Swap any inversion between positions i and i + gap, then shrink the gap the same way shell sort does, down to 1. When the gap is 1, every adjacent inversion has been removed, so the logical sequence is sorted and both arrays stay in place.","complexity":"O((n + m) log(n + m)) time, O(1) extra space.","code":"void merge(int[] a, int[] b) {\n     int n = a.length, m = b.length, gap = (n + m + 1) / 2;\n     while (gap > 0) {\n         int i = 0, j = gap;\n         while (j < n + m) {\n             if (at(a, b, n, i) > at(a, b, n, j)) swap(a, b, n, i, j);\n             i++; j++;\n         }\n         if (gap == 1) break;\n         gap = (gap + 1) / 2;\n     }\n }\n int at(int[] a, int[] b, int n, int i) {\n     return i < n ? a[i] : b[i - n];\n }\n void swap(int[] a, int[] b, int n, int i, int j) {\n     int vi = at(a, b, n, i), vj = at(a, b, n, j);\n     if (i < n) a[i] = vj; else b[i - n] = vj;\n     if (j < n) a[j] = vi; else b[j - n] = vi;\n }"}]},{"id":10,"title":"Find the Duplicate Number","module":"Arrays","approaches":[{"label":"Brute force","explanation":"Sort  the  array  (or  mark  indices  in  an  auxiliary  boolean  array  of  size  n)  and  find  the  value  that  appears  twice. Modifies order or uses O(n) extra bits.","complexity":"O(n log n) time if sorting, O(n) space for marks.","code":"int findDuplicateBrute(int[] nums) {\n     int[] cnt = new int[nums.length];\n     for (int x : nums) {\n         if (++cnt[x] > 1) return x;\n     }\n     return -1;\n }"},{"label":"Optimal","explanation":"Floyd cycle detection on the index-to-value graph. Values lie in 1..n and the array has n + 1 cells, so following i -> nums[i]  is  a  functional  graph  with  exactly  one  cycle.  The  cycle  entrance  is  the  duplicated  value,  because  two indices point at it. The first phase meets inside the cycle. The second phase starts one pointer at nums[0]; both move one step, and they meet at the entrance. This does not modify the array.","complexity":"O(n) time, O(1) space.","code":"int findDuplicate(int[] nums) {\n     int slow = nums[0], fast = nums[0];\n     do {\n         slow = nums[slow];\n         fast = nums[nums[fast]];\n     } while (slow != fast);\n     slow = nums[0];\n     while (slow != fast) {\n         slow = nums[slow];\n         fast = nums[fast];\n     }\n     return slow;\n }"}]},{"id":11,"title":"Repeat and Missing Number","module":"Arrays","approaches":[{"label":"Brute force","explanation":"Use a boolean array or hash set expecting values 1..n. The value seen twice is the repeat; the value never seen is the missing one.","complexity":"O(n) time, O(n) space.","code":"int[] findErrorNumsBrute(int[] a) {\n     int n = a.length;\n     boolean[] seen = new boolean[n + 1];\n     int repeat = -1, missing = -1;\n     for (int v : a) {\n         if (seen[v]) repeat = v;\n         seen[v] = true;\n     }\n     for (int v = 1; v <= n; v++)\n         if (!seen[v]) missing = v;\n     return new int[]{repeat, missing};\n }"},{"label":"Optimal","explanation":"Two equations from sum and sum of squares. The array should be 1..n, but one value x is repeated and one value y is missing. The difference of sums is x - y. The difference of squares is x^2 - y^2 = (x - y)(x + y). Divide to get x + y, then solve the two linear equations. Use long so n up to 10^5 does not overflow.","complexity":"O(n) time, O(1) space.","code":"int[] findErrorNums(int[] a) {\n     long n = a.length, sum = 0, sq = 0;\n     for (int v : a) { sum += v; sq += (long) v * v; }\n     long diff = sum - n * (n + 1) / 2;\n     long sqDiff = sq - n * (n + 1) * (2 * n + 1) / 6;\n     long sumXY = sqDiff / diff;\n     int repeat = (int) ((diff + sumXY) / 2);\n     int missing = (int) (sumXY - repeat);\n     return new int[]{repeat, missing};\n }"}]},{"id":12,"title":"Count Inversions","module":"Arrays","approaches":[{"label":"Brute force","explanation":"Count every pair i < j with a[i] > a[j] with nested loops. Direct definition, quadratic.","complexity":"O(n^2) time, O(1) extra space.","code":"long inversionCountBrute(int[] a) {\n     long inv = 0;\n     for (int i = 0; i < a.length; i++)\n         for (int j = i + 1; j < a.length; j++)\n             if (a[i] > a[j]) inv++;\n     return inv;\n }"},{"label":"Optimal","explanation":"Count cross inversions while merging. An inversion is a pair i < j with a[i] > a[j]. Pairs that sit entirely in the left or right half are counted by recursion. During the merge, both halves are sorted, so if left[i] is greater than right[j], it is also greater than every remaining element of the right half. Add that whole block at once, then merge as in merge sort.","complexity":"O(n log n) time, O(n) space.","code":"long inversionCount(int[] a) {\n     return sort(a, 0, a.length - 1, new int[a.length]);\n }\n long sort(int[] a, int l, int r, int[] tmp) {\n     if (l >= r) return 0;\n     int m = (l + r) >>> 1;\n     long inv = sort(a, l, m, tmp) + sort(a, m + 1, r, tmp);\n     int i = l, j = m + 1, k = l;\n     while (i <= m && j <= r) {\n         if (a[i] <= a[j]) tmp[k++] = a[i++];\n         else { tmp[k++] = a[j++]; inv += m - i + 1; }\n     }\n     while (i <= m) tmp[k++] = a[i++];\n     while (j <= r) tmp[k++] = a[j++];\n     for (int t = l; t <= r; t++) a[t] = tmp[t];\n     return inv;\n }"}]},{"id":13,"title":"Search a 2D Matrix","module":"Arrays","approaches":[{"label":"Brute force","explanation":"Scan every cell until target is found or the matrix is exhausted. Ignores sorted structure.","complexity":"O(n * m) time, O(1) space.","code":"boolean searchMatrixBrute(int[][] a, int target) {\n     for (int[] row : a)\n         for (int v : row)\n             if (v == target) return true;\n     return false;\n }"},{"label":"Better","explanation":"Start at the top-right corner. If the cell is too large, move left; if too small, move down. Each step eliminates a row or column.","complexity":"O(n + m) time, O(1) space.","code":"boolean searchMatrixStair(int[][] a, int target) {\n     int r = 0, c = a[0].length - 1;\n     while (r < a.length && c >= 0) {\n         if (a[r][c] == target) return true;\n         if (a[r][c] > target) c--;\n         else r++;\n     }\n     return false;\n }"},{"label":"Optimal","explanation":"Binary search on the matrix viewed as one sorted array. Each row is sorted, and the first value of a row is greater than the last value of the previous row, so the whole matrix is one sorted sequence of length n * m. Index mid maps to row mid / m and column mid % m. Ordinary binary search then applies.","complexity":"O(log(nm)) time, O(1) space.","code":"boolean searchMatrix(int[][] a, int target) {\n     int n = a.length, m = a[0].length;\n     int lo = 0, hi = n * m - 1;\n     while (lo <= hi) {\n         int mid = (lo + hi) >>> 1;\n         int v = a[mid / m][mid % m];\n         if (v == target) return true;\n         if (v < target) lo = mid + 1;\n         else hi = mid - 1;\n     }\n     return false;\n }"}]},{"id":14,"title":"Pow(x, n)","module":"Arrays","approaches":[{"label":"Brute force","explanation":"Multiply x into an accumulator |n| times (handle negative n by inverting once). Linear in the exponent.","complexity":"O(|n|) time, O(1) space.","code":"double myPowBrute(double x, int n) {\n     long e = n;\n     if (e < 0) { x = 1 / x; e = -e; }\n     double ans = 1;\n     for (long i = 0; i < e; i++) ans *= x;\n     return ans;\n }"},{"label":"Optimal","explanation":"Binary  exponentiation.  x^n  =  (x^2)^(n/2)  when  n  is  even,  and  x  *  (x^2)^(n/2)  when  n  is  odd.  That  halves  the exponent each step. Store the exponent in a long before negating it, because n can be Integer.MIN_VALUE. A negative exponent means invert the base first and then use the positive power.","complexity":"O(log |n|) time, O(1) space.","code":"double myPow(double x, int n) {\n     long e = n;\n     if (e < 0) { x = 1 / x; e = -e; }\n     double ans = 1;\n     while (e > 0) {\n         if ((e & 1) == 1) ans *= x;\n         x *= x;\n         e >>= 1;\n     }\n     return ans;\n }"}]},{"id":15,"title":"Majority Element I","module":"Arrays","approaches":[{"label":"Brute force","explanation":"For each distinct value (or each index), count occurrences in a second loop and return the first value with count > n/2.","complexity":"O(n^2) time, O(1) extra space.","code":"int majorityElementBrute(int[] a) {\n     int n = a.length;\n     for (int i = 0; i < n; i++) {\n         int cnt = 0;\n         for (int j = 0; j < n; j++)\n             if (a[j] == a[i]) cnt++;\n         if (cnt > n / 2) return a[i];\n     }\n     return a[0];\n }"},{"label":"Better","explanation":"Sort the array and return the middle element. A majority must occupy the middle index after sorting.","complexity":"O(n log n) time, O(1) extra space if sorting in place.","code":"int majorityElementSort(int[] a) {\n     Arrays.sort(a);\n     return a[a.length / 2];\n }"},{"label":"Optimal","explanation":"Boyer-Moore vote: one candidate and a counter. The majority element appears more than n/2 times, so it survives pairing. Walk the array with a candidate and a count. Matching the candidate increments the count; anything else decrements  it.  At  zero,  the  previous  candidate  has  been  cancelled  and  the  current  value  becomes  the  new candidate. Because a true majority cannot be fully cancelled, it is the candidate at the end. The problem promises a majority, so a second verification pass is unnecessary.","complexity":"O(n) time, O(1) space.","code":"int majorityElement(int[] a) {\n     int cand = a[0], count = 0;\n     for (int x : a) {\n         if (count == 0) cand = x;\n         count += (x == cand) ? 1 : -1;\n     }\n     return cand;\n }"}]},{"id":16,"title":"Majority Element II","module":"Arrays","approaches":[{"label":"Brute force","explanation":"Count frequency of every value with a hash map and collect keys whose count exceeds n/3. Straightforward and linear time with extra space.","complexity":"O(n) time, O(n) space.","code":"List<Integer> majorityElementBrute(int[] a) {\n     Map<Integer, Integer> cnt = new HashMap<>();\n     for (int x : a) cnt.put(x, cnt.getOrDefault(x, 0) + 1);\n     List<Integer> ans = new ArrayList<>();\n     for (var e : cnt.entrySet())\n         if (e.getValue() > a.length / 3) ans.add(e.getKey());\n     return ans;\n }"},{"label":"Optimal","explanation":"Boyer-Moore with two candidates. At most two values can appear more than n/3 times. Keep two candidates and two  counters.  A  match  increments  that  candidate.  If  a  counter  is  zero,  adopt  the  current  value.  Otherwise  both counters  fall  by  one,  which  cancels  one  copy  of  each  candidate  against  a  third  value.  The  survivors  are  only candidates. A second pass counts them and keeps those whose count is greater than n/3.","complexity":"O(n) time, O(1) space.","code":"List<Integer> majorityElement(int[] a) {\n     int n1 = 0, n2 = 0, c1 = 0, c2 = 0;\n     for (int x : a) {\n         if (x == n1) c1++;\n         else if (x == n2) c2++;\n         else if (c1 == 0) { n1 = x; c1 = 1; }\n         else if (c2 == 0) { n2 = x; c2 = 1; }\n         else { c1--; c2--; }\n     }\n     c1 = 0; c2 = 0;\n     for (int x : a) {\n         if (x == n1) c1++;\n         else if (x == n2) c2++;\n     }\n     List<Integer> ans = new ArrayList<>();\n     if (c1 > a.length / 3) ans.add(n1);\n     if (n2 != n1 && c2 > a.length / 3) ans.add(n2);\n     return ans;\n }"}]},{"id":17,"title":"Maximum Product Subarray","module":"Arrays","approaches":[{"label":"Brute force","explanation":"For each subarray, multiply all elements and track the maximum product. Handles zeros and negatives correctly but slowly.","complexity":"O(n^2) time, O(1) extra space.","code":"int maxProductBrute(int[] a) {\n     int best = Integer.MIN_VALUE;\n     for (int i = 0; i < a.length; i++) {\n         int p = 1;\n         for (int j = i; j < a.length; j++) {\n             p *= a[j];\n             best = Math.max(best, p);\n         }\n     }\n     return best;\n }"},{"label":"Optimal","explanation":"Kadane with both the best and worst product ending here. A negative number flips a large product into a small one and a small product into a large one. So the best product ending at i is the max of a[i], a[i] times the previous max, and a[i] times the previous min. Keep both ends. A zero splits the array into independent pieces, which falls out naturally because multiplying by zero resets both ends to zero and the next element starts fresh.","complexity":"O(n) time, O(1) space.","code":"int maxProduct(int[] a) {\n     int best = a[0], mx = a[0], mn = a[0];\n     for (int i = 1; i < a.length; i++) {\n         int x = a[i];\n         int hi = Math.max(x, Math.max(mx * x, mn * x));\n         int lo = Math.min(x, Math.min(mx * x, mn * x));\n         mx = hi; mn = lo;\n         best = Math.max(best, mx);\n     }\n     return best;\n }"}]},{"id":18,"title":"Reverse Pairs","module":"Arrays","approaches":[{"label":"Brute force","explanation":"Check every pair i < j and increment when a[i] > 2L * a[j]. Direct definition.","complexity":"O(n^2) time, O(1) extra space.","code":"int reversePairsBrute(int[] a) {\n     int cnt = 0;\n     for (int i = 0; i < a.length; i++)\n         for (int j = i + 1; j < a.length; j++)\n             if (a[i] > 2L * a[j]) cnt++;\n     return cnt;\n }"},{"label":"Optimal","explanation":"Count  a[i]  >  2  *  a[j]  while  merging.  Same  split  as  inversion  count,  but  the  condition  is  stricter  than  a  plain greater-than. Before merging a sorted left half and right half, walk i on the left and j on the right. Because the right half is sorted, once a[i] > 2 * a[j], every earlier right element also qualifies, and j only moves forward. Count those pairs, then merge normally. The factor 2 uses a long so it does not overflow.","complexity":"O(n log n) time, O(n) space.","code":"int reversePairs(int[] a) {\n     return (int) sort(a, 0, a.length - 1, new int[a.length]);\n }\n long sort(int[] a, int l, int r, int[] tmp) {\n     if (l >= r) return 0;\n     int m = (l + r) >>> 1;\n     long cnt = sort(a, l, m, tmp) + sort(a, m + 1, r, tmp);\n     int j = m + 1;\n     for (int i = l; i <= m; i++) {\n         while (j <= r && a[i] > 2L * a[j]) j++;\n         cnt += j - (m + 1);\n     }\n     int i = l, p = m + 1, k = l;\n     while (i <= m && p <= r)\n         tmp[k++] = a[i] <= a[p] ? a[i++] : a[p++];\n     while (i <= m) tmp[k++] = a[i++];\n     while (p <= r) tmp[k++] = a[p++];\n     for (int t = l; t <= r; t++) a[t] = tmp[t];\n     return cnt;\n }"}]},{"id":19,"title":"Two Sum","module":"Hashing","approaches":[{"label":"Brute force","explanation":"Try every ordered pair (i, j) with i < j. If a[i] + a[j] equals the target, return those indices. Correct but quadratic.","complexity":"O(n^2) time, O(1) extra space.","code":"int[] twoSumBrute(int[] a, int target) {\n     for (int i = 0; i < a.length; i++)\n         for (int j = i + 1; j < a.length; j++)\n             if (a[i] + a[j] == target) return new int[]{i, j};\n     return new int[0];\n }"},{"label":"Optimal","explanation":"Map value to index; look for target - x. For each value x, the partner that completes the target is target - x. If that partner was stored earlier, the pair exists and the indices are different. Store x only after the lookup so a value is not paired with itself. One pass is enough because every earlier index is already in the map.","complexity":"O(n) time, O(n) space.","code":"int[] twoSum(int[] a, int target) {\n     Map<Integer, Integer> seen = new HashMap<>();\n     for (int i = 0; i < a.length; i++) {\n         int need = target - a[i];\n         if (seen.containsKey(need)) return new int[]{seen.get(need), i};\n         seen.put(a[i], i);\n     }\n     return new int[0];\n }"}]},{"id":20,"title":"4Sum","module":"Hashing","approaches":[{"label":"Brute force","explanation":"Four  nested  loops  over  indices  i  <  j  <  l  <  r.  When  the  four  values  sum  to  target,  record  the  quadruplet.  Skip duplicate logic is optional; the method is dominated by O(n^4) checks.","complexity":"O(n^4) time, O(1) extra space besides the answer.","code":"List<List<Integer>> fourSumBrute(int[] a, int target) {\n     List<List<Integer>> ans = new ArrayList<>();\n     int n = a.length;\n     for (int i = 0; i < n; i++)\n         for (int j = i + 1; j < n; j++)\n             for (int l = j + 1; l < n; l++)\n                 for (int r = l + 1; r < n; r++) {\n                     long s = (long) a[i] + a[j] + a[l] + a[r];\n                     if (s == target)\n                         ans.add(Arrays.asList(a[i], a[j], a[l], a[r]));\n                 }\n     return ans;\n }"},{"label":"Optimal","explanation":"Sort, fix two numbers, then two pointers. Sorting lets equal values sit together so duplicates can be skipped, and it lets the remaining two numbers move inward. Fix i and j. If the four-sum is too small, move the left pointer; if too large, move the right pointer. On a hit, record the quadruplet and skip identical neighbors of both pointers. Skip identical i and j as well, otherwise the same quadruplet is emitted many times. Use a long sum because four ints can overflow.","complexity":"O(n^3) time, O(1) extra space besides the answer.","code":"List<List<Integer>> fourSum(int[] a, int target) {\n     Arrays.sort(a);\n     List<List<Integer>> ans = new ArrayList<>();\n     int n = a.length;\n     for (int i = 0; i < n; i++) {\n         if (i > 0 && a[i] == a[i - 1]) continue;\n         for (int j = i + 1; j < n; j++) {\n             if (j > i + 1 && a[j] == a[j - 1]) continue;\n             int l = j + 1, r = n - 1;\n             while (l < r) {\n                 long s = (long) a[i] + a[j] + a[l] + a[r];\n                 if (s == target) {\n                     ans.add(Arrays.asList(a[i], a[j], a[l], a[r]));\n                     l++; r--;\n                     while (l < r && a[l] == a[l - 1]) l++;\n                     while (l < r && a[r] == a[r + 1]) r--;\n                 } else if (s < target) l++;\n                 else r--;\n             }\n         }\n     }\n     return ans;\n }"}]},{"id":21,"title":"Longest Consecutive Sequence","module":"Hashing","approaches":[{"label":"Brute force","explanation":"Sort the array and scan runs of equal neighbors, extending each distinct value forward one step at a time while the next integer exists in the sorted list. Sorting makes existence checks linear in run length.","complexity":"O(n log n) time, O(1) extra space if sorting in place.","code":"int longestConsecutiveBrute(int[] a) {\n     if (a.length == 0) return 0;\n     Arrays.sort(a);\n     int best = 1, cur = 1;\n     for (int i = 1; i < a.length; i++) {\n         if (a[i] == a[i - 1]) continue;\n         if (a[i] == a[i - 1] + 1) cur++;\n         else { best = Math.max(best, cur); cur = 1; }\n     }\n     return Math.max(best, cur);\n }"},{"label":"Optimal","explanation":"A number starts a run only if num - 1 is absent. Put every value in a set. A consecutive run has exactly one left endpoint: the value whose predecessor is missing. From each such start, walk num, num + 1, num + 2 while they exist and keep the longest length. Each number is visited once as part of a walk, so the total work is linear even though the inner loop looks nested.","complexity":"O(n) time, O(n) space.","code":"int longestConsecutive(int[] a) {\n     Set<Integer> set = new HashSet<>();\n     for (int x : a) set.add(x);\n     int best = 0;\n     for (int x : set) {\n         if (set.contains(x - 1)) continue;\n         int len = 1;\n         while (set.contains(x + len)) len++;\n         best = Math.max(best, len);\n     }\n     return best;\n }"}]},{"id":22,"title":"Largest Subarray with Sum 0","module":"Hashing","approaches":[{"label":"Brute force","explanation":"For every start index i, extend j and track the running sum. When the sum is zero, update the best length j - i + 1. Every subarray is considered.","complexity":"O(n^2) time, O(1) extra space.","code":"int maxLenBrute(int[] a) {\n     int best = 0;\n     for (int i = 0; i < a.length; i++) {\n         int sum = 0;\n         for (int j = i; j < a.length; j++) {\n             sum += a[j];\n             if (sum == 0) best = Math.max(best, j - i + 1);\n         }\n     }\n     return best;\n }"},{"label":"Optimal","explanation":"Equal prefix sums bound a zero-sum segment. If prefix[j] == prefix[i], the sum from i + 1 through j is 0. The first time a prefix sum appears is the leftmost start of such a segment, so store that index and, on a repeat, take j - firstIndex. A prefix of 0 itself means the array from the start sums to 0; store sum 0 at index -1 so that case falls out of the same formula.","complexity":"O(n) time, O(n) space.","code":"int maxLen(int[] a) {\n     Map<Integer, Integer> first = new HashMap<>();\n     first.put(0, -1);\n     int sum = 0, best = 0;\n     for (int i = 0; i < a.length; i++) {\n         sum += a[i];\n         if (first.containsKey(sum)) best = Math.max(best, i - first.get(sum));\n         else first.put(sum, i);\n     }\n     return best;\n }"}]},{"id":23,"title":"Count Subarrays with XOR K","module":"Hashing","approaches":[{"label":"Brute force","explanation":"For each start i, walk j and XOR-accumulate. Whenever the subarray xor equals k, increment the answer. Correct but quadratic.","complexity":"O(n^2) time, O(1) extra space.","code":"int subarraysWithXorKBrute(int[] a, int k) {\n     int ans = 0;\n     for (int i = 0; i < a.length; i++) {\n         int x = 0;\n         for (int j = i; j < a.length; j++) {\n             x ^= a[j];\n             if (x == k) ans++;\n         }\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"prefixXor[j] ^ prefixXor[i] = k. XOR from i + 1 to j equals prefix[j] ^ prefix[i]. That equals k exactly when prefix[i] = prefix[j] ^ k. Count how many earlier prefixes have that value. Include the empty prefix 0 so subarrays that start at index 0 are counted. Each index adds the number of valid starts ending there.","complexity":"O(n) time, O(n) space.","code":"int subarraysWithXorK(int[] a, int k) {\n     Map<Integer, Integer> freq = new HashMap<>();\n     freq.put(0, 1);\n     int xor = 0, ans = 0;\n     for (int x : a) {\n         xor ^= x;\n         ans += freq.getOrDefault(xor ^ k, 0);\n         freq.put(xor, freq.getOrDefault(xor, 0) + 1);\n     }\n     return ans;\n }"}]},{"id":24,"title":"Subarray Sum Equals K","module":"Hashing","approaches":[{"label":"Brute force","explanation":"Enumerate all subarrays by nested loops, maintain the sum, and count how many equal k. No auxiliary structures.","complexity":"O(n^2) time, O(1) extra space.","code":"int subarraySumBrute(int[] a, int k) {\n     int ans = 0;\n     for (int i = 0; i < a.length; i++) {\n         int sum = 0;\n         for (int j = i; j < a.length; j++) {\n             sum += a[j];\n             if (sum == k) ans++;\n         }\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"prefix[j]  -  prefix[i]  =  k.  The  same  prefix  idea  as  the  zero-sum  problem,  but  now  the  needed  earlier  prefix  is currentSum - k, and we count occurrences instead of storing only the first index. The empty prefix 0 with frequency 1 covers subarrays that start at the beginning.","complexity":"O(n) time, O(n) space.","code":"int subarraySum(int[] a, int k) {\n     Map<Integer, Integer> freq = new HashMap<>();\n     freq.put(0, 1);\n     int sum = 0, ans = 0;\n     for (int x : a) {\n         sum += x;\n         ans += freq.getOrDefault(sum - k, 0);\n         freq.put(sum, freq.getOrDefault(sum, 0) + 1);\n     }\n     return ans;\n }"}]},{"id":25,"title":"Longest Subarray with Sum K","module":"Hashing","approaches":[{"label":"Brute force","explanation":"Try every subarray, track its sum, and keep the longest length with sum k. Works for negative numbers but scans all O(n^2) segments.","complexity":"O(n^2) time, O(1) extra space.","code":"int longestSubarraySumKBrute(int[] a, int k) {\n     int best = 0;\n     for (int i = 0; i < a.length; i++) {\n         int sum = 0;\n         for (int j = i; j < a.length; j++) {\n             sum += a[j];\n             if (sum == k) best = Math.max(best, j - i + 1);\n         }\n     }\n     return best;\n }"},{"label":"Better","explanation":"When every element is non-negative, a sliding window works: expand the right end while sum < k, shrink from the left while sum > k, and record length when sum equals k. Linear time but wrong if negatives appear.","complexity":"O(n) time, O(1) extra space (non-negative arrays only).","code":"int longestSubarraySumKWindow(int[] a, int k) {\n     int l = 0, sum = 0, best = 0;\n     for (int r = 0; r < a.length; r++) {\n         sum += a[r];\n         while (sum > k && l <= r) sum -= a[l++];\n         if (sum == k) best = Math.max(best, r - l + 1);\n     }\n     return best;\n }"},{"label":"Optimal","explanation":"First index of prefix sum - k, positives allow two pointers instead. For an array that may contain negatives, hashing is required: the longest subarray ending at i with sum k starts just after the earliest index whose prefix is sum - k. If the statement guarantees non-negative numbers, a sliding window is enough and uses constant space, because growing the right end only increases the sum. This function is the general version.","complexity":"O(n) time, O(n) space.","code":"int longestSubarraySumK(int[] a, int k) {\n     Map<Integer, Integer> first = new HashMap<>();\n     first.put(0, -1);\n     int sum = 0, best = 0;\n     for (int i = 0; i < a.length; i++) {\n         sum += a[i];\n         if (first.containsKey(sum - k))\n             best = Math.max(best, i - first.get(sum - k));\n         first.putIfAbsent(sum, i);\n     }\n     return best;\n }"}]},{"id":26,"title":"Count Distinct Elements in Every Window of Size K","module":"Hashing","approaches":[{"label":"Brute force","explanation":"For each window starting at i, insert its k elements into a set (or mark a frequency array if values are bounded) and report the set size. Each window is rebuilt from scratch.","complexity":"O(n * k) time, O(k) space per window.","code":"List<Integer> distinctInWindowsBrute(int[] a, int k) {\n     List<Integer> ans = new ArrayList<>();\n     for (int i = 0; i + k <= a.length; i++) {\n         Set<Integer> seen = new HashSet<>();\n         for (int j = i; j < i + k; j++) seen.add(a[j]);\n         ans.add(seen.size());\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"Frequency map of the current window. Build the frequency map of the first k elements. Its size is the number of distinct  values.  Slide  one  step:  decrement  the  outgoing  element  and  remove  it  when  its  count  hits  zero,  then increment the incoming element. The map size after each slide is the answer for that window. Each element enters and leaves once.","complexity":"O(n) time, O(k) space.","code":"List<Integer> distinctInWindows(int[] a, int k) {\n     Map<Integer, Integer> freq = new HashMap<>();\n     List<Integer> ans = new ArrayList<>();\n     for (int i = 0; i < a.length; i++) {\n         freq.put(a[i], freq.getOrDefault(a[i], 0) + 1);\n         if (i >= k) {\n             int out = a[i - k];\n             freq.put(out, freq.get(out) - 1);\n             if (freq.get(out) == 0) freq.remove(out);\n         }\n         if (i >= k - 1) ans.add(freq.size());\n     }\n     return ans;\n }"}]},{"id":27,"title":"Lower Bound and Upper Bound","module":"Binary Search","approaches":[{"label":"Brute force","explanation":"Scan from left to right. Lower bound is the first index with a[i] >= target, or n if none. Upper bound is the first index with a[i] > target. Linear and always correct on sorted input.","complexity":"O(n) time, O(1) space.","code":"int lowerBoundBrute(int[] a, int target) {\n     for (int i = 0; i < a.length; i++)\n         if (a[i] >= target) return i;\n     return a.length;\n }\n int upperBoundBrute(int[] a, int target) {\n     for (int i = 0; i < a.length; i++)\n         if (a[i] > target) return i;\n     return a.length;\n }"},{"label":"Optimal","explanation":"First index where the predicate becomes true. Lower bound is the first index with a[i] >= target. Upper bound is the first index with a[i] > target. Keep the invariant that lo is the first possible answer and hi is just past the end. If mid already satisfies the predicate, it might be the answer, so pull hi down to mid. Otherwise the answer is strictly to the right. The loop ends with lo == hi, which is the insertion point, or n if every element fails.","complexity":"O(log n) time, O(1) space.","code":"int lowerBound(int[] a, int target) {\n     int lo = 0, hi = a.length;\n     while (lo < hi) {\n         int mid = (lo + hi) >>> 1;\n         if (a[mid] >= target) hi = mid;\n         else lo = mid + 1;\n     }\n     return lo;\n }\n int upperBound(int[] a, int target) {\n     int lo = 0, hi = a.length;\n     while (lo < hi) {\n         int mid = (lo + hi) >>> 1;\n         if (a[mid] > target) hi = mid;\n         else lo = mid + 1;\n     }\n     return lo;\n }"}]},{"id":28,"title":"First and Last Position of an Element","module":"Binary Search","approaches":[{"label":"Brute force","explanation":"Walk the sorted array once. Remember the first index where a[i] equals target, keep updating the last index while values still match, and return [-1, -1] if never seen.","complexity":"O(n) time, O(1) space.","code":"int[] searchRangeBrute(int[] a, int target) {\n     int first = -1, last = -1;\n     for (int i = 0; i < a.length; i++) {\n         if (a[i] == target) {\n             if (first == -1) first = i;\n             last = i;\n         }\n     }\n     return new int[]{first, last};\n }"},{"label":"Optimal","explanation":"Lower bound and upper bound of the same target. The first occurrence is the lower bound. The last occurrence is the index just before the upper bound. If the lower bound is out of range or does not hold the target, the element is absent. Two binary searches replace a linear scan of the equal run.","complexity":"O(log n) time, O(1) space.","code":"int[] searchRange(int[] a, int target) {\n     int l = lowerBound(a, target);\n     if (l == a.length || a[l] != target) return new int[]{-1, -1};\n     return new int[]{l, upperBound(a, target) - 1};\n }"}]},{"id":29,"title":"Search in Rotated Sorted Array","module":"Binary Search","approaches":[{"label":"Brute force","explanation":"Find  the  pivot  where  the  rotation  happened  with  a  linear  scan,  then  run  ordinary  binary  search  on  the  half  that contains the target. Two O(log n) searches after an O(n) pivot find, or simply scan all indices.","complexity":"O(n) time for pivot scan, O(1) extra space.","code":"int searchBrute(int[] a, int target) {\n     for (int i = 0; i < a.length; i++)\n         if (a[i] == target) return i;\n     return -1;\n }"},{"label":"Better","explanation":"Locate the minimum index (pivot) with binary search on the rotated array, then binary search separately in the left sorted segment and the right sorted segment. Two binary searches after one pivot search.","complexity":"O(log n) time, O(1) space.","code":"int searchPivotBs(int[] a, int target) {\n     int n = a.length, lo = 0, hi = n - 1;\n     while (lo < hi) {\n         int mid = (lo + hi) >>> 1;\n         if (a[mid] > a[hi]) lo = mid + 1;\n         else hi = mid;\n     }\n     int pivot = lo;\n     if (target >= a[pivot] && target <= a[n - 1])\n         return bs(a, pivot, n - 1, target);\n     return bs(a, 0, pivot - 1, target);\n }\n int bs(int[] a, int lo, int hi, int target) {\n     while (lo <= hi) {\n         int mid = (lo + hi) >>> 1;\n         if (a[mid] == target) return mid;\n         if (a[mid] < target) lo = mid + 1;\n         else hi = mid - 1;\n     }\n     return -1;\n }"},{"label":"Optimal","explanation":"One half of the window is still sorted. Rotation keeps one of the two halves sorted. Compare a[mid] with a[lo]. If the left half is sorted and the target lies inside it, discard the right; otherwise discard the left. The mirror test handles a sorted right half. Duplicates break the comparison a[mid] == a[lo], so this function assumes distinct values, which is the usual statement.","complexity":"O(log n) time, O(1) space.","code":"int search(int[] a, int target) {\n     int lo = 0, hi = a.length - 1;\n     while (lo <= hi) {\n         int mid = (lo + hi) >>> 1;\n         if (a[mid] == target) return mid;\n         if (a[lo] <= a[mid]) {\n             if (a[lo] <= target && target < a[mid]) hi = mid - 1;\n             else lo = mid + 1;\n         } else {\n             if (a[mid] < target && target <= a[hi]) lo = mid + 1;\n             else hi = mid - 1;\n         }\n     }\n     return -1;\n }"}]},{"id":30,"title":"Single Element in a Sorted Array","module":"Binary Search","approaches":[{"label":"Brute force","explanation":"XOR every element. Values that appear twice cancel; the lone value remains. Linear time and simple, but does not exploit the sorted structure.","complexity":"O(n) time, O(1) space.","code":"int singleNonDuplicateXor(int[] a) {\n     int x = 0;\n     for (int v : a) x ^= v;\n     return x;\n }"},{"label":"Optimal","explanation":"Pairs occupy even-odd indexes until the single breaks them. Before the single element, values sit in pairs at (0, 1), (2, 3), and so on. After it, pairs sit at odd-even indexes. If mid is even and a[mid] == a[mid + 1], the single is still to the right. Otherwise it is at mid or to the left. Force mid onto an even index so the partner test is always the next cell.","complexity":"O(log n) time, O(1) space.","code":"int singleNonDuplicate(int[] a) {\n     int lo = 0, hi = a.length - 1;\n     while (lo < hi) {\n         int mid = (lo + hi) >>> 1;\n         if ((mid & 1) == 1) mid--;\n         if (a[mid] == a[mid + 1]) lo = mid + 2;\n         else hi = mid;\n     }\n     return a[lo];\n }"}]},{"id":31,"title":"Find Peak Element","module":"Binary Search","approaches":[{"label":"Brute force","explanation":"Check  each  index  i  (with  neighbors  treated  as  -infinity  at  the  ends).  Return  the  first  i  where  a[i]  is  at  least  both neighbors. A peak is guaranteed to exist.","complexity":"O(n) time, O(1) space.","code":"int findPeakBrute(int[] a) {\n     for (int i = 0; i < a.length; i++) {\n         int left = i == 0 ? Integer.MIN_VALUE : a[i - 1];\n         int right = i == a.length - 1 ? Integer.MIN_VALUE : a[i + 1];\n         if (a[i] >= left && a[i] >= right) return i;\n     }\n     return 0;\n }"},{"label":"Optimal","explanation":"Walk uphill; a slope decides which side still has a peak. A peak is not smaller than its neighbors. If a[mid] < a[mid + 1], the right side is strictly uphill at mid, so some peak exists at mid + 1 or further right (the array edge counts as negative infinity). Otherwise a peak exists at mid or to the left. The loop shrinks until one index remains.","complexity":"O(log n) time, O(1) space.","code":"int findPeakElement(int[] a) {\n     int lo = 0, hi = a.length - 1;\n     while (lo < hi) {\n         int mid = (lo + hi) >>> 1;\n         if (a[mid] < a[mid + 1]) lo = mid + 1;\n         else hi = mid;\n     }\n     return lo;\n }"}]},{"id":32,"title":"Nth Root of an Integer","module":"Binary Search","approaches":[{"label":"Brute force","explanation":"Try every integer x from 1 through m. The largest x with x^n <= m is the answer. Each trial multiplies n times with early exit on overflow.","complexity":"O(m * n) time, O(1) space.","code":"int nthRootBrute(int n, int m) {\n     int ans = -1;\n     for (int x = 1; x <= m; x++) {\n         if (powCmp(x, n, m) <= 0) ans = x;\n         else break;\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"Binary search on the answer, multiply in a long. The nth root of m is the largest integer x with x^n <= m. The search space  is  1..m.  Computing  x^n  by  a  loop  that  aborts  when  the  product  exceeds  m  avoids  overflow  and  avoids floating point. If mid^n is too big, the root is smaller; if it is too small, try a larger mid and remember it.","complexity":"O(n log m) time, O(1) space.","code":"int nthRoot(int n, int m) {\n     int lo = 1, hi = m, ans = -1;\n     while (lo <= hi) {\n         int mid = (lo + hi) >>> 1;\n         int cmp = powCmp(mid, n, m);\n         if (cmp == 0) return mid;\n         if (cmp < 0) { ans = mid; lo = mid + 1; }\n         else hi = mid - 1;\n     }\n     return ans;\n }\n int powCmp(int base, int exp, int limit) {\n     long p = 1;\n     for (int i = 0; i < exp; i++) {\n         p *= base;\n         if (p > limit) return 1;\n     }\n     return p == limit ? 0 : -1;\n }"}]},{"id":33,"title":"Median of Two Sorted Arrays","module":"Binary Search","approaches":[{"label":"Brute force","explanation":"Merge the two sorted arrays into one buffer of length n + m (standard two-pointer merge), then read the middle element(s). Correct but linear time and extra space.","complexity":"O(n + m) time, O(n + m) space.","code":"double findMedianBrute(int[] a, int[] b) {\n     int n = a.length, m = b.length;\n     int[] c = new int[n + m];\n     int i = 0, j = 0, k = 0;\n     while (i < n && j < m)\n         c[k++] = a[i] <= b[j] ? a[i++] : b[j++];\n     while (i < n) c[k++] = a[i++];\n     while (j < m) c[k++] = b[j++];\n     int mid = (n + m) / 2;\n     if (((n + m) & 1) == 1) return c[mid];\n     return (c[mid - 1] + c[mid]) / 2.0;\n }"},{"label":"Optimal","explanation":"Partition both arrays so the left half has the right count. The median is the middle of the merged array. Choose a cut i in the first array; the matching cut in the second is half - i, where half is the number of elements that belong on the left. The cut is valid when the largest on the left of each array is no bigger than the smallest on the right of the other. If a[i - 1] is too big, move the cut left; otherwise move it right. Odd and even totals differ only in whether the median is one value or the average of the two middle values.","complexity":"O(log min(n, m)) time, O(1) space.","code":"double findMedianSortedArrays(int[] a, int[] b) {\n     if (a.length > b.length) return findMedianSortedArrays(b, a);\n     int n = a.length, m = b.length, half = (n + m + 1) / 2;\n     int lo = 0, hi = n;\n     while (lo <= hi) {\n         int i = (lo + hi) >>> 1;\n         int j = half - i;\n         int aL = i == 0 ? Integer.MIN_VALUE : a[i - 1];\n         int aR = i == n ? Integer.MAX_VALUE : a[i];\n         int bL = j == 0 ? Integer.MIN_VALUE : b[j - 1];\n         int bR = j == m ? Integer.MAX_VALUE : b[j];\n         if (aL <= bR && bL <= aR) {\n             if (((n + m) & 1) == 1) return Math.max(aL, bL);\n             return (Math.max(aL, bL) + Math.min(aR, bR)) / 2.0;\n         } else if (aL > bR) hi = i - 1;\n         else lo = i + 1;\n     }\n     return 0;\n }"}]},{"id":34,"title":"Kth Element of Two Sorted Arrays","module":"Binary Search","approaches":[{"label":"Brute force","explanation":"Merge with two pointers until k elements have been written, then return the kth merged value. Same merge as the median brute force but stops early at k.","complexity":"O(n + m) time, O(1) extra space.","code":"int kthElementBrute(int[] a, int[] b, int k) {\n     int i = 0, j = 0, cnt = 0;\n     while (i < a.length && j < b.length) {\n         cnt++;\n         if (a[i] <= b[j]) {\n             if (cnt == k) return a[i];\n             i++;\n         } else {\n             if (cnt == k) return b[j];\n             j++;\n         }\n     }\n     while (i < a.length) {\n         cnt++;\n         if (cnt == k) return a[i];\n         i++;\n     }\n     while (j < b.length) {\n         cnt++;\n         if (cnt == k) return b[j];\n         j++;\n     }\n     return -1;\n }"},{"label":"Optimal","explanation":"The same partition, with the left side sized to k. Instead of splitting at the median, require exactly k elements on the left of the cut. The largest of the two left edges is the kth element of the merged array. The feasible range for the cut in the shorter array is max(0, k - m) through min(k, n), because the other array must be able to supply the rest.","complexity":"O(log min(n, m)) time, O(1) space.","code":"int kthElement(int[] a, int[] b, int k) {\n     if (a.length > b.length) return kthElement(b, a, k);\n     int n = a.length, m = b.length;\n     int lo = Math.max(0, k - m), hi = Math.min(k, n);\n     while (lo <= hi) {\n         int i = (lo + hi) >>> 1, j = k - i;\n         int aL = i == 0 ? Integer.MIN_VALUE : a[i - 1];\n         int aR = i == n ? Integer.MAX_VALUE : a[i];\n         int bL = j == 0 ? Integer.MIN_VALUE : b[j - 1];\n         int bR = j == m ? Integer.MAX_VALUE : b[j];\n         if (aL <= bR && bL <= aR) return Math.max(aL, bL);\n         if (aL > bR) hi = i - 1;\n         else lo = i + 1;\n     }\n     return -1;\n }"}]},{"id":35,"title":"Koko Eating Bananas","module":"Binary Search","approaches":[{"label":"Brute force","explanation":"Try every integer speed from 1 up to the largest pile. For each speed, sum ceil(pile / speed) across piles and pick the smallest speed whose total hours is at most h.","complexity":"O(n * M) time, O(1) space, M = max pile.","code":"int minEatingSpeedBrute(int[] piles, int h) {\n     int hi = 0;\n     for (int p : piles) hi = Math.max(hi, p);\n     for (int s = 1; s <= hi; s++)\n         if (hours(piles, s) <= h) return s;\n     return hi;\n }"},{"label":"Optimal","explanation":"Search on the answer: minimum speed that finishes in h hours. A slower speed always takes at least as many hours as a faster speed, so feasibility is monotonic. The speed lies between 1 and the largest pile. For a candidate speed, the hours needed are the sum of ceil(pile / speed). If that fits in h, try a slower speed; otherwise the speed is too small. The leftmost feasible speed is the answer.","complexity":"O(n log M) time, O(1) space, M = max pile.","code":"int minEatingSpeed(int[] piles, int h) {\n     int lo = 1, hi = 0;\n     for (int p : piles) hi = Math.max(hi, p);\n     while (lo < hi) {\n         int mid = (lo + hi) >>> 1;\n         if (hours(piles, mid) <= h) hi = mid;\n         else lo = mid + 1;\n     }\n     return lo;\n }\n long hours(int[] piles, int speed) {\n     long t = 0;\n     for (int p : piles) t += (p + speed - 1L) / speed;\n     return t;\n }"}]},{"id":36,"title":"Aggressive Cows","module":"Binary Search","approaches":[{"label":"Brute force","explanation":"Sort stalls, then try every candidate distance d from 0 up to the span. The largest d for which greedy placement of cows succeeds is the answer. Each check walks the stalls once.","complexity":"O(n log n + n * D) time, O(1) extra space, D = span.","code":"int aggressiveCowsBrute(int[] stalls, int cows) {\n     Arrays.sort(stalls);\n     int best = 0;\n     for (int d = stalls[stalls.length - 1] - stalls[0]; d >= 0; d--)\n         if (canPlace(stalls, cows, d)) return d;\n     return best;\n }"},{"label":"Optimal","explanation":"Search  on  the  minimum  distance  between  cows.  Sort  the  stalls.  If  some  minimum  distance  d  is  possible,  every smaller distance is also possible, so binary search d. A greedy check places the next cow in the first stall that is at least d away from the previous cow. If k cows fit, try a larger d; otherwise shrink. The search range is 0 through the distance between the first and last stall.","complexity":"O(n log n + n log D) time, O(1) extra space.","code":"int aggressiveCows(int[] stalls, int cows) {\n     Arrays.sort(stalls);\n     int lo = 0, hi = stalls[stalls.length - 1] - stalls[0];\n     while (lo < hi) {\n         int mid = (lo + hi + 1) >>> 1;\n         if (canPlace(stalls, cows, mid)) lo = mid;\n         else hi = mid - 1;\n     }\n     return lo;\n }\n boolean canPlace(int[] s, int cows, int d) {\n     int used = 1, last = s[0];\n     for (int i = 1; i < s.length && used < cows; i++) {\n         if (s[i] - last >= d) { used++; last = s[i]; }\n     }\n     return used == cows;\n }"}]},{"id":37,"title":"Allocate Minimum Number of Pages","module":"Binary Search","approaches":[{"label":"Brute force","explanation":"The answer lies between the thickest book and the sum of all pages. Try every cap in that range; the smallest cap that can be split into at most the allowed students is optimal.","complexity":"O(n * S) time, O(1) space, S = sum of pages.","code":"int allocateBrute(int[] pages, int students) {\n     if (students > pages.length) return -1;\n     int lo = 0, hi = 0;\n     for (int p : pages) { lo = Math.max(lo, p); hi += p; }\n     for (int cap = lo; cap <= hi; cap++)\n         if (need(pages, cap) <= students) return cap;\n     return hi;\n }"},{"label":"Optimal","explanation":"Search  on  the  maximum  pages  given  to  any  student.  Books  are  in  order  and  each  student  gets  a  contiguous segment. If a maximum load cap is feasible, every larger cap is feasible. The cap is at least the thickest book and at most the sum of all books. The check walks left to right and starts a new student whenever adding the next book would exceed the cap. If the number of students needed is within the limit, try a smaller cap.","complexity":"O(n log S) time, O(1) space, S = sum of pages.","code":"int allocate(int[] pages, int students) {\n     if (students > pages.length) return -1;\n     int lo = 0, hi = 0;\n     for (int p : pages) { lo = Math.max(lo, p); hi += p; }\n     while (lo < hi) {\n         int mid = (lo + hi) >>> 1;\n         if (need(pages, mid) <= students) hi = mid;\n         else lo = mid + 1;\n     }\n     return lo;\n }\n int need(int[] pages, int cap) {\n     int students = 1, load = 0;\n     for (int p : pages) {\n         if (load + p > cap) { students++; load = 0; }\n         load += p;\n     }\n     return students;\n }"}]},{"id":38,"title":"Median in a Row-Wise Sorted Matrix","module":"Binary Search","approaches":[{"label":"Brute force","explanation":"Copy every matrix entry into a list, sort, and return the element at rank (n*m+1)/2. Simple but ignores row-wise order.","complexity":"O(n * m * log(n * m)) time, O(n * m) space.","code":"int matrixMedianBrute(int[][] a) {\n     List<Integer> all = new ArrayList<>();\n     for (int[] row : a)\n         for (int v : row) all.add(v);\n     Collections.sort(all);\n     return all.get((all.size() - 1) / 2);\n }"},{"label":"Optimal","explanation":"Binary search the value, count how many entries are <= mid. The matrix median is the smallest value x such that at least (n * m + 1) / 2 entries are <= x. Values lie between the smallest first-column entry and the largest last-column entry. For a candidate, each row is sorted, so the count in that row is an upper bound. If the count is still short of the required rank, the median is larger.","complexity":"O(n log m * log V) time, O(1) space.","code":"int matrixMedian(int[][] a) {\n     int n = a.length, m = a[0].length;\n     int lo = a[0][0], hi = a[0][m - 1];\n     for (int i = 1; i < n; i++) {\n         lo = Math.min(lo, a[i][0]);\n         hi = Math.max(hi, a[i][m - 1]);\n     }\n     int need = (n * m + 1) / 2;\n     while (lo < hi) {\n         int mid = (lo + hi) >>> 1;\n         if (countLeq(a, mid) >= need) hi = mid;\n         else lo = mid + 1;\n     }\n     return lo;\n }\n int countLeq(int[][] a, int x) {\n     int cnt = 0;\n     for (int[] row : a) {\n         int lo = 0, hi = row.length;\n         while (lo < hi) {\n             int mid = (lo + hi) >>> 1;\n             if (row[mid] <= x) lo = mid + 1;\n             else hi = mid;\n         }\n         cnt += lo;\n     }\n     return cnt;\n }"}]},{"id":39,"title":"Capacity To Ship Packages Within D Days","module":"Binary Search","approaches":[{"label":"Brute force","explanation":"Capacity must be at least the heaviest package and at most the total weight. Scan every capacity in that range and use the greedy day-packing check; return the first feasible capacity.","complexity":"O(n * S) time, O(1) space, S = total weight.","code":"int shipWithinDaysBrute(int[] weights, int days) {\n     int lo = 0, hi = 0;\n     for (int w : weights) { lo = Math.max(lo, w); hi += w; }\n     for (int cap = lo; cap <= hi; cap++) {\n         int need = 1, load = 0;\n         for (int w : weights) {\n             if (load + w > cap) { need++; load = 0; }\n             load += w;\n         }\n         if (need <= days) return cap;\n     }\n     return hi;\n }"},{"label":"Optimal","explanation":"Same  search-on-answer  shape  as  book  allocation.  Packages  stay  in  order.  A  capacity  is  feasible  when  a left-to-right packing uses at most d days. Capacity is at least the heaviest package and at most the total weight. This is book allocation with days in place of students and weights in place of pages.","complexity":"O(n log S) time, O(1) space.","code":"int shipWithinDays(int[] weights, int days) {\n     int lo = 0, hi = 0;\n     for (int w : weights) { lo = Math.max(lo, w); hi += w; }\n     while (lo < hi) {\n         int mid = (lo + hi) >>> 1;\n         int need = 1, load = 0;\n         for (int w : weights) {\n             if (load + w > mid) { need++; load = 0; }\n             load += w;\n         }\n         if (need <= days) hi = mid;\n         else lo = mid + 1;\n     }\n     return lo;\n }"}]},{"id":40,"title":"Find the Smallest Divisor Given a Threshold","module":"Binary Search","approaches":[{"label":"Brute force","explanation":"Divisors  only  need  to  be  tried  from  1  through  the  maximum  array  value.  Pick  the  smallest  d  whose  sum  of ceil(a[i]/d) is at most the threshold.","complexity":"O(n * M) time, O(1) space, M = max element.","code":"int smallestDivisorBrute(int[] a, int threshold) {\n     int hi = 0;\n     for (int x : a) hi = Math.max(hi, x);\n     for (int d = 1; d <= hi; d++) {\n         long sum = 0;\n         for (int x : a) sum += (x + d - 1L) / d;\n         if (sum <= threshold) return d;\n     }\n     return hi;\n }"},{"label":"Optimal","explanation":"Minimum  divisor  whose  ceiling-sum  is  within  the  threshold.  ceil(a[i]  /  d)  shrinks  as  d  grows,  so  the  sum  is monotonic.  d  ranges  from  1  to  the  maximum  element.  The  check  is  the  same  ceiling  sum  used  for  Koko.  The smallest d whose sum is <= threshold is the answer.","complexity":"O(n log M) time, O(1) space.","code":"int smallestDivisor(int[] a, int threshold) {\n     int lo = 1, hi = 0;\n     for (int x : a) hi = Math.max(hi, x);\n     while (lo < hi) {\n         int mid = (lo + hi) >>> 1;\n         long sum = 0;\n         for (int x : a) sum += (x + mid - 1L) / mid;\n         if (sum <= threshold) hi = mid;\n         else lo = mid + 1;\n     }\n     return lo;\n }"}]},{"id":41,"title":"3Sum","module":"Sliding Window and Two Pointers","approaches":[{"label":"Brute force","explanation":"Try every triple (i, j, k) with i < j < k. When the sum is zero, sort the triplet and add it to a set so duplicates collapse. Correct but cubic.","complexity":"O(n^3) time, O(n) space for deduplication.","code":"List<List<Integer>> threeSumBrute(int[] a) {\n     Set<List<Integer>> set = new HashSet<>();\n     int n = a.length;\n     for (int i = 0; i < n; i++)\n         for (int j = i + 1; j < n; j++)\n             for (int k = j + 1; k < n; k++)\n                 if (a[i] + a[j] + a[k] == 0)\n                     set.add(Arrays.asList(a[i], a[j], a[k]));\n     return new ArrayList<>(set);\n }"},{"label":"Optimal","explanation":"Sort, fix a[i], and two-pointer the pair in the suffix for sum -a[i]. Skip equal i and, after a hit, skip equal left and right values so each triplet is recorded once.","complexity":"O(n^2) time, O(1) extra space besides the answer.","code":"List<List<Integer>> threeSum(int[] a) {\n     Arrays.sort(a);\n     List<List<Integer>> ans = new ArrayList<>();\n     for (int i = 0; i < a.length; i++) {\n         if (i > 0 && a[i] == a[i - 1]) continue;\n         int l = i + 1, r = a.length - 1;\n         while (l < r) {\n             int s = a[i] + a[l] + a[r];\n             if (s == 0) {\n                 ans.add(Arrays.asList(a[i], a[l], a[r]));\n                 l++; r--;\n                 while (l < r && a[l] == a[l - 1]) l++;\n                 while (l < r && a[r] == a[r + 1]) r--;\n             } else if (s < 0) l++;\n             else r--;\n         }\n     }\n     return ans;\n }"}]},{"id":42,"title":"Trapping Rain Water","module":"Sliding Window and Two Pointers","approaches":[{"label":"Brute force","explanation":"For each bar, scan left for the tallest bar and right for the tallest bar. Water at i is min(leftMax, rightMax) - height[i] when positive. Each index rescans both sides.","complexity":"O(n^2) time, O(1) space.","code":"int trapBrute(int[] h) {\n     int water = 0;\n     for (int i = 0; i < h.length; i++) {\n         int left = 0, right = 0;\n         for (int j = 0; j <= i; j++) left = Math.max(left, h[j]);\n         for (int j = i; j < h.length; j++) right = Math.max(right, h[j]);\n         water += Math.max(0, Math.min(left, right) - h[i]);\n     }\n     return water;\n }"},{"label":"Better","explanation":"Precompute leftMax[i] and rightMax[i] in two passes. Water at i uses those arrays in O(1). Same formula as brute, without rescanning every time.","complexity":"O(n) time, O(n) space.","code":"int trapPrefix(int[] h) {\n     int n = h.length;\n     int[] left = new int[n], right = new int[n];\n     left[0] = h[0];\n     for (int i = 1; i < n; i++) left[i] = Math.max(left[i - 1], h[i]);\n     right[n - 1] = h[n - 1];\n     for (int i = n - 2; i >= 0; i--) right[i] = Math.max(right[i + 1], h[i]);\n     int water = 0;\n     for (int i = 0; i < n; i++)\n         water += Math.max(0, Math.min(left[i], right[i]) - h[i]);\n     return water;\n }"},{"label":"Optimal","explanation":"Two  pointers  maintain  the  tallest  seen  from  the  left  and  from  the  right.  The  side  with  the  smaller  max  is  the bottleneck:  every  unprocessed  bar  on  that  side  is  capped  by  that  max,  so  add  the  difference  and  advance  that pointer.","complexity":"O(n) time, O(1) space.","code":"int trap(int[] h) {\n     int l = 0, r = h.length - 1, left = 0, right = 0, water = 0;\n     while (l < r) {\n         if (h[l] <= h[r]) {\n             left = Math.max(left, h[l]);\n             water += left - h[l];\n             l++;\n         } else {\n             right = Math.max(right, h[r]);\n             water += right - h[r];\n             r--;\n         }\n     }\n     return water;\n }"}]},{"id":43,"title":"Container With Most Water","module":"Sliding Window and Two Pointers","approaches":[{"label":"Brute force","explanation":"Try every pair of lines (l, r). Area is width times the shorter height. Track the maximum.","complexity":"O(n^2) time, O(1) space.","code":"int maxAreaBrute(int[] h) {\n     int best = 0;\n     for (int l = 0; l < h.length; l++)\n         for (int r = l + 1; r < h.length; r++)\n             best = Math.max(best, (r - l) * Math.min(h[l], h[r]));\n     return best;\n }"},{"label":"Optimal","explanation":"Start at the widest pair. Moving the taller line inward cannot help: width shrinks and the shorter line is unchanged. Move the shorter line to seek a taller partner that pays for the lost width.","complexity":"O(n) time, O(1) space.","code":"int maxArea(int[] h) {\n     int l = 0, r = h.length - 1, best = 0;\n     while (l < r) {\n         best = Math.max(best, (r - l) * Math.min(h[l], h[r]));\n         if (h[l] < h[r]) l++;\n         else r--;\n     }\n     return best;\n }"}]},{"id":44,"title":"Remove Duplicates from Sorted Array","module":"Sliding Window and Two Pointers","approaches":[{"label":"Brute force","explanation":"For  each  read  index,  check  whether  the  value  already  appears  in  the  prefix  [0..w].  If  not,  append  it.  Correct  on sorted input but rescans the kept prefix every time.","complexity":"O(n^2) time, O(1) space.","code":"int removeDuplicatesBrute(int[] a) {\n     if (a.length == 0) return 0;\n     int w = 0;\n     for (int r = 1; r < a.length; r++) {\n         boolean seen = false;\n         for (int j = 0; j <= w; j++)\n             if (a[j] == a[r]) { seen = true; break; }\n         if (!seen) a[++w] = a[r];\n     }\n     return w + 1;\n }"},{"label":"Optimal","explanation":"Duplicates are adjacent after sorting. write stays on the last kept value; whenever a[read] differs, copy it just after write. The answer length is write + 1.","complexity":"O(n) time, O(1) space.","code":"int removeDuplicates(int[] a) {\n     if (a.length == 0) return 0;\n     int w = 0;\n     for (int r = 1; r < a.length; r++) {\n         if (a[r] != a[w]) a[++w] = a[r];\n     }\n     return w + 1;\n }"}]},{"id":45,"title":"Max Consecutive Ones","module":"Sliding Window and Two Pointers","approaches":[{"label":"Brute force","explanation":"Every subarray is a candidate. Extend r from each start l while the subarray has no zero; track the longest run of ones.","complexity":"O(n^2) time, O(1) space.","code":"int findMaxConsecutiveOnesBrute(int[] a) {\n     int best = 0;\n     for (int l = 0; l < a.length; l++) {\n         for (int r = l; r < a.length && a[r] == 1; r++)\n             best = Math.max(best, r - l + 1);\n     }\n     return best;\n }"},{"label":"Optimal","explanation":"A run of ones ends at every zero. Count the current run and remember the longest; a zero resets the run to zero.","complexity":"O(n) time, O(1) space.","code":"int findMaxConsecutiveOnes(int[] a) {\n     int cur = 0, best = 0;\n     for (int x : a) {\n         cur = x == 1 ? cur + 1 : 0;\n         best = Math.max(best, cur);\n     }\n     return best;\n }"}]},{"id":46,"title":"Max Consecutive Ones III","module":"Sliding Window and Two Pointers","approaches":[{"label":"Brute force","explanation":"For each subarray, count zeros and keep it if the count is at most k. Track the longest valid length.","complexity":"O(n^2) time, O(1) space.","code":"int longestOnesBrute(int[] a, int k) {\n     int best = 0;\n     for (int l = 0; l < a.length; l++) {\n         int zeros = 0;\n         for (int r = l; r < a.length; r++) {\n             if (a[r] == 0) zeros++;\n             if (zeros <= k) best = Math.max(best, r - l + 1);\n             else break;\n         }\n     }\n     return best;\n }"},{"label":"Optimal","explanation":"Flipping a zero equals allowing up to k zeros inside the window. Grow r; when zeros exceed k, shrink l until legal again. Both pointers only move forward.","complexity":"O(n) time, O(1) space.","code":"int longestOnes(int[] a, int k) {\n     int l = 0, zeros = 0, best = 0;\n     for (int r = 0; r < a.length; r++) {\n         if (a[r] == 0) zeros++;\n         while (zeros > k) {\n             if (a[l] == 0) zeros--;\n             l++;\n         }\n         best = Math.max(best, r - l + 1);\n     }\n     return best;\n }"}]},{"id":47,"title":"Longest Substring Without Repeating Characters","module":"Sliding Window and Two Pointers","approaches":[{"label":"Brute force","explanation":"Try every substring [l, r]. Use a set to detect a repeated character; stop extending r when a duplicate appears.","complexity":"O(n^2) time, O(alphabet) space.","code":"int lengthOfLongestSubstringBrute(String s) {\n     int best = 0;\n     for (int l = 0; l < s.length(); l++) {\n         Set<Character> seen = new HashSet<>();\n         for (int r = l; r < s.length(); r++) {\n             if (!seen.add(s.charAt(r))) break;\n             best = Math.max(best, r - l + 1);\n         }\n     }\n     return best;\n }"},{"label":"Better","explanation":"Sliding window with a frequency map. Grow r; while a character count exceeds one, shrink l and decrement counts until the window is unique again.","complexity":"O(n) time, O(alphabet) space.","code":"int lengthOfLongestSubstringSet(String s) {\n     Map<Character, Integer> freq = new HashMap<>();\n     int l = 0, best = 0;\n     for (int r = 0; r < s.length(); r++) {\n         char c = s.charAt(r);\n         freq.put(c, freq.getOrDefault(c, 0) + 1);\n         while (freq.get(c) > 1) {\n             char left = s.charAt(l++);\n             freq.put(left, freq.get(left) - 1);\n         }\n         best = Math.max(best, r - l + 1);\n     }\n     return best;\n }"},{"label":"Optimal","explanation":"Store the last index of each character. When a[r] was seen inside the current window, start the window after that index. Record r as the new last index.","complexity":"O(n) time, O(1) space for a fixed alphabet, else O(alphabet).","code":"int lengthOfLongestSubstring(String s) {\n     int[] last = new int[256];\n     Arrays.fill(last, -1);\n     int l = 0, best = 0;\n     for (int r = 0; r < s.length(); r++) {\n         char c = s.charAt(r);\n         if (last[c] >= l) l = last[c] + 1;\n         last[c] = r;\n         best = Math.max(best, r - l + 1);\n     }\n     return best;\n }"}]},{"id":48,"title":"Minimum Window Substring","module":"Sliding Window and Two Pointers","approaches":[{"label":"Brute force","explanation":"Try every substring of s. A substring is valid when it contains every character of t with required multiplicity. Keep the shortest valid one.","complexity":"O(n^2 * m) time, O(1) space for a fixed alphabet.","code":"String minWindowBrute(String s, String t) {\n     int[] need = new int[128];\n     for (int i = 0; i < t.length(); i++) need[t.charAt(i)]++;\n     int best = Integer.MAX_VALUE, start = 0;\n     for (int l = 0; l < s.length(); l++) {\n         int[] have = new int[128];\n         int formed = 0, needDistinct = 0;\n         for (int c = 0; c < 128; c++) if (need[c] > 0) needDistinct++;\n         for (int r = l; r < s.length(); r++) {\n             char ch = s.charAt(r);\n             if (need[ch] == 0) continue;\n             if (++have[ch] == need[ch]) formed++;\n             if (formed == needDistinct && r - l + 1 < best) {\n                 best = r - l + 1;\n                 start = l;\n             }\n         }\n     }\n     return best == Integer.MAX_VALUE ? \"\" : s.substring(start, start + best);\n }"},{"label":"Optimal","explanation":"need counts how many characters t still owes the window. Grow r until every requirement is satisfied, then shrink l while updating the best window until a required count goes positive again.","complexity":"O(n + m) time, O(1) space for a fixed alphabet.","code":"String minWindow(String s, String t) {\n     int[] need = new int[128];\n     for (int i = 0; i < t.length(); i++) need[t.charAt(i)]++;\n     int missing = t.length(), best = Integer.MAX_VALUE, start = 0;\n     for (int l = 0, r = 0; r < s.length(); r++) {\n         if (need[s.charAt(r)]-- > 0) missing--;\n         while (missing == 0) {\n             if (r - l + 1 < best) { best = r - l + 1; start = l; }\n             if (++need[s.charAt(l)] > 0) missing++;\n             l++;\n         }\n     }\n     return best == Integer.MAX_VALUE ? \"\" : s.substring(start, start + best);\n }"}]},{"id":49,"title":"Fruit Into Baskets","module":"Sliding Window and Two Pointers","approaches":[{"label":"Brute force","explanation":"Two baskets mean at most two distinct fruit types. Check every subarray and count distinct values with a map; keep the longest valid window.","complexity":"O(n^2) time, O(1) space (at most three map entries).","code":"int totalFruitBrute(int[] a) {\n     int best = 0;\n     for (int l = 0; l < a.length; l++) {\n         Map<Integer, Integer> freq = new HashMap<>();\n         for (int r = l; r < a.length; r++) {\n             freq.put(a[r], freq.getOrDefault(a[r], 0) + 1);\n             if (freq.size() <= 2) best = Math.max(best, r - l + 1);\n             else break;\n         }\n     }\n     return best;\n }"},{"label":"Optimal","explanation":"Frequency map tracks the window. When a third type appears, shrink from the left until one type disappears. The longest legal window is the answer.","complexity":"O(n) time, O(1) space.","code":"int totalFruit(int[] a) {\n     Map<Integer, Integer> freq = new HashMap<>();\n     int l = 0, best = 0;\n     for (int r = 0; r < a.length; r++) {\n         freq.put(a[r], freq.getOrDefault(a[r], 0) + 1);\n         while (freq.size() > 2) {\n             freq.put(a[l], freq.get(a[l]) - 1);\n             if (freq.get(a[l]) == 0) freq.remove(a[l]);\n             l++;\n         }\n         best = Math.max(best, r - l + 1);\n     }\n     return best;\n }"}]},{"id":50,"title":"Number of Substrings Containing All Three Characters","module":"Sliding Window and Two Pointers","approaches":[{"label":"Brute force","explanation":"Count every substring. A substring is valid when it contains at least one a, one b, and one c.","complexity":"O(n^2) time, O(1) space.","code":"int numberOfSubstringsBrute(String s) {\n     int ans = 0;\n     for (int l = 0; l < s.length(); l++) {\n         boolean[] seen = new boolean[3];\n         int have = 0;\n         for (int r = l; r < s.length(); r++) {\n             int idx = s.charAt(r) - 'a';\n             if (!seen[idx]) { seen[idx] = true; have++; }\n             if (have == 3) ans += s.length() - r;\n             if (have == 3) break;\n         }\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"Track the latest index of a, b, and c. Once all three have been seen up to r, every start from 0 through the earliest of those three indexes forms a valid substring ending at r. Add left + 1.","complexity":"O(n) time, O(1) space.","code":"int numberOfSubstrings(String s) {\n     int[] last = {-1, -1, -1};\n     int ans = 0;\n     for (int i = 0; i < s.length(); i++) {\n         last[s.charAt(i) - 'a'] = i;\n         int left = Math.min(last[0], Math.min(last[1], last[2]));\n         if (left >= 0) ans += left + 1;\n     }\n     return ans;\n }"}]},{"id":51,"title":"Longest Repeating Character Replacement","module":"Sliding Window and Two Pointers","approaches":[{"label":"Brute force","explanation":"Try every substring. Replacements needed equal window length minus the count of the most frequent character inside the window.","complexity":"O(n^2) time, O(1) space.","code":"int characterReplacementBrute(String s, int k) {\n     int best = 0;\n     for (int l = 0; l < s.length(); l++) {\n         int[] freq = new int[26];\n         int most = 0;\n         for (int r = l; r < s.length(); r++) {\n             most = Math.max(most, ++freq[s.charAt(r) - 'A']);\n             if (r - l + 1 - most <= k) best = Math.max(best, r - l + 1);\n         }\n     }\n     return best;\n }"},{"label":"Optimal","explanation":"Inside a window, keep the most frequent character and replace the rest. If replacements exceed k, shrink from the left. An overestimated max frequency never accepts a worse longer window because the best only grows.","complexity":"O(n) time, O(1) space.","code":"int characterReplacement(String s, int k) {\n     int[] freq = new int[26];\n     int l = 0, most = 0, best = 0;\n     for (int r = 0; r < s.length(); r++) {\n         most = Math.max(most, ++freq[s.charAt(r) - 'A']);\n         while (r - l + 1 - most > k) freq[s.charAt(l++) - 'A']--;\n         best = Math.max(best, r - l + 1);\n     }\n     return best;\n }"}]},{"id":52,"title":"Binary Subarrays With Sum","module":"Sliding Window and Two Pointers","approaches":[{"label":"Brute force","explanation":"Count ones in every subarray. Increment the answer when the sum equals goal.","complexity":"O(n^2) time, O(1) space.","code":"int numSubarraysWithSumBrute(int[] a, int goal) {\n     int ans = 0;\n     for (int l = 0; l < a.length; l++) {\n         int sum = 0;\n         for (int r = l; r < a.length; r++) {\n             sum += a[r];\n             if (sum == goal) ans++;\n             if (sum > goal) break;\n         }\n     }\n     return ans;\n }"},{"label":"Better","explanation":"Prefix sums: subarray sum equals pref[r + 1] - pref[l]. For each right end, add how many earlier prefixes gave the needed difference. Works for general arrays, not only binary.","complexity":"O(n) time, O(n) space.","code":"int numSubarraysWithSumPrefix(int[] a, int goal) {\n     int ans = 0, sum = 0;\n     Map<Integer, Integer> cnt = new HashMap<>();\n     cnt.put(0, 1);\n     for (int x : a) {\n         sum += x;\n         ans += cnt.getOrDefault(sum - goal, 0);\n         cnt.put(sum, cnt.getOrDefault(sum, 0) + 1);\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"On a binary array, count subarrays with sum at most goal by shrinking while sum exceeds goal; each right end contributes r - l + 1 starts. Exactly goal is atMost(goal) - atMost(goal - 1).","complexity":"O(n) time, O(1) space.","code":"int numSubarraysWithSum(int[] a, int goal) {\n     return atMost(a, goal) - atMost(a, goal - 1);\n }\n int atMost(int[] a, int goal) {\n     if (goal < 0) return 0;\n     int l = 0, sum = 0, ans = 0;\n     for (int r = 0; r < a.length; r++) {\n         sum += a[r];\n         while (sum > goal) sum -= a[l++];\n         ans += r - l + 1;\n     }\n     return ans;\n }"}]},{"id":53,"title":"Subset Sums","module":"Recursion and Backtracking","approaches":[{"label":"Brute force","explanation":"Every subset is a bitmask from 0 to 2^n - 1. Sum the elements whose bit is set and collect all sums. Sort at the end if the statement wants ordered output.","complexity":"O(2^n * n) time, O(2^n) space for answers.","code":"List<Integer> subsetSumsBrute(int[] a) {\n     List<Integer> ans = new ArrayList<>();\n     int n = a.length;\n     for (int mask = 0; mask < (1 << n); mask++) {\n         int sum = 0;\n         for (int i = 0; i < n; i++)\n             if ((mask & (1 << i)) != 0) sum += a[i];\n         ans.add(sum);\n     }\n     Collections.sort(ans);\n     return ans;\n }"},{"label":"Optimal","explanation":"Recurse on the next index twice: once adding a[i], once skipping it. Each finished path records one subset sum.","complexity":"O(2^n) time, O(n) recursion stack.","code":"List<Integer> subsetSums(int[] a) {\n     List<Integer> ans = new ArrayList<>();\n     collect(a, 0, 0, ans);\n     Collections.sort(ans);\n     return ans;\n }\n void collect(int[] a, int i, int sum, List<Integer> ans) {\n     if (i == a.length) { ans.add(sum); return; }\n     collect(a, i + 1, sum + a[i], ans);\n     collect(a, i + 1, sum, ans);\n }"}]},{"id":54,"title":"Subsets II","module":"Recursion and Backtracking","approaches":[{"label":"Brute force","explanation":"Generate every subset via bitmask, convert to lists, sort each list and the outer list, then drop duplicates with a set or linear scan. Correct but wasteful on duplicate-heavy input.","complexity":"O(2^n * n log n) time, O(2^n * n) space.","code":"List<List<Integer>> subsetsWithDupBrute(int[] a) {\n     Set<String> keys = new HashSet<>();\n     List<List<Integer>> ans = new ArrayList<>();\n     int n = a.length;\n     for (int mask = 0; mask < (1 << n); mask++) {\n         List<Integer> cur = new ArrayList<>();\n         for (int i = 0; i < n; i++)\n             if ((mask & (1 << i)) != 0) cur.add(a[i]);\n         Collections.sort(cur);\n         String key = cur.toString();\n         if (keys.add(key)) ans.add(cur);\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"Sort so equal values sit together. At each level skip duplicate siblings: if a[i] equals a[i - 1] and i > start, continue. That drops duplicate subsets while still allowing several copies when chosen in order.","complexity":"O(2^n * n) time, O(n) stack.","code":"List<List<Integer>> subsetsWithDup(int[] a) {\n     Arrays.sort(a);\n     List<List<Integer>> ans = new ArrayList<>();\n     build(a, 0, new ArrayList<>(), ans);\n     return ans;\n }\n void build(int[] a, int start, List<Integer> cur, List<List<Integer>> ans) {\n     ans.add(new ArrayList<>(cur));\n     for (int i = start; i < a.length; i++) {\n         if (i > start && a[i] == a[i - 1]) continue;\n         cur.add(a[i]);\n         build(a, i + 1, cur, ans);\n         cur.remove(cur.size() - 1);\n     }\n }"}]},{"id":55,"title":"Combination Sum","module":"Recursion and Backtracking","approaches":[{"label":"Brute force","explanation":"For each candidate, try using it 0, 1, 2, ... times up to target / a[i], then move to the next index. Every count vector is explored; no take-or-skip shortcut at the same index.","complexity":"Exponential in target, O(target / min) stack.","code":"List<List<Integer>> combinationSumBrute(int[] a, int target) {\n     List<List<Integer>> ans = new ArrayList<>();\n     countPick(a, 0, target, new ArrayList<>(), ans);\n     return ans;\n }\n void countPick(int[] a, int i, int left, List<Integer> cur, List<List<Integer>> ans) {\n     if (left == 0) { ans.add(new ArrayList<>(cur)); return; }\n     if (i == a.length || left < 0) return;\n     for (int take = 0; take * a[i] <= left; take++) {\n         for (int t = 0; t < take; t++) cur.add(a[i]);\n         countPick(a, i + 1, left - take * a[i], cur, ans);\n         for (int t = 0; t < take; t++) cur.remove(cur.size() - 1);\n     }\n }"},{"label":"Optimal","explanation":"Candidates may be reused, but order does not matter, so each recursive call only looks at indexes >= the one just chosen. Subtract the chosen value from the remaining target; undo before trying skip.","complexity":"Exponential in the target, O(target / min) stack.","code":"List<List<Integer>> combinationSum(int[] a, int target) {\n     List<List<Integer>> ans = new ArrayList<>();\n     pick(a, 0, target, new ArrayList<>(), ans);\n     return ans;\n }\n void pick(int[] a, int i, int left, List<Integer> cur, List<List<Integer>> ans) {\n     if (left == 0) { ans.add(new ArrayList<>(cur)); return; }\n     if (i == a.length || left < 0) return;\n     cur.add(a[i]);\n     pick(a, i, left - a[i], cur, ans);\n     cur.remove(cur.size() - 1);\n     pick(a, i + 1, left, cur, ans);\n }"}]},{"id":56,"title":"Combination Sum II","module":"Recursion and Backtracking","approaches":[{"label":"Brute force","explanation":"Sort candidates and enumerate subsets that use each index at most once via bitmask. Keep subsets whose sum equals target; deduplicate by encoding sorted lists as strings.","complexity":"O(2^n * n) time, O(2^n) space.","code":"List<List<Integer>> combinationSum2Brute(int[] a, int target) {\n     Arrays.sort(a);\n     Set<String> keys = new HashSet<>();\n     List<List<Integer>> ans = new ArrayList<>();\n     int n = a.length;\n     for (int mask = 1; mask < (1 << n); mask++) {\n         List<Integer> cur = new ArrayList<>();\n         int sum = 0;\n         for (int i = 0; i < n; i++)\n             if ((mask & (1 << i)) != 0) { cur.add(a[i]); sum += a[i]; }\n         if (sum != target) continue;\n         String key = cur.toString();\n         if (keys.add(key)) ans.add(cur);\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"Each element is used at most once, so the next call starts at i + 1. Skip duplicate values at the same recursion depth after sorting.","complexity":"O(2^n) time, O(n) stack.","code":"List<List<Integer>> combinationSum2(int[] a, int target) {\n     Arrays.sort(a);\n     List<List<Integer>> ans = new ArrayList<>();\n     pick(a, 0, target, new ArrayList<>(), ans);\n     return ans;\n }\n void pick(int[] a, int start, int left, List<Integer> cur, List<List<Integer>> ans) {\n     if (left == 0) { ans.add(new ArrayList<>(cur)); return; }\n     for (int i = start; i < a.length && a[i] <= left; i++) {\n         if (i > start && a[i] == a[i - 1]) continue;\n         cur.add(a[i]);\n         pick(a, i + 1, left - a[i], cur, ans);\n         cur.remove(cur.size() - 1);\n     }\n }"}]},{"id":57,"title":"Palindrome Partitioning","module":"Recursion and Backtracking","approaches":[{"label":"Brute force","explanation":"There  are  2^(n-1)  ways  to  place  cuts  between  characters.  Encode  cuts  as  a  bitmask,  split  the  string,  and  keep partitions where every piece is a palindrome.","complexity":"O(2^n * n) time, O(n) stack.","code":"List<List<String>> partitionBrute(String s) {\n     List<List<String>> ans = new ArrayList<>();\n     int n = s.length();\n     for (int mask = 0; mask < (1 << (n - 1)); mask++) {\n         List<String> parts = new ArrayList<>();\n         int start = 0;\n         boolean ok = true;\n         for (int i = 0; i < n - 1; i++) {\n             if ((mask & (1 << i)) != 0) {\n                 String piece = s.substring(start, i + 1);\n                 if (!isPal(piece)) { ok = false; break; }\n                 parts.add(piece);\n                 start = i + 1;\n             }\n         }\n         if (!ok) continue;\n         String last = s.substring(start);\n         if (isPal(last)) {\n             parts.add(last);\n             ans.add(parts);\n         }\n     }\n     return ans;\n }\n boolean isPal(String t) {\n     int l = 0, r = t.length() - 1;\n     while (l < r) if (t.charAt(l++) != t.charAt(r--)) return false;\n     return true;\n }"},{"label":"Better","explanation":"Backtrack cuts: from start, try every end where s[start..end] is a palindrome, append the piece, recurse from end + 1, then undo.","complexity":"O(n * 2^n) time, O(n) stack.","code":"List<List<String>> partition(String s) {\n     List<List<String>> ans = new ArrayList<>();\n     cut(s, 0, new ArrayList<>(), ans);\n     return ans;\n }\n void cut(String s, int start, List<String> cur, List<List<String>> ans) {\n     if (start == s.length()) { ans.add(new ArrayList<>(cur)); return; }\n     for (int end = start; end < s.length(); end++) {\n         if (!isPal(s, start, end)) continue;\n         cur.add(s.substring(start, end + 1));\n         cut(s, end + 1, cur, ans);\n         cur.remove(cur.size() - 1);\n     }\n }\n boolean isPal(String s, int l, int r) {\n     while (l < r) if (s.charAt(l++) != s.charAt(r--)) return false;\n     return true;\n }"},{"label":"Optimal","explanation":"Precompute isPal[l][r] in O(n^2). Backtracking then checks palindromes in O(1), which matters when the recursion tree is large.","complexity":"O(n^2 + n * 2^n) time, O(n^2) space for the table.","code":"List<List<String>> partition(String s) {\n     int n = s.length();\n     boolean[][] pal = new boolean[n][n];\n     for (int i = n - 1; i >= 0; i--)\n         for (int j = i; j < n; j++)\n             pal[i][j] = s.charAt(i) == s.charAt(j) && (j - i < 2 || pal[i + 1][j - 1]);\n     List<List<String>> ans = new ArrayList<>();\n     cut(s, 0, pal, new ArrayList<>(), ans);\n     return ans;\n }\n void cut(String s, int start, boolean[][] pal, List<String> cur, List<List<String>> ans) {\n     if (start == s.length()) { ans.add(new ArrayList<>(cur)); return; }\n     for (int end = start; end < s.length(); end++) {\n         if (!pal[start][end]) continue;\n         cur.add(s.substring(start, end + 1));\n         cut(s, end + 1, pal, cur, ans);\n         cur.remove(cur.size() - 1);\n     }\n }"}]},{"id":58,"title":"Permutations","module":"Recursion and Backtracking","approaches":[{"label":"Brute force","explanation":"Sort  a  copy  of  the  array  and  repeatedly  apply  next-permutation  until  the  sequence  wraps.  Each  step  is  one  full permutation.","complexity":"O(n * n!) time, O(n) space.","code":"List<List<Integer>> permuteBrute(int[] a) {\n     int[] b = a.clone();\n     Arrays.sort(b);\n     List<List<Integer>> ans = new ArrayList<>();\n     do {\n         List<Integer> row = new ArrayList<>();\n         for (int x : b) row.add(x);\n         ans.add(row);\n     } while (nextPerm(b));\n     return ans;\n }\n boolean nextPerm(int[] a) {\n     int i = a.length - 2;\n     while (i >= 0 && a[i] >= a[i + 1]) i--;\n     if (i < 0) return false;\n     int j = a.length - 1;\n     while (a[j] <= a[i]) j--;\n     int t = a[i]; a[i] = a[j]; a[j] = t;\n     for (int l = i + 1, r = a.length - 1; l < r; l++, r--) {\n         t = a[l]; a[l] = a[r]; a[r] = t;\n     }\n     return true;\n }"},{"label":"Better","explanation":"Fill position i by trying every unused value. A boolean used[] marks occupancy; undo the mark after the recursive call.","complexity":"O(n * n!) time, O(n) stack.","code":"List<List<Integer>> permuteUsed(int[] a) {\n     List<List<Integer>> ans = new ArrayList<>();\n     boolean[] used = new boolean[a.length];\n     build(a, used, new ArrayList<>(), ans);\n     return ans;\n }\n void build(int[] a, boolean[] used, List<Integer> cur, List<List<Integer>> ans) {\n     if (cur.size() == a.length) { ans.add(new ArrayList<>(cur)); return; }\n     for (int i = 0; i < a.length; i++) {\n         if (used[i]) continue;\n         used[i] = true;\n         cur.add(a[i]);\n         build(a, used, cur, ans);\n         cur.remove(cur.size() - 1);\n         used[i] = false;\n     }\n }"},{"label":"Optimal","explanation":"Swap a[i] with each later choice to place the next element, recurse to i + 1, then swap back so the array is restored for the next branch.","complexity":"O(n * n!) time, O(n) stack.","code":"List<List<Integer>> permute(int[] a) {\n     List<List<Integer>> ans = new ArrayList<>();\n     perm(a, 0, ans);\n     return ans;\n }\n void perm(int[] a, int i, List<List<Integer>> ans) {\n     if (i == a.length) {\n         List<Integer> row = new ArrayList<>();\n         for (int x : a) row.add(x);\n         ans.add(row);\n         return;\n     }\n     for (int j = i; j < a.length; j++) {\n         int t = a[i]; a[i] = a[j]; a[j] = t;\n         perm(a, i + 1, ans);\n         t = a[i]; a[i] = a[j]; a[j] = t;\n     }\n }"}]},{"id":59,"title":"Kth Permutation Sequence","module":"Recursion and Backtracking","approaches":[{"label":"Brute force","explanation":"Generate  permutations  in  lex  order  with  next-permutation  and  return  the  kth  (1-based).  Stops  as  soon  as  the counter reaches k.","complexity":"O(n * k) time in typical cases, O(n * n!) worst case, O(n) space.","code":"String getPermutationBrute(int n, int k) {\n     int[] a = new int[n];\n     for (int i = 0; i < n; i++) a[i] = i + 1;\n     for (int step = 1; step < k; step++)\n         if (!nextPerm(a)) break;\n     StringBuilder sb = new StringBuilder();\n     for (int x : a) sb.append(x);\n     return sb.toString();\n }\n boolean nextPerm(int[] a) {\n     int i = a.length - 2;\n     while (i >= 0 && a[i] >= a[i + 1]) i--;\n     if (i < 0) return false;\n     int j = a.length - 1;\n     while (a[j] <= a[i]) j--;\n     int t = a[i]; a[i] = a[j]; a[j] = t;\n     for (int l = i + 1, r = a.length - 1; l < r; l++, r--) {\n         t = a[l]; a[l] = a[r]; a[r] = t;\n     }\n     return true;\n }"},{"label":"Optimal","explanation":"There are (n - 1)! permutations for each first digit. Pick index k / (n - 1)! from the remaining list, set k to k % (n - 1)!, and repeat. Direct construction without enumerating all n! orders.","complexity":"O(n^2) time, O(n) space.","code":"String getPermutation(int n, int k) {\n     List<Integer> nums = new ArrayList<>();\n     int fact = 1;\n     for (int i = 1; i <= n; i++) { nums.add(i); fact *= i; }\n     k--;\n     StringBuilder sb = new StringBuilder();\n     for (int left = n; left >= 1; left--) {\n         fact /= left;\n         int idx = k / fact;\n         sb.append(nums.remove(idx));\n         k %= fact;\n     }\n     return sb.toString();\n }"}]},{"id":60,"title":"N-Queens","module":"Recursion and Backtracking","approaches":[{"label":"Brute force","explanation":"Place a queen in every cell of row r and recurse. Reject a placement when any two queens share a row, column, or diagonal. No column/diagonal bitmask pruning beyond checking the board.","complexity":"O(n^n) time worst case, O(n^2) space.","code":"List<List<String>> solveNQueensBrute(int n) {\n     List<List<String>> ans = new ArrayList<>();\n     char[][] b = new char[n][n];\n     for (char[] row : b) Arrays.fill(row, '.');\n     placeBrute(0, n, b, ans);\n     return ans;\n }\n void placeBrute(int r, int n, char[][] b, List<List<String>> ans) {\n     if (r == n) {\n         List<String> one = new ArrayList<>();\n         for (char[] row : b) one.add(new String(row));\n         ans.add(one);\n         return;\n     }\n     for (int c = 0; c < n; c++) {\n         if (!safe(b, r, c, n)) continue;\n         b[r][c] = 'Q';\n         placeBrute(r + 1, n, b, ans);\n         b[r][c] = '.';\n     }\n }\n boolean safe(char[][] b, int r, int c, int n) {\n     for (int i = 0; i < r; i++)\n         for (int j = 0; j < n; j++)\n             if (b[i][j] == 'Q' && (j == c || i - j == r - c || i + j == r + c))\n                 return false;\n     return true;\n }"},{"label":"Optimal","explanation":"One  queen  per  row.  Track  used  columns  and  both  diagonal  families  with  boolean  arrays;  place,  mark,  recurse, unmark.","complexity":"O(n!) time, O(n) extra space.","code":"List<List<String>> solveNQueens(int n) {\n     List<List<String>> ans = new ArrayList<>();\n     char[][] b = new char[n][n];\n     for (char[] row : b) Arrays.fill(row, '.');\n     place(0, n, b, new boolean[n], new boolean[2 * n], new boolean[2 * n], ans);\n     return ans;\n }\n void place(int r, int n, char[][] b, boolean[] col, boolean[] d1, boolean[] d2,\n            List<List<String>> ans) {\n     if (r == n) {\n         List<String> one = new ArrayList<>();\n         for (char[] row : b) one.add(new String(row));\n         ans.add(one);\n         return;\n     }\n     for (int c = 0; c < n; c++) {\n         int x = r - c + n - 1, y = r + c;\n         if (col[c] || d1[x] || d2[y]) continue;\n         col[c] = d1[x] = d2[y] = true;\n         b[r][c] = 'Q';\n         place(r + 1, n, b, col, d1, d2, ans);\n         b[r][c] = '.';\n         col[c] = d1[x] = d2[y] = false;\n     }\n }"}]},{"id":61,"title":"Sudoku Solver","module":"Recursion and Backtracking","approaches":[{"label":"Brute force","explanation":"Collect every empty cell. Try digits 1 through 9 at each empty in order, recurse to the next empty, and backtrack on failure. Row/column/box checks run from scratch each time.","complexity":"Exponential, O(1) extra space besides the stack.","code":"boolean solveSudokuBrute(char[][] b) {\n     List<int[]> empty = new ArrayList<>();\n     for (int r = 0; r < 9; r++)\n         for (int c = 0; c < 9; c++)\n             if (b[r][c] == '.') empty.add(new int[]{r, c});\n     return fill(b, empty, 0);\n }\n boolean fill(char[][] b, List<int[]> empty, int idx) {\n     if (idx == empty.size()) return true;\n     int r = empty.get(idx)[0], c = empty.get(idx)[1];\n     for (char d = '1'; d <= '9'; d++) {\n         if (!ok(b, r, c, d)) continue;\n         b[r][c] = d;\n         if (fill(b, empty, idx + 1)) return true;\n         b[r][c] = '.';\n     }\n     return false;\n }\n boolean ok(char[][] b, int r, int c, char d) {\n     for (int i = 0; i < 9; i++) {\n         if (b[r][i] == d || b[i][c] == d) return false;\n         int br = 3 * (r / 3) + i / 3, bc = 3 * (c / 3) + i % 3;\n         if (b[br][bc] == d) return false;\n     }\n     return true;\n }"},{"label":"Optimal","explanation":"Scan for the next '.' and try legal digits with the same ok test. First complete assignment wins; typical boards prune heavily so this in-place scan is standard.","complexity":"Exponential, pruning makes typical boards small. O(1) extra space besides the stack.","code":"boolean solveSudoku(char[][] b) {\n     for (int r = 0; r < 9; r++) {\n         for (int c = 0; c < 9; c++) {\n             if (b[r][c] != '.') continue;\n             for (char d = '1'; d <= '9'; d++) {\n                 if (!ok(b, r, c, d)) continue;\n                 b[r][c] = d;\n                 if (solveSudoku(b)) return true;\n                 b[r][c] = '.';\n             }\n             return false;\n         }\n     }\n     return true;\n }\n boolean ok(char[][] b, int r, int c, char d) {\n     for (int i = 0; i < 9; i++) {\n         if (b[r][i] == d || b[i][c] == d) return false;\n         int br = 3 * (r / 3) + i / 3, bc = 3 * (c / 3) + i % 3;\n         if (b[br][bc] == d) return false;\n     }\n     return true;\n }"}]},{"id":62,"title":"M-Coloring","module":"Recursion and Backtracking","approaches":[{"label":"Brute force","explanation":"Assign  colors  1..m  to  vertices  in  order  without  checking  neighbors  mid-search.  When  all  vertices  are  colored, validate every edge. Backtrack only after a full assignment fails.","complexity":"O(m^n * n) worst case, O(n) stack.","code":"boolean graphColoringBrute(boolean[][] graph, int m) {\n     int n = graph.length;\n     int[] color = new int[n];\n     return assignAll(graph, color, 0, m);\n }\n boolean assignAll(boolean[][] g, int[] color, int v, int m) {\n     if (v == g.length) return coloringValid(g, color);\n     for (int c = 1; c <= m; c++) {\n         color[v] = c;\n         if (assignAll(g, color, v + 1, m)) return true;\n     }\n     color[v] = 0;\n     return false;\n }\n boolean coloringValid(boolean[][] g, int[] color) {\n     for (int v = 0; v < g.length; v++)\n         for (int u = v + 1; u < g.length; u++)\n             if (g[v][u] && color[v] == color[u]) return false;\n     return true;\n }"},{"label":"Optimal","explanation":"Color vertices in order. Before recursing, only try colors that no neighbor already uses. Undo on failure.","complexity":"O(m^n * n) worst case, O(n) stack.","code":"boolean graphColoring(boolean[][] graph, int m) {\n     return paint(graph, new int[graph.length], 0, m);\n }\n boolean paint(boolean[][] g, int[] color, int v, int m) {\n     if (v == g.length) return true;\n     for (int c = 1; c <= m; c++) {\n         boolean ok = true;\n         for (int u = 0; u < g.length; u++)\n             if (g[v][u] && color[u] == c) ok = false;\n         if (!ok) continue;\n         color[v] = c;\n         if (paint(g, color, v + 1, m)) return true;\n         color[v] = 0;\n     }\n     return false;\n }"}]},{"id":63,"title":"Rat in a Maze","module":"Recursion and Backtracking","approaches":[{"label":"Brute force","explanation":"DFS from (0, 0) with a separate visited matrix copied at each step so every path exploration is independent. Collect path strings when (n - 1, n - 1) is reached.","complexity":"O(4^(n^2)) worst case, O(n^2) stack depth.","code":"List<String> findPathBrute(int[][] maze) {\n     List<String> ans = new ArrayList<>();\n     int n = maze.length;\n     if (maze[0][0] == 0 || maze[n - 1][n - 1] == 0) return ans;\n     walkBrute(maze, 0, 0, new boolean[n][n], new StringBuilder(), ans);\n     return ans;\n }\n void walkBrute(int[][] a, int r, int c, boolean[][] vis, StringBuilder path,\n                List<String> ans) {\n     int n = a.length;\n     if (r == n - 1 && c == n - 1) { ans.add(path.toString()); return; }\n     vis[r][c] = true;\n     int[] dr = {1, 0, 0, -1};\n     int[] dc = {0, -1, 1, 0};\n     char[] dir = {'D', 'L', 'R', 'U'};\n     for (int k = 0; k < 4; k++) {\n         int nr = r + dr[k], nc = c + dc[k];\n         if (nr < 0 || nc < 0 || nr >= n || nc >= n || a[nr][nc] == 0 || vis[nr][nc])\n             continue;\n         path.append(dir[k]);\n         walkBrute(a, nr, nc, vis, path, ans);\n         path.deleteCharAt(path.length() - 1);\n     }\n     vis[r][c] = false;\n }"},{"label":"Optimal","explanation":"Mark the current cell blocked on the grid, try D/L/R/U in order, append the direction letter, then restore the cell and remove the letter on backtrack.","complexity":"O(4^(n^2)) worst case, O(n^2) stack.","code":"List<String> findPath(int[][] maze) {\n     List<String> ans = new ArrayList<>();\n     int n = maze.length;\n     if (maze[0][0] == 0 || maze[n - 1][n - 1] == 0) return ans;\n     walk(maze, 0, 0, new StringBuilder(), ans);\n     return ans;\n }\n void walk(int[][] a, int r, int c, StringBuilder path, List<String> ans) {\n     int n = a.length;\n     if (r == n - 1 && c == n - 1) { ans.add(path.toString()); return; }\n     a[r][c] = 0;\n     int[] dr = {1, 0, 0, -1};\n     int[] dc = {0, -1, 1, 0};\n     char[] dir = {'D', 'L', 'R', 'U'};\n     for (int k = 0; k < 4; k++) {\n         int nr = r + dr[k], nc = c + dc[k];\n         if (nr < 0 || nc < 0 || nr >= n || nc >= n || a[nr][nc] == 0) continue;\n         path.append(dir[k]);\n         walk(a, nr, nc, path, ans);\n         path.deleteCharAt(path.length() - 1);\n     }\n     a[r][c] = 1;\n }"}]},{"id":64,"title":"Word Search","module":"Recursion and Backtracking","approaches":[{"label":"Brute force","explanation":"From every cell matching the first letter, DFS with a fresh visited[][] so paths cannot reuse a cell. Try four directions for each next character.","complexity":"O(n * m * 4^L) time, O(L) stack, L = word length.","code":"boolean existBrute(char[][] board, String word) {\n     int rows = board.length, cols = board[0].length;\n     for (int r = 0; r < rows; r++)\n         for (int c = 0; c < cols; c++)\n             if (board[r][c] == word.charAt(0)\n                     && dfsBrute(board, word, 0, r, c, new boolean[rows][cols]))\n                 return true;\n     return false;\n }\n boolean dfsBrute(char[][] b, String w, int i, int r, int c, boolean[][] vis) {\n     if (i == w.length()) return true;\n     if (r < 0 || c < 0 || r >= b.length || c >= b[0].length) return false;\n     if (vis[r][c] || b[r][c] != w.charAt(i)) return false;\n     vis[r][c] = true;\n     boolean ok = dfsBrute(b, w, i + 1, r + 1, c, vis) || dfsBrute(b, w, i + 1, r - 1, c, vis)\n               || dfsBrute(b, w, i + 1, r, c + 1, vis) || dfsBrute(b, w, i + 1, r, c - 1, vis);\n     vis[r][c] = false;\n     return ok;\n }"},{"label":"Optimal","explanation":"Same DFS from each matching start, but mark the cell with a sentinel on the board and restore it after the call. That avoids allocating a visited matrix per path.","complexity":"O(n * m * 4^L) time, O(L) stack, L = word length.","code":"boolean exist(char[][] board, String word) {\n     for (int r = 0; r < board.length; r++)\n         for (int c = 0; c < board[0].length; c++)\n             if (dfs(board, word, 0, r, c)) return true;\n     return false;\n }\n boolean dfs(char[][] b, String w, int i, int r, int c) {\n     if (i == w.length()) return true;\n     if (r < 0 || c < 0 || r >= b.length || c >= b[0].length) return false;\n     if (b[r][c] != w.charAt(i)) return false;\n     char saved = b[r][c];\n     b[r][c] = '#';\n     boolean ok = dfs(b, w, i + 1, r + 1, c) || dfs(b, w, i + 1, r - 1, c)\n               || dfs(b, w, i + 1, r, c + 1) || dfs(b, w, i + 1, r, c - 1);\n     b[r][c] = saved;\n     return ok;\n }"}]},{"id":65,"title":"Reverse a Linked List","module":"Linked List","approaches":[{"label":"Brute force","explanation":"Walk the list once and push every value onto a stack. Pop the stack into new nodes chained from a dummy head. Order is reversed without touching original links, at the cost of extra storage and a new list.","complexity":"O(n) time, O(n) space.","code":"ListNode reverseListBrute(ListNode head) {\n     Deque<Integer> st = new ArrayDeque<>();\n     for (ListNode cur = head; cur != null; cur = cur.next) st.push(cur.val);\n     ListNode dummy = new ListNode(0), tail = dummy;\n     while (!st.isEmpty()) {\n         tail.next = new ListNode(st.pop());\n         tail = tail.next;\n     }\n     return dummy.next;\n }"},{"label":"Better","explanation":"Recursion reverses the suffix after head, then attaches head at the tail of that suffix. The base case is null or a single node. Each call uses O(n) stack depth.","complexity":"O(n) time, O(n) recursion stack.","code":"ListNode reverseListRec(ListNode head) {\n     if (head == null || head.next == null) return head;\n     ListNode newHead = reverseListRec(head.next);\n     head.next.next = head;\n     head.next = null;\n     return newHead;\n }"},{"label":"Optimal","explanation":"Three pointers: previous, current, next. Each node must point at the node that used to precede it. Save cur.next before  overwriting  it,  point  cur  at  prev,  then  step  both  forward.  At  the  end  prev  is  the  new  head.  Empty  and one-node lists need no special case.","complexity":"O(n) time, O(1) space.","code":"ListNode reverseList(ListNode head) {\n     ListNode prev = null, cur = head;\n     while (cur != null) {\n         ListNode nxt = cur.next;\n         cur.next = prev;\n         prev = cur;\n         cur = nxt;\n     }\n     return prev;\n }"}]},{"id":66,"title":"Middle of a Linked List","module":"Linked List","approaches":[{"label":"Brute force","explanation":"Count nodes in one pass, then walk again stopping after count / 2 steps. Correct but touches the list twice.","complexity":"O(n) time, O(1) space.","code":"ListNode middleNodeCount(ListNode head) {\n     int n = 0;\n     for (ListNode cur = head; cur != null; cur = cur.next) n++;\n     ListNode cur = head;\n     for (int i = 0; i < n / 2; i++) cur = cur.next;\n     return cur;\n }"},{"label":"Optimal","explanation":"Fast moves two steps, slow moves one. When fast reaches the end, slow has covered half as many nodes. For even length, slow lands on the second middle. One pass, no length count.","complexity":"O(n) time, O(1) space.","code":"ListNode middleNode(ListNode head) {\n     ListNode slow = head, fast = head;\n     while (fast != null && fast.next != null) {\n         slow = slow.next;\n         fast = fast.next.next;\n     }\n     return slow;\n }"}]},{"id":67,"title":"Merge Two Sorted Lists","module":"Linked List","approaches":[{"label":"Brute force","explanation":"Copy all values from both lists into an array, sort it, then build a fresh list from the sorted values. Ignores that the inputs were already sorted.","complexity":"O((n + m) log(n + m)) time, O(n + m) space.","code":"ListNode mergeTwoListsBrute(ListNode a, ListNode b) {\n     List<Integer> vals = new ArrayList<>();\n     for (ListNode cur = a; cur != null; cur = cur.next) vals.add(cur.val);\n     for (ListNode cur = b; cur != null; cur = cur.next) vals.add(cur.val);\n     Collections.sort(vals);\n     ListNode dummy = new ListNode(0), tail = dummy;\n     for (int v : vals) {\n         tail.next = new ListNode(v);\n         tail = tail.next;\n     }\n     return dummy.next;\n }"},{"label":"Optimal","explanation":"Dummy head, always attach the smaller node. While both lists remain, attach the smaller head and advance that list. Attach whichever list is left in one assignment. Return dummy.next.","complexity":"O(n + m) time, O(1) space.","code":"ListNode mergeTwoLists(ListNode a, ListNode b) {\n     ListNode dummy = new ListNode(0), tail = dummy;\n     while (a != null && b != null) {\n         if (a.val <= b.val) { tail.next = a; a = a.next; }\n         else { tail.next = b; b = b.next; }\n         tail = tail.next;\n     }\n     tail.next = a != null ? a : b;\n     return dummy.next;\n }"}]},{"id":68,"title":"Remove Nth Node From End","module":"Linked List","approaches":[{"label":"Brute force","explanation":"Count the length, then delete the node at index length - n from the head using a dummy to handle deleting the head.","complexity":"O(n) time, O(1) space.","code":"ListNode removeNthFromEndCount(ListNode head, int n) {\n     int len = 0;\n     for (ListNode cur = head; cur != null; cur = cur.next) len++;\n     ListNode dummy = new ListNode(0);\n     dummy.next = head;\n     ListNode cur = dummy;\n     for (int i = 0; i < len - n; i++) cur = cur.next;\n     cur.next = cur.next.next;\n     return dummy.next;\n }"},{"label":"Optimal","explanation":"Gap of n between two pointers, plus a dummy. Advance fast n steps, then move slow and fast together until fast reaches the end. Slow stands on the node before the one to delete. Dummy handles deleting the original head.","complexity":"O(n) time, O(1) space.","code":"ListNode removeNthFromEnd(ListNode head, int n) {\n     ListNode dummy = new ListNode(0);\n     dummy.next = head;\n     ListNode fast = dummy, slow = dummy;\n     for (int i = 0; i < n; i++) fast = fast.next;\n     while (fast.next != null) { fast = fast.next; slow = slow.next; }\n     slow.next = slow.next.next;\n     return dummy.next;\n }"}]},{"id":69,"title":"Add Two Numbers","module":"Linked List","approaches":[{"label":"Better","explanation":"Same digit-by-digit addition as the iterative version, expressed recursively on the tails after consuming one digit from each list and the carry.","complexity":"O(max(n, m)) time, O(max(n, m)) space for the answer and recursion.","code":"ListNode addTwoNumbersRec(ListNode a, ListNode b, int carry) {\n     if (a == null && b == null && carry == 0) return null;\n     int sum = carry;\n     if (a != null) { sum += a.val; a = a.next; }\n     if (b != null) { sum += b.val; b = b.next; }\n     ListNode node = new ListNode(sum % 10);\n     node.next = addTwoNumbersRec(a, b, sum / 10);\n     return node;\n }\n ListNode addTwoNumbers(ListNode a, ListNode b) {\n     return addTwoNumbersRec(a, b, 0);\n }"},{"label":"Optimal","explanation":"Both lists store digits least-significant first. Add the two digits plus carry, write sum % 10 as the next node, keep sum / 10 as carry. Continue while either list or carry remains.","complexity":"O(max(n, m)) time, O(max(n, m)) space for the answer.","code":"ListNode addTwoNumbers(ListNode a, ListNode b) {\n     ListNode dummy = new ListNode(0), tail = dummy;\n     int carry = 0;\n     while (a != null || b != null || carry != 0) {\n         int sum = carry;\n         if (a != null) { sum += a.val; a = a.next; }\n         if (b != null) { sum += b.val; b = b.next; }\n         tail.next = new ListNode(sum % 10);\n         tail = tail.next;\n         carry = sum / 10;\n     }\n     return dummy.next;\n }"}]},{"id":70,"title":"Delete a Node When Only That Node Is Given","module":"Linked List","approaches":[{"label":"Optimal","explanation":"The previous node is unknown and the node is not the tail. Copy the successor's value into this node and bypass the successor. The list values match deletion; the original node object remains.","complexity":"O(1) time, O(1) space.","code":"void deleteNode(ListNode node) {\n     node.val = node.next.val;\n     node.next = node.next.next;\n }"}]},{"id":71,"title":"Intersection of Two Linked Lists","module":"Linked List","approaches":[{"label":"Brute force","explanation":"For every node in list A, walk list B and compare references. First match is the intersection. Simple but quadratic when lists are long with no shared tail.","complexity":"O(n * m) time, O(1) space.","code":"ListNode getIntersectionNodeBrute(ListNode a, ListNode b) {\n     for (ListNode p = a; p != null; p = p.next)\n         for (ListNode q = b; q != null; q = q.next)\n             if (p == q) return p;\n     return null;\n }"},{"label":"Optimal","explanation":"Switch heads when a pointer finishes. Both walk a + b + c steps before entering the shared tail together, or both become null if there is no intersection.","complexity":"O(n + m) time, O(1) space.","code":"ListNode getIntersectionNode(ListNode a, ListNode b) {\n     ListNode p = a, q = b;\n     while (p != q) {\n         p = p == null ? b : p.next;\n         q = q == null ? a : q.next;\n     }\n     return p;\n }"}]},{"id":72,"title":"Detect a Cycle","module":"Linked List","approaches":[{"label":"Brute force","explanation":"Track visited nodes in a hash set while walking. The first repeat means a cycle; reaching null means none.","complexity":"O(n) time, O(n) space.","code":"boolean hasCycleHash(ListNode head) {\n     Set<ListNode> seen = new HashSet<>();\n     for (ListNode cur = head; cur != null; cur = cur.next) {\n         if (!seen.add(cur)) return true;\n     }\n     return false;\n }"},{"label":"Optimal","explanation":"Floyd: slow and fast. Inside a cycle, fast gains one step on slow each iteration until they meet. If fast reaches null, there is no cycle.","complexity":"O(n) time, O(1) space.","code":"boolean hasCycle(ListNode head) {\n     ListNode slow = head, fast = head;\n     while (fast != null && fast.next != null) {\n         slow = slow.next;\n         fast = fast.next.next;\n         if (slow == fast) return true;\n     }\n     return false;\n }"}]},{"id":73,"title":"Starting Point of the Cycle","module":"Linked List","approaches":[{"label":"Brute force","explanation":"Record each node in a hash set on first visit. The first node seen twice is the cycle entrance.","complexity":"O(n) time, O(n) space.","code":"ListNode detectCycleHash(ListNode head) {\n     Set<ListNode> seen = new HashSet<>();\n     for (ListNode cur = head; cur != null; cur = cur.next) {\n         if (!seen.add(cur)) return cur;\n     }\n     return null;\n }"},{"label":"Optimal","explanation":"After Floyd finds a meeting point, reset one pointer to the head and advance both one step at a time. They meet at the cycle entrance because the stem length equals the distance from the meeting point to the entrance along the cycle.","complexity":"O(n) time, O(1) space.","code":"ListNode detectCycle(ListNode head) {\n     ListNode slow = head, fast = head;\n     while (fast != null && fast.next != null) {\n         slow = slow.next;\n         fast = fast.next.next;\n         if (slow == fast) {\n             slow = head;\n             while (slow != fast) { slow = slow.next; fast = fast.next; }\n             return slow;\n         }\n     }\n     return null;\n }"}]},{"id":74,"title":"Reverse Nodes in k-Group","module":"Linked List","approaches":[{"label":"Brute force","explanation":"Copy values into an array, reverse each block of k indices in place, then write values back into the original nodes without changing structure beyond values.","complexity":"O(n) time, O(n) space.","code":"ListNode reverseKGroupBrute(ListNode head, int k) {\n     List<Integer> vals = new ArrayList<>();\n     for (ListNode cur = head; cur != null; cur = cur.next) vals.add(cur.val);\n     for (int i = 0; i + k <= vals.size(); i += k) {\n         int l = i, r = i + k - 1;\n         while (l < r) {\n             int t = vals.get(l); vals.set(l, vals.get(r)); vals.set(r, t);\n             l++; r--;\n         }\n     }\n     ListNode cur = head;\n     for (int v : vals) { cur.val = v; cur = cur.next; }\n     return head;\n }"},{"label":"Better","explanation":"Iteratively count k nodes, reverse that block with three pointers, stitch the old head to the next block's result, and advance. Same logic as recursion without call stack.","complexity":"O(n) time, O(1) extra space.","code":"ListNode reverseKGroupIter(ListNode head, int k) {\n     ListNode dummy = new ListNode(0);\n     dummy.next = head;\n     ListNode prevGroup = dummy;\n     while (true) {\n         ListNode kth = prevGroup;\n         for (int i = 0; i < k && kth != null; i++) kth = kth.next;\n         if (kth == null) break;\n         ListNode groupNext = kth.next;\n         ListNode prev = groupNext, cur = prevGroup.next;\n         while (cur != groupNext) {\n             ListNode nxt = cur.next;\n             cur.next = prev;\n             prev = cur;\n             cur = nxt;\n         }\n         ListNode tmp = prevGroup.next;\n         prevGroup.next = kth;\n         prevGroup = tmp;\n     }\n     return dummy.next;\n }"},{"label":"Optimal","explanation":"Count k nodes; if fewer remain, return head unchanged. Reverse the block with three pointers, then recursively reverse the suffix and attach. A dummy makes the first stitch like the rest.","complexity":"O(n) time, O(n / k) recursion stack.","code":"ListNode reverseKGroup(ListNode head, int k) {\n     ListNode cur = head;\n     for (int i = 0; i < k; i++) {\n         if (cur == null) return head;\n         cur = cur.next;\n     }\n     ListNode prev = null, node = head;\n     for (int i = 0; i < k; i++) {\n         ListNode nxt = node.next;\n         node.next = prev;\n         prev = node;\n         node = nxt;\n     }\n     head.next = reverseKGroup(node, k);\n     return prev;\n }"}]},{"id":75,"title":"Palindrome Linked List","module":"Linked List","approaches":[{"label":"Brute force","explanation":"Copy values into an array and compare from both ends with two indices. Easy but uses extra space.","complexity":"O(n) time, O(n) space.","code":"boolean isPalindromeBrute(ListNode head) {\n     List<Integer> a = new ArrayList<>();\n     for (ListNode cur = head; cur != null; cur = cur.next) a.add(cur.val);\n     int l = 0, r = a.size() - 1;\n     while (l < r) {\n         if (!a.get(l++).equals(a.get(r--))) return false;\n     }\n     return true;\n }"},{"label":"Optimal","explanation":"Find the middle with slow and fast, reverse the second half in place, compare head with reversed half. Optionally reverse again to restore the list.","complexity":"O(n) time, O(1) space.","code":"boolean isPalindrome(ListNode head) {\n     ListNode slow = head, fast = head;\n     while (fast != null && fast.next != null) {\n         slow = slow.next;\n         fast = fast.next.next;\n     }\n     ListNode right = reverseList(slow), left = head;\n     while (right != null) {\n         if (left.val != right.val) return false;\n         left = left.next;\n         right = right.next;\n     }\n     return true;\n }"}]},{"id":76,"title":"Flatten a Multilevel Sorted List","module":"Linked List","approaches":[{"label":"Brute force","explanation":"Collect every value via DFS on next and bottom, sort, then rebuild a single-level list with only next pointers.","complexity":"O(N log N) time for N total nodes, O(N) space.","code":"Node flattenBrute(Node head) {\n     List<Integer> vals = new ArrayList<>();\n     collect(head, vals);\n     Collections.sort(vals);\n     Node dummy = new Node(0), tail = dummy;\n     for (int v : vals) {\n         tail.next = new Node(v);\n         tail = tail.next;\n     }\n     return dummy.next;\n }\n void collect(Node node, List<Integer> vals) {\n     while (node != null) {\n         vals.add(node.val);\n         if (node.bottom != null) collect(node.bottom, vals);\n         node = node.next;\n     }\n }"},{"label":"Optimal","explanation":"Recursively flatten everything to the right, then merge this column with that result using sorted merge on bottom pointers, clearing next on merged nodes.","complexity":"O(total nodes) time, O(columns) stack.","code":"Node flatten(Node head) {\n     if (head == null || head.next == null) return head;\n     head.next = flatten(head.next);\n     return mergeBottom(head, head.next);\n }\n Node mergeBottom(Node a, Node b) {\n     Node dummy = new Node(0), tail = dummy;\n     while (a != null && b != null) {\n         if (a.val <= b.val) { tail.bottom = a; a = a.bottom; }\n         else { tail.bottom = b; b = b.bottom; }\n         tail = tail.bottom;\n         tail.next = null;\n     }\n     tail.bottom = a != null ? a : b;\n     return dummy.bottom;\n }"}]},{"id":77,"title":"Rotate List","module":"Linked List","approaches":[{"label":"Brute force","explanation":"Repeat k % n times: save the tail, detach it, and make it the new head. Each rotation is one full walk to the tail.","complexity":"O(n * k) time, O(1) space.","code":"ListNode rotateRightBrute(ListNode head, int k) {\n     if (head == null || head.next == null) return head;\n     int n = 0;\n     for (ListNode cur = head; cur != null; cur = cur.next) n++;\n     k %= n;\n     if (k == 0) return head;\n     for (int r = 0; r < k; r++) {\n         ListNode cur = head, prev = null;\n         while (cur.next != null) { prev = cur; cur = cur.next; }\n         prev.next = null;\n         cur.next = head;\n         head = cur;\n     }\n     return head;\n }"},{"label":"Optimal","explanation":"Find length and tail, connect tail to head to form a circle, then break at position n - k % n. The node after the break is the new head.","complexity":"O(n) time, O(1) space.","code":"ListNode rotateRight(ListNode head, int k) {\n     if (head == null || head.next == null) return head;\n     int n = 1;\n     ListNode tail = head;\n     while (tail.next != null) { tail = tail.next; n++; }\n     k %= n;\n     if (k == 0) return head;\n     tail.next = head;\n     ListNode neu = head;\n     for (int i = 0; i < n - k - 1; i++) neu = neu.next;\n     ListNode start = neu.next;\n     neu.next = null;\n     return start;\n }"}]},{"id":78,"title":"Copy List with Random Pointer","module":"Linked List","approaches":[{"label":"Brute force","explanation":"Two passes with a hash map from each original node to its clone. First pass creates clones, second pass wires next and random from the map.","complexity":"O(n) time, O(n) space.","code":"Node copyRandomListMap(Node head) {\n     if (head == null) return null;\n     Map<Node, Node> map = new HashMap<>();\n     for (Node cur = head; cur != null; cur = cur.next)\n         map.put(cur, new Node(cur.val));\n     for (Node cur = head; cur != null; cur = cur.next) {\n         map.get(cur).next = map.get(cur.next);\n         map.get(cur).random = map.get(cur.random);\n     }\n     return map.get(head);\n }"},{"label":"Optimal","explanation":"Insert  each  clone  between  a  node  and  its  next  so  clone  of  x.random  is  x.random.next.  Set  random  links,  then detach clones in a third pass. No hash map.","complexity":"O(n) time, O(1) extra space.","code":"Node copyRandomList(Node head) {\n     if (head == null) return null;\n     for (Node cur = head; cur != null; cur = cur.next.next) {\n         Node copy = new Node(cur.val);\n         copy.next = cur.next;\n         cur.next = copy;\n     }\n     for (Node cur = head; cur != null; cur = cur.next.next)\n         if (cur.random != null) cur.next.random = cur.random.next;\n     Node dummy = new Node(0), tail = dummy;\n     for (Node cur = head; cur != null; cur = cur.next) {\n         tail.next = cur.next;\n         tail = tail.next;\n         cur.next = cur.next.next;\n     }\n     return dummy.next;\n }"}]},{"id":79,"title":"Valid Parentheses","module":"Stack and Queues","approaches":[{"label":"Brute force","explanation":"Repeatedly find and remove adjacent matching pairs like () or [] until the string is empty or no pair remains. Valid iff nothing is left. Each scan is O(n); worst case this degrades badly on nested strings.","complexity":"O(n^2) time, O(n) space for the mutable string.","code":"boolean isValidBrute(String s) {\n     StringBuilder sb = new StringBuilder(s);\n     boolean changed = true;\n     while (changed && sb.length() > 0) {\n         changed = false;\n         for (int i = 0; i + 1 < sb.length(); i++) {\n             char a = sb.charAt(i), b = sb.charAt(i + 1);\n             if ((a == '(' && b == ')') || (a == '{' && b == '}')\n                     || (a == '[' && b == ']')) {\n                 sb.delete(i, i + 2);\n                 changed = true;\n                 break;\n             }\n         }\n     }\n     return sb.length() == 0;\n }"},{"label":"Optimal","explanation":"Push openings. A closing bracket is valid only when the stack top is its partner; then pop. Invalid on empty stack or mismatch. Valid when the stack is empty at the end.","complexity":"O(n) time, O(n) space.","code":"boolean isValid(String s) {\n     Deque<Character> st = new ArrayDeque<>();\n     for (int i = 0; i < s.length(); i++) {\n         char c = s.charAt(i);\n         if (c == '(' || c == '{' || c == '[') st.push(c);\n         else if (st.isEmpty()) return false;\n         else {\n             char o = st.pop();\n             if (c == ')' && o != '(') return false;\n             if (c == '}' && o != '{') return false;\n             if (c == ']' && o != '[') return false;\n         }\n     }\n     return st.isEmpty();\n }"}]},{"id":80,"title":"Min Stack","module":"Stack and Queues","approaches":[{"label":"Better","explanation":"Keep  two  stacks:  one  for  values  and  one  for  the  minimum  after  each  push.  Pop  both  together.  Slightly  more bookkeeping than pairs but the idea is transparent.","complexity":"O(1) per operation, O(n) space.","code":"class MinStackTwoStacks {\n     Deque<Integer> vals = new ArrayDeque<>();\n     Deque<Integer> mins = new ArrayDeque<>();\n     void push(int val) {\n         vals.push(val);\n         mins.push(mins.isEmpty() ? val : Math.min(val, mins.peek()));\n     }\n     void pop() { vals.pop(); mins.pop(); }\n     int top() { return vals.peek(); }\n     int getMin() { return mins.peek(); }\n }"},{"label":"Optimal","explanation":"Each stack entry stores the value and the minimum at that moment. getMin reads the second half of the top pair; pop discards both.","complexity":"O(1) per operation, O(n) space.","code":"class MinStack {\n     Deque<int[]> st = new ArrayDeque<>();\n     void push(int val) {\n         int mn = st.isEmpty() ? val : Math.min(val, st.peek()[1]);\n         st.push(new int[]{val, mn});\n     }\n     void pop() { st.pop(); }\n     int top() { return st.peek()[0]; }\n     int getMin() { return st.peek()[1]; }\n }"}]},{"id":81,"title":"Queue Using Two Stacks","module":"Stack and Queues","approaches":[{"label":"Brute force","explanation":"On  every  pop  or  peek,  pour  the  entire  inbox  into  the  outbox  so  the  oldest  element  is  on  top.  Simple  but  each operation can cost O(n).","complexity":"O(n) per pop/peek, O(n) space.","code":"class MyQueueBrute {\n     Deque<Integer> in = new ArrayDeque<>();\n     Deque<Integer> out = new ArrayDeque<>();\n     void push(int x) { in.push(x); }\n     int pop() {\n         while (!in.isEmpty()) out.push(in.pop());\n         return out.pop();\n     }\n     int peek() {\n         while (!in.isEmpty()) out.push(in.pop());\n         return out.peek();\n     }\n     boolean empty() { return in.isEmpty() && out.isEmpty(); }\n }"},{"label":"Optimal","explanation":"Pour inbox into outbox only when outbox is empty. Each element moves once, so pop and peek are amortized O(1).","complexity":"Amortized O(1) per operation, O(n) space.","code":"class MyQueue {\n     Deque<Integer> in = new ArrayDeque<>();\n     Deque<Integer> out = new ArrayDeque<>();\n     void push(int x) { in.push(x); }\n     void pour() {\n         if (out.isEmpty()) while (!in.isEmpty()) out.push(in.pop());\n     }\n     int pop() { pour(); return out.pop(); }\n     int peek() { pour(); return out.peek(); }\n     boolean empty() { return in.isEmpty() && out.isEmpty(); }\n }"}]},{"id":82,"title":"Stack Using Two Queues","module":"Stack and Queues","approaches":[{"label":"Better","explanation":"Maintain two queues. Push enqueues into the non-empty queue, or q1 if both empty. Pop dequeues from the only non-empty queue after moving all but one element to the other queue so the last element is removed. Push stays O(1); pop costs O(n).","complexity":"O(1) push, O(n) pop, O(n) space.","code":"class MyStackTwoQueues {\n     Queue<Integer> q1 = new ArrayDeque<>();\n     Queue<Integer> q2 = new ArrayDeque<>();\n     void push(int x) {\n         if (!q1.isEmpty()) q1.offer(x);\n         else q2.offer(x);\n     }\n     int pop() {\n         Queue<Integer> big = q1.size() >= q2.size() ? q1 : q2;\n         Queue<Integer> small = big == q1 ? q2 : q1;\n         while (big.size() > 1) small.offer(big.poll());\n         return big.poll();\n     }\n     int top() {\n         int v = pop();\n         push(v);\n         return v;\n     }\n     boolean empty() { return q1.isEmpty() && q2.isEmpty(); }\n }"},{"label":"Optimal","explanation":"Single queue: after enqueueing x, rotate by dequeuing and enqueueing size - 1 elements so x sits at the front. pop and top read the front.","complexity":"O(n) push, O(1) pop, O(n) space.","code":"class MyStack {\n     Queue<Integer> q = new ArrayDeque<>();\n     void push(int x) {\n         q.offer(x);\n         for (int i = q.size() - 1; i > 0; i--) q.offer(q.poll());\n     }\n     int pop() { return q.poll(); }\n     int top() { return q.peek(); }\n     boolean empty() { return q.isEmpty(); }\n }"}]},{"id":83,"title":"Next Greater Element","module":"Stack and Queues","approaches":[{"label":"Brute force","explanation":"For each index, scan right until a larger value appears or return -1.","complexity":"O(n^2) time, O(1) extra space besides output.","code":"int[] nextGreaterBrute(int[] a) {\n     int n = a.length, ans[] = new int[n];\n     for (int i = 0; i < n; i++) {\n         ans[i] = -1;\n         for (int j = i + 1; j < n; j++) {\n             if (a[j] > a[i]) { ans[i] = a[j]; break; }\n         }\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"Monotonic  decreasing  stack  of  indexes.  When  a[i]  beats  the  top  value,  it  is  that  index's  next  greater.  Pop  until decreasing again, then push i.","complexity":"O(n) time, O(n) space.","code":"int[] nextGreater(int[] a) {\n     int n = a.length, ans[] = new int[n];\n     Arrays.fill(ans, -1);\n     Deque<Integer> st = new ArrayDeque<>();\n     for (int i = 0; i < n; i++) {\n         while (!st.isEmpty() && a[st.peek()] < a[i]) ans[st.pop()] = a[i];\n         st.push(i);\n     }\n     return ans;\n }"}]},{"id":84,"title":"Next Smaller Element","module":"Stack and Queues","approaches":[{"label":"Brute force","explanation":"For each index, scan right for the first strictly smaller value.","complexity":"O(n^2) time, O(1) extra space besides output.","code":"int[] nextSmallerBrute(int[] a) {\n     int n = a.length, ans[] = new int[n];\n     for (int i = 0; i < n; i++) {\n         ans[i] = -1;\n         for (int j = i + 1; j < n; j++) {\n             if (a[j] < a[i]) { ans[i] = a[j]; break; }\n         }\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"Monotonic  increasing  stack  of  indexes.  When  a[i]  is  smaller  than  the  top,  it  answers  every  popped  index. Remaining indexes get -1.","complexity":"O(n) time, O(n) space.","code":"int[] nextSmaller(int[] a) {\n     int n = a.length, ans[] = new int[n];\n     Arrays.fill(ans, -1);\n     Deque<Integer> st = new ArrayDeque<>();\n     for (int i = 0; i < n; i++) {\n         while (!st.isEmpty() && a[st.peek()] > a[i]) ans[st.pop()] = a[i];\n         st.push(i);\n     }\n     return ans;\n }"}]},{"id":85,"title":"Previous Smaller Element","module":"Stack and Queues","approaches":[{"label":"Brute force","explanation":"For each index, scan left for the nearest strictly smaller value.","complexity":"O(n^2) time, O(1) extra space besides output.","code":"int[] previousSmallerBrute(int[] a) {\n     int n = a.length, ans[] = new int[n];\n     for (int i = 0; i < n; i++) {\n         ans[i] = -1;\n         for (int j = i - 1; j >= 0; j--) {\n             if (a[j] < a[i]) { ans[i] = a[j]; break; }\n         }\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"Increasing stack: before pushing i, pop values >= a[i]. The top, if any, is the previous smaller; then push i.","complexity":"O(n) time, O(n) space.","code":"int[] previousSmaller(int[] a) {\n     int n = a.length, ans[] = new int[n];\n     Deque<Integer> st = new ArrayDeque<>();\n     for (int i = 0; i < n; i++) {\n         while (!st.isEmpty() && a[st.peek()] >= a[i]) st.pop();\n         ans[i] = st.isEmpty() ? -1 : a[st.peek()];\n         st.push(i);\n     }\n     return ans;\n }"}]},{"id":86,"title":"Stock Span","module":"Stack and Queues","approaches":[{"label":"Brute force","explanation":"For each day, walk left while prices are at most today's price and count days included.","complexity":"O(n^2) time, O(1) extra space besides output.","code":"int[] stockSpanBrute(int[] price) {\n     int n = price.length, span[] = new int[n];\n     for (int i = 0; i < n; i++) {\n         span[i] = 1;\n         for (int j = i - 1; j >= 0 && price[j] <= price[i]; j--) span[i]++;\n     }\n     return span;\n }"},{"label":"Optimal","explanation":"Decreasing stack of indexes. Pop days with price <= today; span is i - top or i + 1 if empty.","complexity":"O(n) time, O(n) space.","code":"int[] stockSpan(int[] price) {\n     int n = price.length, span[] = new int[n];\n     Deque<Integer> st = new ArrayDeque<>();\n     for (int i = 0; i < n; i++) {\n         while (!st.isEmpty() && price[st.peek()] <= price[i]) st.pop();\n         span[i] = st.isEmpty() ? i + 1 : i - st.peek();\n         st.push(i);\n     }\n     return span;\n }"}]},{"id":87,"title":"Largest Rectangle in Histogram","module":"Stack and Queues","approaches":[{"label":"Brute force","explanation":"For each bar, expand left and right while heights stay at least h[i], then area is h[i] times width. Correct but each bar may scan O(n) neighbors.","complexity":"O(n^2) time, O(1) extra space.","code":"int largestRectangleAreaBrute(int[] h) {\n     int n = h.length, best = 0;\n     for (int i = 0; i < n; i++) {\n         int left = i, right = i;\n         while (left > 0 && h[left - 1] >= h[i]) left--;\n         while (right + 1 < n && h[right + 1] >= h[i]) right++;\n         best = Math.max(best, h[i] * (right - left + 1));\n     }\n     return best;\n }"},{"label":"Optimal","explanation":"Previous and next strictly smaller index for each bar with monotonic stacks. Width is right - left - 1; maximize h[i] * width.","complexity":"O(n) time, O(n) space.","code":"int largestRectangleArea(int[] h) {\n     int n = h.length;\n     int[] left = new int[n], right = new int[n];\n     Deque<Integer> st = new ArrayDeque<>();\n     for (int i = 0; i < n; i++) {\n         while (!st.isEmpty() && h[st.peek()] >= h[i]) st.pop();\n         left[i] = st.isEmpty() ? -1 : st.peek();\n         st.push(i);\n     }\n     st.clear();\n     for (int i = n - 1; i >= 0; i--) {\n         while (!st.isEmpty() && h[st.peek()] >= h[i]) st.pop();\n         right[i] = st.isEmpty() ? n : st.peek();\n         st.push(i);\n     }\n     int best = 0;\n     for (int i = 0; i < n; i++)\n         best = Math.max(best, h[i] * (right[i] - left[i] - 1));\n     return best;\n }"}]},{"id":88,"title":"Maximal Rectangle","module":"Stack and Queues","approaches":[{"label":"Brute force","explanation":"Enumerate every submatrix by top/bottom rows and left/right columns, check if all cells are '1', track max area. Fine for tiny grids only.","complexity":"O(rows^2 * cols^2) time, O(1) extra space.","code":"int maximalRectangleBrute(char[][] matrix) {\n     if (matrix.length == 0) return 0;\n     int rows = matrix.length, cols = matrix[0].length, best = 0;\n     for (int r1 = 0; r1 < rows; r1++) {\n         for (int r2 = r1; r2 < rows; r2++) {\n             for (int c1 = 0; c1 < cols; c1++) {\n                 for (int c2 = c1; c2 < cols; c2++) {\n                     boolean ok = true;\n                     for (int r = r1; r <= r2 && ok; r++)\n                         for (int c = c1; c <= c2; c++)\n                             if (matrix[r][c] == '0') ok = false;\n                     if (ok) best = Math.max(best, (r2 - r1 + 1) * (c2 - c1 + 1));\n                 }\n             }\n         }\n     }\n     return best;\n }"},{"label":"Optimal","explanation":"Each row builds a histogram height of consecutive ones above. The largest rectangle in that histogram is the best rectangle ending on this row. Max over all rows.","complexity":"O(rows * cols) time, O(cols) space.","code":"int maximalRectangle(char[][] matrix) {\n     if (matrix.length == 0) return 0;\n     int m = matrix[0].length, best = 0;\n     int[] h = new int[m];\n     for (char[] row : matrix) {\n         for (int c = 0; c < m; c++)\n             h[c] = row[c] == '1' ? h[c] + 1 : 0;\n         best = Math.max(best, largestRectangleArea(h));\n     }\n     return best;\n }"}]},{"id":89,"title":"Sliding Window Maximum","module":"Stack and Queues","approaches":[{"label":"Brute force","explanation":"For each window start, scan the k elements and take the maximum.","complexity":"O(n * k) time, O(1) extra space besides output.","code":"int[] maxSlidingWindowBrute(int[] a, int k) {\n     int n = a.length;\n     int[] ans = new int[n - k + 1];\n     for (int i = 0; i <= n - k; i++) {\n         int mx = a[i];\n         for (int j = i; j < i + k; j++) mx = Math.max(mx, a[j]);\n         ans[i] = mx;\n     }\n     return ans;\n }"},{"label":"Better","explanation":"Max-heap of (value, index) for the window. Push each new index; pop from the top while the index is outside the window. Root is the current maximum.","complexity":"O(n log k) time, O(k) space.","code":"int[] maxSlidingWindowHeap(int[] a, int k) {\n     int n = a.length;\n     int[] ans = new int[n - k + 1];\n     PriorityQueue<int[]> pq = new PriorityQueue<>((x, y) -> y[0] - x[0]);\n     for (int i = 0; i < n; i++) {\n         pq.offer(new int[]{a[i], i});\n         while (pq.peek()[1] <= i - k) pq.poll();\n         if (i >= k - 1) ans[i - k + 1] = pq.peek()[0];\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"Deque of indexes with decreasing values. Drop front when out of window; drop back while value <= a[i]. Front is the window max.","complexity":"O(n) time, O(k) space.","code":"int[] maxSlidingWindow(int[] a, int k) {\n     int n = a.length;\n     int[] ans = new int[n - k + 1];\n     Deque<Integer> dq = new ArrayDeque<>();\n     for (int i = 0; i < n; i++) {\n         while (!dq.isEmpty() && dq.peekFirst() <= i - k) dq.pollFirst();\n         while (!dq.isEmpty() && a[dq.peekLast()] <= a[i]) dq.pollLast();\n         dq.offerLast(i);\n         if (i >= k - 1) ans[i - k + 1] = a[dq.peekFirst()];\n     }\n     return ans;\n }"}]},{"id":90,"title":"The Celebrity Problem","module":"Stack and Queues","approaches":[{"label":"Brute force","explanation":"Try each person as candidate celebrity: everyone else must know them and they must know nobody.","complexity":"O(n^2) time, O(1) space.","code":"int celebrityBrute(int[][] mat) {\n     int n = mat.length;\n     for (int c = 0; c < n; c++) {\n         boolean ok = true;\n         for (int i = 0; i < n && ok; i++) {\n             if (i == c) continue;\n             if (mat[c][i] == 1 || mat[i][c] == 0) ok = false;\n         }\n         if (ok) return c;\n     }\n     return -1;\n }"},{"label":"Optimal","explanation":"Eliminate one person per comparison: if cand knows i, cand is wrong; else i is wrong. Verify the survivor against everyone else.","complexity":"O(n) time, O(1) space.","code":"int celebrity(int[][] mat) {\n     int n = mat.length, cand = 0;\n     for (int i = 1; i < n; i++)\n         if (mat[cand][i] == 1) cand = i;\n     for (int i = 0; i < n; i++) {\n         if (i == cand) continue;\n         if (mat[cand][i] == 1 || mat[i][cand] == 0) return -1;\n     }\n     return cand;\n }"}]},{"id":91,"title":"LRU Cache","module":"Stack and Queues","approaches":[{"label":"Brute force","explanation":"Store entries in a list. get finds the key linearly, moves the entry to the front, or returns -1. put updates or inserts at front and removes the tail when over capacity.","complexity":"O(n) get and put, O(capacity) space.","code":"class LRUCacheBrute {\n     class E { int key, val; E(int k, int v) { key = k; val = v; } }\n     List<E> list = new LinkedList<>();\n     int cap;\n     LRUCacheBrute(int capacity) { cap = capacity; }\n     int get(int key) {\n         for (int i = 0; i < list.size(); i++) {\n             if (list.get(i).key == key) {\n                 E e = list.remove(i);\n                 list.add(0, e);\n                 return e.val;\n             }\n         }\n         return -1;\n     }\n     void put(int key, int value) {\n         for (int i = 0; i < list.size(); i++) {\n             if (list.get(i).key == key) {\n                 list.remove(i);\n                 list.add(0, new E(key, value));\n                 return;\n             }\n         }\n         if (list.size() == cap) list.remove(list.size() - 1);\n         list.add(0, new E(key, value));\n     }\n }"},{"label":"Better","explanation":"Java LinkedHashMap with access-order true evicts the eldest entry when size exceeds capacity. get and put are O(1) amortized with less pointer wiring.","complexity":"O(1) get and put, O(capacity) space.","code":"class LRUCacheLinkedHashMap extends LinkedHashMap<Integer, Integer> {\n     int cap;\n     LRUCacheLinkedHashMap(int capacity) {\n         super(capacity, 0.75f, true);\n         cap = capacity;\n     }\n     protected boolean removeEldestEntry(Map.Entry<Integer, Integer> e) {\n         return size() > cap;\n     }\n     int get(int key) {\n         return super.getOrDefault(key, -1);\n     }\n     void put(int key, int value) { super.put(key, value); }\n }"},{"label":"Optimal","explanation":"Hash map from key to doubly linked list node; list ordered by recency with dummy head and tail. moveFront on access; delete tail.prev on eviction.","complexity":"O(1) get and put, O(capacity) space.","code":"class LRUCache {\n     class N {\n         int key, val; N prev, next;\n         N(int k, int v) { key = k; val = v; }\n     }\n     Map<Integer, N> map = new HashMap<>();\n     N head = new N(0, 0), tail = new N(0, 0);\n     int cap;\n     LRUCache(int capacity) {\n         cap = capacity;\n         head.next = tail; tail.prev = head;\n     }\n     int get(int key) {\n         if (!map.containsKey(key)) return -1;\n         N node = map.get(key);\n         moveFront(node);\n         return node.val;\n     }\n     void put(int key, int value) {\n         if (map.containsKey(key)) {\n             N node = map.get(key);\n             node.val = value;\n             moveFront(node);\n             return;\n         }\n         if (map.size() == cap) {\n             N last = tail.prev;\n             map.remove(last.key);\n             last.prev.next = tail;\n             tail.prev = last.prev;\n         }\n         N node = new N(key, value);\n         map.put(key, node);\n         node.next = head.next; node.prev = head;\n         head.next.prev = node; head.next = node;\n     }\n     void moveFront(N node) {\n         node.prev.next = node.next;\n         node.next.prev = node.prev;\n         node.next = head.next; node.prev = head;\n         head.next.prev = node; head.next = node;\n     }\n }"}]},{"id":92,"title":"Sum of Subarray Minimums","module":"Stack and Queues","approaches":[{"label":"Brute force","explanation":"Enumerate every subarray, track its minimum, add to the running sum modulo 10^9 + 7.","complexity":"O(n^2) time, O(1) extra space.","code":"int sumSubarrayMinsBrute(int[] a) {\n     int n = a.length, mod = 1_000_000_007;\n     long ans = 0;\n     for (int i = 0; i < n; i++) {\n         int mn = a[i];\n         for (int j = i; j < n; j++) {\n             mn = Math.min(mn, a[j]);\n             ans = (ans + mn) % mod;\n         }\n     }\n     return (int) ans;\n }"},{"label":"Optimal","explanation":"Each index is the minimum on a unique range: previous strictly smaller on the left, next smaller-or-equal on the right. Contribution is a[i] * leftSpan * rightSpan.","complexity":"O(n) time, O(n) space.","code":"int sumSubarrayMins(int[] a) {\n     int n = a.length, mod = 1_000_000_007;\n     int[] left = new int[n], right = new int[n];\n     Deque<Integer> st = new ArrayDeque<>();\n     for (int i = 0; i < n; i++) {\n         while (!st.isEmpty() && a[st.peek()] > a[i]) st.pop();\n         left[i] = st.isEmpty() ? i + 1 : i - st.peek();\n         st.push(i);\n     }\n     st.clear();\n     for (int i = n - 1; i >= 0; i--) {\n         while (!st.isEmpty() && a[st.peek()] >= a[i]) st.pop();\n         right[i] = st.isEmpty() ? n - i : st.peek() - i;\n         st.push(i);\n     }\n     long ans = 0;\n     for (int i = 0; i < n; i++)\n         ans = (ans + (long) a[i] * left[i] % mod * right[i]) % mod;\n     return (int) ans;\n }"}]},{"id":93,"title":"Remove K Digits","module":"Stack and Queues","approaches":[{"label":"Brute force","explanation":"Try deleting every subset of k positions (or recurse on which digit to drop). Keeps the lexicographically smallest remaining number. Exponential in k.","complexity":"O(C(n, k) * n) time, O(n) space.","code":"String removeKdigitsBrute(String num, int k) {\n     String best = null;\n     best = dfs(num, k, 0, new StringBuilder(), best);\n     if (best == null || best.isEmpty()) return \"0\";\n     return best;\n }\n String dfs(String num, int k, int i, StringBuilder cur, String best) {\n     if (k == 0) {\n         String rest = cur.toString() + num.substring(i);\n         int p = 0;\n         while (p < rest.length() && rest.charAt(p) == '0') p++;\n         rest = p == rest.length() ? \"\" : rest.substring(p);\n         if (best == null || rest.compareTo(best) < 0) return rest;\n         return best;\n     }\n     if (i >= num.length()) return best;\n     best = dfs(num, k, i + 1, cur, best);\n     cur.append(num.charAt(i));\n     best = dfs(num, k - 1, i + 1, cur, best);\n     cur.deleteCharAt(cur.length() - 1);\n     return best;\n }"},{"label":"Optimal","explanation":"Monotonic  increasing  stack  of  digits.  While  top  is  larger  than  the  current  digit  and  removals  remain,  pop.  Trim remaining k from the end, strip leading zeros, return \"0\" if empty.","complexity":"O(n) time, O(n) space.","code":"String removeKdigits(String num, int k) {\n     StringBuilder st = new StringBuilder();\n     for (int i = 0; i < num.length(); i++) {\n         char c = num.charAt(i);\n         while (k > 0 && st.length() > 0 && st.charAt(st.length() - 1) > c) {\n             st.deleteCharAt(st.length() - 1);\n             k--;\n         }\n         st.append(c);\n     }\n     st.setLength(st.length() - k);\n     int i = 0;\n     while (i < st.length() && st.charAt(i) == '0') i++;\n     String ans = st.substring(i);\n     return ans.isEmpty() ? \"0\" : ans;\n }"}]},{"id":94,"title":"Asteroid Collision","module":"Stack and Queues","approaches":[{"label":"Brute force","explanation":"Repeatedly scan for a right-moving positive followed by a left-moving negative, resolve that collision, and restart until no collision remains.","complexity":"O(n^2) time, O(n) space.","code":"int[] asteroidCollisionBrute(int[] a) {\n     List<Integer> list = new ArrayList<>();\n     for (int x : a) list.add(x);\n     boolean hit = true;\n     while (hit) {\n         hit = false;\n         for (int i = 0; i + 1 < list.size(); i++) {\n             int x = list.get(i), y = list.get(i + 1);\n             if (x > 0 && y < 0) {\n                 hit = true;\n                 if (x < -y) list.remove(i);\n                 else if (x > -y) list.remove(i + 1);\n                 else { list.remove(i + 1); list.remove(i); }\n                 break;\n             }\n         }\n     }\n     int[] ans = new int[list.size()];\n     for (int i = 0; i < ans.length; i++) ans[i] = list.get(i);\n     return ans;\n }"},{"label":"Optimal","explanation":"Stack of surviving asteroids. Only a positive top collides with an incoming negative. Pop while smaller; equal sizes destroy both.","complexity":"O(n) time, O(n) space.","code":"int[] asteroidCollision(int[] a) {\n     Deque<Integer> st = new ArrayDeque<>();\n     for (int x : a) {\n         boolean alive = true;\n         while (alive && x < 0 && !st.isEmpty() && st.peek() > 0) {\n             if (st.peek() < -x) st.pop();\n             else if (st.peek() == -x) { st.pop(); alive = false; }\n             else alive = false;\n         }\n         if (alive) st.push(x);\n     }\n     int[] ans = new int[st.size()];\n     for (int i = ans.length - 1; i >= 0; i--) ans[i] = st.pop();\n     return ans;\n }"}]},{"id":95,"title":"N Meetings in One Room (Activity Selection)","module":"Greedy","approaches":[{"label":"Brute force","explanation":"Each meeting is either taken or skipped. Enumerate all 2^n subsets, keep only subsets whose meetings do not overlap, and return the largest size. Correct but exponential.","complexity":"O(2^n * n) time, O(n) space.","code":"int maxMeetingsBrute(int[][] m) {\n     int n = m.length, best = 0;\n     for (int mask = 0; mask < (1 << n); mask++) {\n         int prevEnd = -1, cnt = 0, ok = true;\n         for (int i = 0; i < n; i++) {\n             if ((mask & (1 << i)) == 0) continue;\n             if (m[i][0] < prevEnd) { ok = false; break; }\n             prevEnd = m[i][1];\n             cnt++;\n         }\n         if (ok) best = Math.max(best, cnt);\n     }\n     return best;\n }"},{"label":"Optimal","explanation":"Sort by finish time. Take the next meeting if its start is not before the last chosen finish. Finishing early leaves the most room for later meetings, so an exchange argument shows no optimal schedule uses fewer meetings.","complexity":"O(n log n) time, O(1) extra space.","code":"int maxMeetings(int[][] m) {\n     Arrays.sort(m, (a, b) -> Integer.compare(a[1], b[1]));\n     int cnt = 0, end = -1;\n     for (int[] x : m) {\n         if (x[0] >= end) { cnt++; end = x[1]; }\n     }\n     return cnt;\n }"}]},{"id":96,"title":"Minimum Number of Platforms","module":"Greedy","approaches":[{"label":"Better","explanation":"Sort arrivals and departures separately. Walk both arrays: if the next arrival is before or when the next train leaves, one more platform is needed and the arrival pointer moves; otherwise a platform frees and the departure pointer moves. Track the peak count.","complexity":"O(n log n) time, O(1) extra space besides sorting.","code":"int findPlatform(int[] arr, int[] dep) {\n     Arrays.sort(arr);\n     Arrays.sort(dep);\n     int i = 0, j = 0, cur = 0, best = 0;\n     while (i < arr.length) {\n         if (arr[i] <= dep[j]) { cur++; i++; best = Math.max(best, cur); }\n         else { cur--; j++; }\n     }\n     return best;\n }"},{"label":"Optimal","explanation":"Build  events:  +1  at  each  arrival,  -1  at  each  departure.  Sort  by  time;  at  equal  times  process  departures  before arrivals so a train leaving at t frees a platform for one arriving at t. Scan and keep the running maximum.","complexity":"O(n log n) time, O(n) space for events.","code":"int findPlatformEvents(int[] arr, int[] dep) {\n     int n = arr.length;\n     int[][] ev = new int[2 * n][2];\n     for (int i = 0; i < n; i++) {\n         ev[2 * i] = new int[]{arr[i], 1};\n         ev[2 * i + 1] = new int[]{dep[i], -1};\n     }\n     Arrays.sort(ev, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0])\n             : Integer.compare(a[1], b[1]));\n     int cur = 0, best = 0;\n     for (int[] e : ev) {\n         cur += e[1];\n         best = Math.max(best, cur);\n     }\n     return best;\n }"}]},{"id":97,"title":"Job Sequencing Problem","module":"Greedy","approaches":[{"label":"Brute force","explanation":"Try every ordering of jobs. For each order, assign each job to the latest free slot on or before its deadline and sum profit of jobs that fit. Keep the best profit. Correct but factorial.","complexity":"O(n! * n) time, O(n) space.","code":"int jobSeqBrute(int[] profit, int[] deadline) {\n     int n = profit.length;\n     Integer[] idx = new Integer[n];\n     for (int i = 0; i < n; i++) idx[i] = i;\n     int best = 0;\n     do {\n         int maxD = 0;\n         for (int i : idx) maxD = Math.max(maxD, deadline[i]);\n         boolean[] used = new boolean[maxD + 1];\n         int sum = 0;\n         for (int i : idx) {\n             for (int d = deadline[i]; d >= 1; d--) {\n                 if (!used[d]) { used[d] = true; sum += profit[i]; break; }\n             }\n         }\n         best = Math.max(best, sum);\n     } while (nextPerm(idx));\n     return best;\n }\n boolean nextPerm(Integer[] a) {\n     int i = a.length - 2;\n     while (i >= 0 && a[i] >= a[i + 1]) i--;\n     if (i < 0) return false;\n     int j = a.length - 1;\n     while (a[j] <= a[i]) j--;\n     int t = a[i]; a[i] = a[j]; a[j] = t;\n     for (int l = i + 1, r = a.length - 1; l < r; l++, r--) {\n         t = a[l]; a[l] = a[r]; a[r] = t;\n     }\n     return true;\n }"},{"label":"Optimal","explanation":"Sort jobs by decreasing profit. For each job, place it in the latest free day on or before its deadline using a parent array that points to the previous free slot (disjoint-set style). A high-profit job placed late never blocks a lower-profit job that needs an earlier day.","complexity":"O(n^2) time with simple slot scan; O(n log n) with DSU, O(n) space.","code":"int jobSequencing(int[] profit, int[] deadline) {\n     int n = profit.length;\n     Integer[] id = new Integer[n];\n     for (int i = 0; i < n; i++) id[i] = i;\n     Arrays.sort(id, (a, b) -> Integer.compare(profit[b], profit[a]));\n     int maxD = 0;\n     for (int d : deadline) maxD = Math.max(maxD, d);\n     int[] parent = new int[maxD + 2];\n     for (int i = 0; i <= maxD + 1; i++) parent[i] = i;\n     int total = 0, jobs = 0;\n     for (int j : id) {\n         int d = find(parent, deadline[j]);\n         if (d > 0) {\n             parent[d] = find(parent, d - 1);\n             total += profit[j];\n             jobs++;\n         }\n     }\n     return total;\n }\n int find(int[] p, int x) {\n     if (p[x] != x) p[x] = find(p, p[x]);\n     return p[x];\n }"}]},{"id":98,"title":"Fractional Knapsack","module":"Greedy","approaches":[{"label":"Better","explanation":"0/1 knapsack: each item is fully taken or skipped. DP over capacity records the best value using the first i items. This is the right model when splitting items is forbidden, but it does not solve the fractional version.","complexity":"O(n * W) time, O(W) space.","code":"int knapsack01(int[] wt, int[] val, int W) {\n     int[] dp = new int[W + 1];\n     for (int i = 0; i < wt.length; i++)\n         for (int c = W; c >= wt[i]; c--)\n             dp[c] = Math.max(dp[c], dp[c - wt[i]] + val[i]);\n     return dp[W];\n }"},{"label":"Optimal","explanation":"When  fractions  are  allowed,  take  items  in  decreasing  value-to-weight  ratio  until  the  knapsack  is  full.  If  the  next whole item does not fit, take a fraction of it. Any solution that replaces a taken fraction with a worse ratio can be improved by swapping weight, so the greedy order is optimal.","complexity":"O(n log n) time, O(1) extra space besides sorting.","code":"double fractionalKnapsack(int[] wt, int[] val, int W) {\n     int n = wt.length;\n     Integer[] id = new Integer[n];\n     for (int i = 0; i < n; i++) id[i] = i;\n     Arrays.sort(id, (a, b) -> Double.compare(\n             (double) val[b] / wt[b], (double) val[a] / wt[a]));\n     double ans = 0;\n     for (int i : id) {\n         if (W >= wt[i]) { ans += val[i]; W -= wt[i]; }\n         else { ans += (double) val[i] * W / wt[i]; break; }\n     }\n     return ans;\n }"}]},{"id":99,"title":"Minimum Coins (Greedy vs DP)","module":"Greedy","approaches":[{"label":"Brute force","explanation":"BFS on the amount: from amount a, try subtracting each coin denomination and enqueue a - c when non-negative. The first time 0 is reached, the path length is the minimum number of coins. Works for any coin system.","complexity":"O(amount * k) time, O(amount) space.","code":"int coinChangeBfs(int[] coins, int amount) {\n     if (amount == 0) return 0;\n     boolean[] seen = new boolean[amount + 1];\n     Deque<Integer> q = new ArrayDeque<>();\n     q.offer(amount);\n     seen[amount] = true;\n     for (int steps = 1; !q.isEmpty(); steps++) {\n         int sz = q.size();\n         for (int t = 0; t < sz; t++) {\n             int a = q.poll();\n             for (int c : coins) {\n                 int nxt = a - c;\n                 if (nxt == 0) return steps;\n                 if (nxt > 0 && !seen[nxt]) { seen[nxt] = true; q.offer(nxt); }\n             }\n         }\n     }\n     return -1;\n }"},{"label":"Better","explanation":"Unbounded knapsack-style DP: dp[a] is the minimum coins to make a. For each amount, try every coin. Correct for arbitrary denominations, unlike a blind greedy pass.","complexity":"O(amount * k) time, O(amount) space.","code":"int coinChange(int[] coins, int amount) {\n     int[] dp = new int[amount + 1];\n     Arrays.fill(dp, amount + 1);\n     dp[0] = 0;\n     for (int a = 1; a <= amount; a++)\n         for (int c : coins)\n             if (c <= a) dp[a] = Math.min(dp[a], dp[a - c] + 1);\n     return dp[amount] > amount ? -1 : dp[amount];\n }"},{"label":"Optimal","explanation":"For canonical systems (typical US coins: each denomination is at least the sum of smaller ones), repeatedly take the largest coin that does not exceed the remaining amount. One pass, no table. Fails on counterexamples such as coins [1, 3, 4] for amount 6.","complexity":"O(k) time after sorting coins, O(1) extra space.","code":"int coinChangeGreedy(int[] coins, int amount) {\n     Arrays.sort(coins);\n     int cnt = 0;\n     for (int i = coins.length - 1; i >= 0 && amount > 0; i--) {\n         while (amount >= coins[i]) { amount -= coins[i]; cnt++; }\n     }\n     return amount == 0 ? cnt : -1;\n }"}]},{"id":100,"title":"Assign Cookies","module":"Greedy","approaches":[{"label":"Brute force","explanation":"For each child in order, scan every unused cookie and assign the first cookie that satisfies their greed. Simple but can waste large cookies on small children when a sorted matching would do better.","complexity":"O(n * m) time, O(m) space for used flags.","code":"int findContentChildrenBrute(int[] g, int[] s) {\n     boolean[] used = new boolean[s.length];\n     int ans = 0;\n     for (int need : g) {\n         for (int j = 0; j < s.length; j++) {\n             if (!used[j] && s[j] >= need) { used[j] = true; ans++; break; }\n         }\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"Sort  children  by  greed  and  cookies  by  size.  Two  pointers:  if  the  current  cookie  satisfies  the  current  child,  both advance; otherwise only the cookie pointer advances to find a large enough cookie. Never skip a cookie that could satisfy the smallest unserved child.","complexity":"O(n log n + m log m) time, O(1) extra space.","code":"int findContentChildren(int[] g, int[] s) {\n     Arrays.sort(g);\n     Arrays.sort(s);\n     int i = 0, j = 0;\n     while (i < g.length && j < s.length) {\n         if (s[j] >= g[i]) { i++; j++; }\n         else j++;\n     }\n     return i;\n }"}]},{"id":101,"title":"Lemonade Change","module":"Greedy","approaches":[{"label":"Brute force","explanation":"At each customer, try every valid way to make change (which bills to return) and recurse on the rest of the line. Correct for tiny n but explores redundant choices.","complexity":"O(c^n) time for constant c change choices, O(n) recursion depth.","code":"boolean lemonadeChangeBrute(int[] bills, int idx, int f, int t) {\n     if (idx == bills.length) return true;\n     int b = bills[idx];\n     if (b == 5) return lemonadeChangeBrute(bills, idx + 1, f + 1, t);\n     if (b == 10) {\n         if (f == 0) return false;\n         return lemonadeChangeBrute(bills, idx + 1, f - 1, t + 1);\n     }\n     if (f > 0 && t > 0) return lemonadeChangeBrute(bills, idx + 1, f - 1, t - 1);\n     if (f >= 2) return lemonadeChangeBrute(bills, idx + 1, f - 2, t);\n     return false;\n }"},{"label":"Optimal","explanation":"Customers pay 5, 10, or 20. Track counts of 5s and 10s in the drawer. A 10 needs one 5; a 20 prefers one 10 and one 5, otherwise three 5s. Greedy change use preserves 5s when possible because only 10s need them.","complexity":"O(n) time, O(1) space.","code":"boolean lemonadeChange(int[] bills) {\n     int f = 0, t = 0;\n     for (int b : bills) {\n         if (b == 5) f++;\n         else if (b == 10) { if (f == 0) return false; f--; t++; }\n         else {\n             if (t > 0 && f > 0) { t--; f--; }\n             else if (f >= 2) f -= 2;\n             else return false;\n         }\n     }\n     return true;\n }"}]},{"id":102,"title":"Jump Game I","module":"Greedy","approaches":[{"label":"Brute force","explanation":"From  index  i,  try  every  jump  length  from  1  to  nums[i]  and  recurse.  Memoize  reachable  positions  to  avoid recomputation. Still explores many paths.","complexity":"O(n^2) time, O(n) space.","code":"boolean canJumpBrute(int[] nums) {\n     Boolean[] memo = new Boolean[nums.length];\n     return canJumpFrom(nums, 0, memo);\n }\n boolean canJumpFrom(int[] nums, int i, Boolean[] memo) {\n     if (i >= nums.length - 1) return true;\n     if (memo[i] != null) return memo[i];\n     for (int step = 1; step <= nums[i]; step++)\n         if (canJumpFrom(nums, i + step, memo)) return memo[i] = true;\n     return memo[i] = false;\n }"},{"label":"Optimal","explanation":"Track the farthest index reachable from any position seen so far. Scan left to right; if i is beyond that farthest, the gap cannot be crossed. Otherwise extend farthest to i + nums[i]. Reaching the last index is enough.","complexity":"O(n) time, O(1) space.","code":"boolean canJump(int[] nums) {\n     int far = 0;\n     for (int i = 0; i < nums.length; i++) {\n         if (i > far) return false;\n         far = Math.max(far, i + nums[i]);\n         if (far >= nums.length - 1) return true;\n     }\n     return true;\n }"}]},{"id":103,"title":"Jump Game II","module":"Greedy","approaches":[{"label":"Brute force","explanation":"BFS treats each index as a state and enqueues all indices reachable in one jump. The level when the last index is first dequeued is the minimum number of jumps.","complexity":"O(n^2) time in the worst case, O(n) space.","code":"int jumpBfs(int[] nums) {\n     int n = nums.length;\n     if (n <= 1) return 0;\n     Deque<Integer> q = new ArrayDeque<>();\n     boolean[] seen = new boolean[n];\n     q.offer(0);\n     seen[0] = true;\n     for (int jumps = 0; !q.isEmpty(); jumps++) {\n         int sz = q.size();\n         for (int t = 0; t < sz; t++) {\n             int i = q.poll();\n             for (int step = 1; step <= nums[i]; step++) {\n                 int j = i + step;\n                 if (j >= n - 1) return jumps + 1;\n                 if (!seen[j]) { seen[j] = true; q.offer(j); }\n             }\n         }\n     }\n     return -1;\n }"},{"label":"Better","explanation":"dp[i] is the minimum jumps to reach i. For each j < i with j + nums[j] >= i, relax dp[i] from dp[j] + 1. Straightforward dynamic programming.","complexity":"O(n^2) time, O(n) space.","code":"int jumpDp(int[] nums) {\n     int n = nums.length;\n     int[] dp = new int[n];\n     Arrays.fill(dp, n);\n     dp[0] = 0;\n     for (int i = 1; i < n; i++)\n         for (int j = 0; j < i; j++)\n             if (j + nums[j] >= i) dp[i] = Math.min(dp[i], dp[j] + 1);\n     return dp[n - 1];\n }"},{"label":"Optimal","explanation":"Greedy on jump layers. currentEnd is the last index of the current jump layer; farthest is the best reach using one more step from that layer. When i hits currentEnd, increment jumps and set currentEnd to farthest. Each jump is forced to cover as far as possible before the next is spent.","complexity":"O(n) time, O(1) space.","code":"int jump(int[] nums) {\n     int jumps = 0, curEnd = 0, far = 0;\n     for (int i = 0; i < nums.length - 1; i++) {\n         far = Math.max(far, i + nums[i]);\n         if (i == curEnd) { jumps++; curEnd = far; }\n     }\n     return jumps;\n }"}]},{"id":104,"title":"Candy","module":"Greedy","approaches":[{"label":"Brute force","explanation":"Binary  search  the  total  candy  count  T.  Check  feasibility  by  scanning  ratings  and  enforcing  each  child  beats neighbors when ratings rise; impossible if the implied minimum exceeds T. Correct but heavy for large n.","complexity":"O(n log S) time where S is sum of upper bounds, O(n) space.","code":"int candyBrute(int[] ratings) {\n     int n = ratings.length;\n     int[] c = new int[n];\n     return assign(ratings, c, 0) ? sum(c) : -1;\n }\n boolean assign(int[] r, int[] c, int i) {\n     if (i == r.length) return valid(r, c);\n     for (int give = 1; give <= r.length; give++) {\n         c[i] = give;\n         if (assign(r, c, i + 1)) return true;\n     }\n     return false;\n }\n boolean valid(int[] r, int[] c) {\n     for (int i = 0; i < r.length; i++) {\n         if (i > 0 && r[i] > r[i - 1] && c[i] <= c[i - 1]) return false;\n         if (i + 1 < r.length && r[i] > r[i + 1] && c[i] <= c[i + 1]) return false;\n     }\n     return true;\n }\n int sum(int[] c) {\n     int s = 0;\n     for (int x : c) s += x;\n     return s;\n }"},{"label":"Optimal","explanation":"Two passes. Left to right: if rating rises, candy is one more than the left neighbor, else one. Right to left: if rating rises  versus  the  right  neighbor,  take  max  with  right  neighbor  plus  one.  Each  pass  enforces  one  side  of  the constraint; the max merges both.","complexity":"O(n) time, O(n) space.","code":"int candy(int[] ratings) {\n     int n = ratings.length;\n     int[] c = new int[n];\n     Arrays.fill(c, 1);\n     for (int i = 1; i < n; i++)\n         if (ratings[i] > ratings[i - 1]) c[i] = c[i - 1] + 1;\n     for (int i = n - 2; i >= 0; i--)\n         if (ratings[i] > ratings[i + 1]) c[i] = Math.max(c[i], c[i + 1] + 1);\n     int sum = 0;\n     for (int x : c) sum += x;\n     return sum;\n }"}]},{"id":105,"title":"Insert Interval","module":"Greedy","approaches":[{"label":"Brute force","explanation":"Append the new interval to the list, then run the standard merge-intervals routine until no overlaps remain. Simple and reuses merge logic, but touches every interval twice.","complexity":"O(n log n) time if merge sorts, O(n) space.","code":"int[][] insertAndMerge(int[][] intervals, int[] ni) {\n     List<int[]> list = new ArrayList<>(Arrays.asList(intervals));\n     list.add(ni);\n     list.sort(Comparator.comparingInt(a -> a[0]));\n     List<int[]> out = new ArrayList<>();\n     for (int[] iv : list) {\n         if (out.isEmpty() || out.get(out.size() - 1)[1] < iv[0]) out.add(iv);\n         else out.get(out.size() - 1)[1] = Math.max(out.get(out.size() - 1)[1], iv[1]);\n     }\n     return out.toArray(new int[out.size()][]);\n }"},{"label":"Optimal","explanation":"One  scan:  add  intervals  that  end  before  the  new  start;  merge  overlapping  intervals  into  the  new  interval  by expanding  its  end;  append  the  rest  unchanged.  No  full  sort  because  existing  intervals  are  already  sorted  and disjoint.","complexity":"O(n) time, O(n) space for output.","code":"int[][] insert(int[][] intervals, int[] ni) {\n     List<int[]> out = new ArrayList<>();\n     int i = 0, n = intervals.length;\n     while (i < n && intervals[i][1] < ni[0]) out.add(intervals[i++]);\n     while (i < n && intervals[i][0] <= ni[1]) {\n         ni[0] = Math.min(ni[0], intervals[i][0]);\n         ni[1] = Math.max(ni[1], intervals[i][1]);\n         i++;\n     }\n     out.add(ni);\n     while (i < n) out.add(intervals[i++]);\n     return out.toArray(new int[out.size()][]);\n }"}]},{"id":106,"title":"Merge Intervals","module":"Greedy","approaches":[{"label":"Brute force","explanation":"Repeatedly scan for any pair of overlapping intervals, merge them into one, and restart until a full pass finds no overlap. Correct but each merge can shift many intervals.","complexity":"O(n^3) time worst case, O(n) space.","code":"int[][] mergeBrute(int[][] intervals) {\n     List<int[]> list = new ArrayList<>();\n     for (int[] iv : intervals) list.add(new int[]{iv[0], iv[1]});\n     boolean merged;\n     do {\n         merged = false;\n         for (int i = 0; i < list.size(); i++) {\n             for (int j = i + 1; j < list.size(); j++) {\n                 int[] a = list.get(i), b = list.get(j);\n                 if (a[0] <= b[1] && b[0] <= a[1]) {\n                     int[] m = new int[]{Math.min(a[0], b[0]), Math.max(a[1], b[1])};\n                     list.remove(j);\n                     list.remove(i);\n                     list.add(m);\n                     merged = true;\n                     break;\n                 }\n             }\n             if (merged) break;\n         }\n     } while (merged);\n     return list.toArray(new int[list.size()][]);\n }"},{"label":"Optimal","explanation":"Sort by start time. The current merged interval extends its end when the next interval starts on or before that end; otherwise push the current interval and start a new one. After sorting, one left-to-right pass is enough.","complexity":"O(n log n) time, O(n) space for output.","code":"int[][] merge(int[][] intervals) {\n     Arrays.sort(intervals, (x, y) -> Integer.compare(x[0], y[0]));\n     List<int[]> out = new ArrayList<>();\n     int[] cur = intervals[0];\n     for (int i = 1; i < intervals.length; i++) {\n         if (intervals[i][0] <= cur[1]) cur[1] = Math.max(cur[1], intervals[i][1]);\n         else { out.add(cur); cur = intervals[i]; }\n     }\n     out.add(cur);\n     return out.toArray(new int[out.size()][]);\n }"}]},{"id":107,"title":"Kth Largest Element in an Array","module":"Heaps","approaches":[{"label":"Better","explanation":"Sort descending and return the element at index k - 1. Simple and fast when k is large relative to n, but sorts the whole array.","complexity":"O(n log n) time, O(1) extra space if sorting in place.","code":"int findKthLargestSort(int[] nums, int k) {\n     Arrays.sort(nums);\n     return nums[nums.length - k];\n }"},{"label":"Optimal","explanation":"Maintain a min-heap of size k. Each new value evicts the smallest among the k when it is larger. After one pass, the root is the kth largest. Memory stays O(k) instead of sorting all n.","complexity":"O(n log k) time, O(k) space.","code":"int findKthLargest(int[] nums, int k) {\n     PriorityQueue<Integer> pq = new PriorityQueue<>();\n     for (int x : nums) {\n         pq.offer(x);\n         if (pq.size() > k) pq.poll();\n     }\n     return pq.peek();\n }"}]},{"id":108,"title":"Kth Smallest Element in an Array","module":"Heaps","approaches":[{"label":"Better","explanation":"Sort ascending and read index k - 1. Same trade-off as sorting for the kth largest.","complexity":"O(n log n) time, O(1) extra space if sorting in place.","code":"int findKthSmallestSort(int[] nums, int k) {\n     Arrays.sort(nums);\n     return nums[k - 1];\n }"},{"label":"Optimal","explanation":"Keep a max-heap of size k. When a new value is smaller than the heap maximum, replace the max. The root after scanning is the kth smallest.","complexity":"O(n log k) time, O(k) space.","code":"int findKthSmallest(int[] nums, int k) {\n     PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());\n     for (int x : nums) {\n         pq.offer(x);\n         if (pq.size() > k) pq.poll();\n     }\n     return pq.peek();\n }"}]},{"id":109,"title":"Top K Frequent Elements","module":"Heaps","approaches":[{"label":"Better","explanation":"Count frequencies in a hash map, copy entries to a list, and sort by frequency descending. Take the first k keys.","complexity":"O(n + u log u) time where u is distinct keys, O(u) space.","code":"int[] topKFrequentSort(int[] nums, int k) {\n     Map<Integer, Integer> cnt = new HashMap<>();\n     for (int x : nums) cnt.put(x, cnt.getOrDefault(x, 0) + 1);\n     List<Integer> keys = new ArrayList<>(cnt.keySet());\n     keys.sort((a, b) -> cnt.get(b) - cnt.get(a));\n     int[] ans = new int[k];\n     for (int i = 0; i < k; i++) ans[i] = keys.get(i);\n     return ans;\n }"},{"label":"Optimal","explanation":"After counting, maintain a min-heap of size k ordered by frequency. Each entry beats the weakest frequent element in the heap. The heap holds the k most frequent when the scan finishes.","complexity":"O(n + u log k) time, O(u) space.","code":"int[] topKFrequent(int[] nums, int k) {\n     Map<Integer, Integer> cnt = new HashMap<>();\n     for (int x : nums) cnt.put(x, cnt.getOrDefault(x, 0) + 1);\n     PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] - b[1]);\n     for (var e : cnt.entrySet()) {\n         pq.offer(new int[]{e.getKey(), e.getValue()});\n         if (pq.size() > k) pq.poll();\n     }\n     int[] ans = new int[k];\n     for (int i = k - 1; i >= 0; i--) ans[i] = pq.poll()[0];\n     return ans;\n }"}]},{"id":110,"title":"Merge K Sorted Lists","module":"Heaps","approaches":[{"label":"Brute force","explanation":"Merge  lists  two  at  a  time:  merge  the  first  two,  then  merge  that  result  with  the  third,  and  so  on.  Early  merges produce long lists that are scanned again and again.","complexity":"O(kN) time where N is total nodes, O(1) extra besides output.","code":"ListNode mergeKListsBrute(ListNode[] lists) {\n     ListNode head = null;\n     for (ListNode node : lists)\n         head = mergeTwoLists(head, node);\n     return head;\n }\n ListNode mergeTwoLists(ListNode a, ListNode b) {\n     ListNode dummy = new ListNode(0), cur = dummy;\n     while (a != null && b != null) {\n         if (a.val <= b.val) { cur.next = a; a = a.next; }\n         else { cur.next = b; b = b.next; }\n         cur = cur.next;\n     }\n     cur.next = a != null ? a : b;\n     return dummy.next;\n }"},{"label":"Optimal","explanation":"Push  the  head  of  every  non-empty  list  into  a  min-heap  keyed  by  node  value.  Pop  the  smallest,  attach  it  to  the answer, and push its next if any. Always pick the global minimum among list fronts.","complexity":"O(N log k) time, O(k) heap space.","code":"ListNode mergeKLists(ListNode[] lists) {\n     PriorityQueue<ListNode> pq = new PriorityQueue<>((a, b) -> a.val - b.val);\n     for (ListNode n : lists) if (n != null) pq.offer(n);\n     ListNode dummy = new ListNode(0), cur = dummy;\n     while (!pq.isEmpty()) {\n         ListNode node = pq.poll();\n         cur.next = node;\n         cur = cur.next;\n         if (node.next != null) pq.offer(node.next);\n     }\n     return dummy.next;\n }"}]},{"id":111,"title":"Merge K Sorted Arrays","module":"Heaps","approaches":[{"label":"Brute force","explanation":"Concatenate  all  arrays  and  sort  the  combined  result.  Correct  and  easy,  but  ignores  the  fact  that  each  array  is already sorted.","complexity":"O(N log N) time for N total elements, O(N) space.","code":"int[] mergeKSortedBrute(int[][] arrays) {\n     int total = 0;\n     for (int[] a : arrays) total += a.length;\n     int[] all = new int[total];\n     int p = 0;\n     for (int[] a : arrays) for (int x : a) all[p++] = x;\n     Arrays.sort(all);\n     return all;\n }"},{"label":"Optimal","explanation":"Store  triples  (value,  array  index,  position)  in  a  min-heap.  Pop  the  smallest  value,  append  it,  and  push  the  next element from the same array if it exists. Same idea as merging k lists, on raw arrays.","complexity":"O(N log k) time, O(k) heap space.","code":"int[] mergeKSorted(int[][] arrays) {\n     PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);\n     for (int i = 0; i < arrays.length; i++)\n         if (arrays[i].length > 0) pq.offer(new int[]{arrays[i][0], i, 0});\n     List<Integer> out = new ArrayList<>();\n     while (!pq.isEmpty()) {\n         int[] t = pq.poll();\n         out.add(t[0]);\n         int ai = t[1], pos = t[2] + 1;\n         if (pos < arrays[ai].length)\n             pq.offer(new int[]{arrays[ai][pos], ai, pos});\n     }\n     return out.stream().mapToInt(Integer::intValue).toArray();\n }"}]},{"id":112,"title":"Find Median from Data Stream","module":"Heaps","approaches":[{"label":"Brute force","explanation":"Store every number in a list. On median query, sort the list and return the middle element or average of the two middles. addNum is cheap; findMedian is not.","complexity":"O(1) addNum, O(n log n) findMedian, O(n) space.","code":"class MedianFinderBrute {\n     List<Integer> a = new ArrayList<>();\n     void addNum(int num) { a.add(num); }\n     double findMedian() {\n         Collections.sort(a);\n         int n = a.size();\n         if ((n & 1) == 1) return a.get(n / 2);\n         return (a.get(n / 2 - 1) + a.get(n / 2)) / 2.0;\n     }\n }"},{"label":"Optimal","explanation":"Two heaps: max-heap for the lower half, min-heap for the upper half. Keep sizes within one and every lower value at or below every upper value by rebalancing after each insert. The median is the top of the larger heap or the average of both tops.","complexity":"O(log n) addNum, O(1) findMedian, O(n) space.","code":"class MedianFinder {\n     PriorityQueue<Integer> lo = new PriorityQueue<>(Collections.reverseOrder());\n     PriorityQueue<Integer> hi = new PriorityQueue<>();\n     void addNum(int num) {\n         lo.offer(num);\n         hi.offer(lo.poll());\n         if (lo.size() < hi.size()) lo.offer(hi.poll());\n     }\n     double findMedian() {\n         return lo.size() > hi.size() ? lo.peek() : (lo.peek() + hi.peek()) / 2.0;\n     }\n }"}]},{"id":113,"title":"K Closest Points to Origin","module":"Heaps","approaches":[{"label":"Better","explanation":"Sort points by squared distance to the origin and take the first k. No square root is needed because squaring is monotonic for non-negative distances.","complexity":"O(n log n) time, O(1) extra besides output.","code":"int[][] kClosestSort(int[][] points, int k) {\n     Arrays.sort(points, (a, b) -> dist(a) - dist(b));\n     int[][] ans = new int[k][];\n     for (int i = 0; i < k; i++) ans[i] = points[i];\n     return ans;\n }\n int dist(int[] p) { return p[0] * p[0] + p[1] * p[1]; }"},{"label":"Optimal","explanation":"Maintain a max-heap of size k by squared distance. A new point replaces the heap top only if it is closer than the farthest of the current k. The heap then holds the k closest points.","complexity":"O(n log k) time, O(k) space.","code":"int[][] kClosest(int[][] points, int k) {\n     PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> dist(b) - dist(a));\n     for (int[] p : points) {\n         pq.offer(p);\n         if (pq.size() > k) pq.poll();\n     }\n     int[][] ans = new int[k][];\n     for (int i = k - 1; i >= 0; i--) ans[i] = pq.poll();\n     return ans;\n }\n int dist(int[] p) { return p[0] * p[0] + p[1] * p[1]; }"}]},{"id":114,"title":"Task Scheduler","module":"Heaps","approaches":[{"label":"Better","explanation":"Count task frequencies and sort descending. Greedily fill slots of length n + 1 with the most frequent remaining tasks, separated by idle gaps, until all tasks are placed. Math on idle slots gives the same answer without a heap.","complexity":"O(m) time for m tasks, O(1) space for 26 letters.","code":"int leastIntervalMath(char[] tasks, int n) {\n     int[] cnt = new int[26];\n     for (char c : tasks) cnt[c - 'A']++;\n     Arrays.sort(cnt);\n     int maxF = cnt[25], same = 1;\n     for (int i = 24; i >= 0 && cnt[i] == maxF; i--) same++;\n     int part = (maxF - 1) * (n + 1) + same;\n     return Math.max(part, tasks.length);\n }"},{"label":"Optimal","explanation":"Max-heap of remaining counts. Each round of n + 1 slots pops up to n + 1 tasks, decrements them, and pushes back positive counts. Idle time appears when the heap is empty inside a round. Mirrors the schedule construction directly.","complexity":"O(m log 26) time, O(1) space.","code":"int leastInterval(char[] tasks, int n) {\n     int[] cnt = new int[26];\n     for (char c : tasks) cnt[c - 'A']++;\n     PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());\n     for (int x : cnt) if (x > 0) pq.offer(x);\n     int time = 0;\n     while (!pq.isEmpty()) {\n         List<Integer> tmp = new ArrayList<>();\n         for (int i = 0; i <= n; i++) {\n             if (pq.isEmpty()) break;\n             int f = pq.poll() - 1;\n             if (f > 0) tmp.add(f);\n         }\n         time += pq.isEmpty() ? tmp.size() : n + 1;\n         for (int f : tmp) pq.offer(f);\n     }\n     return time;\n }"}]},{"id":115,"title":"Reorganize String","module":"Heaps","approaches":[{"label":"Brute force","explanation":"Try to build the string position by position: at each index, try every character with positive count that differs from the previous character. Backtrack on failure. Correct for small alphabets only.","complexity":"O(k^n) time in worst case, O(n) space.","code":"boolean reorganizeBrute(String s, StringBuilder path, int[] cnt, char prev) {\n     if (path.length() == s.length()) return true;\n     for (int c = 0; c < 26; c++) {\n         if (cnt[c] == 0 || (char) ('a' + c) == prev) continue;\n         cnt[c]--;\n         path.append((char) ('a' + c));\n         if (reorganizeBrute(s, path, cnt, (char) ('a' + c))) return true;\n         path.deleteCharAt(path.length() - 1);\n         cnt[c]++;\n     }\n     return false;\n }"},{"label":"Optimal","explanation":"Max-heap by count. Append the most frequent character that is not the same as the last placed; push the previous character back if its count remains. If the top repeats the last, the string is impossible. A letter with more than half the length cannot be placed without adjacency.","complexity":"O(n log 26) time, O(26) space.","code":"String reorganizeString(String s) {\n     int[] cnt = new int[26];\n     for (char c : s.toCharArray()) cnt[c - 'a']++;\n     PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[1] - a[1]);\n     for (int i = 0; i < 26; i++) if (cnt[i] > 0) pq.offer(new int[]{i, cnt[i]});\n     StringBuilder sb = new StringBuilder();\n     while (!pq.isEmpty()) {\n         int[] cur = pq.poll();\n         if (sb.length() > 0 && sb.charAt(sb.length() - 1) == (char) ('a' + cur[0])) {\n             if (pq.isEmpty()) return \"\";\n             int[] nxt = pq.poll();\n             sb.append((char) ('a' + nxt[0]));\n             if (--nxt[1] > 0) pq.offer(nxt);\n             pq.offer(cur);\n         } else {\n             sb.append((char) ('a' + cur[0]));\n             if (--cur[1] > 0) pq.offer(cur);\n         }\n     }\n     return sb.toString();\n }"}]},{"id":116,"title":"Kth Largest Element in a Stream","module":"Heaps","approaches":[{"label":"Better","explanation":"Keep all numbers seen so far in a list. On each add, sort descending and return the element at index k - 1. Simple but resorts the full history every time.","complexity":"O(m log m) per add for m elements so far, O(m) space.","code":"class KthLargestSort {\n     List<Integer> a = new ArrayList<>();\n     int k;\n     KthLargestSort(int k, int[] nums) {\n         this.k = k;\n         for (int x : nums) a.add(x);\n     }\n     int add(int val) {\n         a.add(val);\n         Collections.sort(a, Collections.reverseOrder());\n         return a.get(k - 1);\n     }\n }"},{"label":"Optimal","explanation":"Min-heap of size k holds the k largest elements seen. add pushes the new value and drops the smallest if size exceeds k. The root is always the kth largest in the stream.","complexity":"O(log k) per add, O(k) space.","code":"class KthLargest {\n     PriorityQueue<Integer> pq = new PriorityQueue<>();\n     int k;\n     KthLargest(int k, int[] nums) {\n         this.k = k;\n         for (int x : nums) add(x);\n     }\n     int add(int val) {\n         pq.offer(val);\n         if (pq.size() > k) pq.poll();\n         return pq.peek();\n     }\n }"}]},{"id":117,"title":"Preorder Traversal","module":"Binary Trees","approaches":[{"label":"Optimal","explanation":"Visit root, then left, then right. Recursion mirrors the definition: record the value, then trust the same function on left and right. An empty child is a no-op.","complexity":"O(n) time, O(h) recursion stack.","code":"List<Integer> preorder(TreeNode root) {\n     List<Integer> ans = new ArrayList<>();\n     dfsPre(root, ans);\n     return ans;\n }\n void dfsPre(TreeNode node, List<Integer> ans) {\n     if (node == null) return;\n     ans.add(node.val);\n     dfsPre(node.left, ans);\n     dfsPre(node.right, ans);\n }"},{"label":"Better","explanation":"Iterative preorder uses a stack that always holds the next node to visit. Pop, record, push right then left so left is popped first. No recursion stack overflow on deep skewed trees.","complexity":"O(n) time, O(h) explicit stack.","code":"List<Integer> preorderIterative(TreeNode root) {\n     List<Integer> ans = new ArrayList<>();\n     if (root == null) return ans;\n     Deque<TreeNode> st = new ArrayDeque<>();\n     st.push(root);\n     while (!st.isEmpty()) {\n         TreeNode node = st.pop();\n         ans.add(node.val);\n         if (node.right != null) st.push(node.right);\n         if (node.left != null) st.push(node.left);\n     }\n     return ans;\n }"}]},{"id":118,"title":"Inorder Traversal","module":"Binary Trees","approaches":[{"label":"Optimal","explanation":"Inorder is left, root, right. On a BST this order is sorted. Recursion walks left until null, records, then walks right.","complexity":"O(n) time, O(h) stack.","code":"List<Integer> inorder(TreeNode root) {\n     List<Integer> ans = new ArrayList<>();\n     dfsIn(root, ans);\n     return ans;\n }\n void dfsIn(TreeNode node, List<Integer> ans) {\n     if (node == null) return;\n     dfsIn(node.left, ans);\n     ans.add(node.val);\n     dfsIn(node.right, ans);\n }"},{"label":"Better","explanation":"Morris  inorder  threads  the  tree:  when  there  is  no  left  child,  visit  and  go  right.  When  there  is  a  left  child,  find  its inorder predecessor. If its right link is null, link it to the current node and go left. If the link already points back, unlink, visit, go right. No stack and O(1) extra space aside from the output.","complexity":"O(n) time, O(1) extra space.","code":"List<Integer> inorderMorris(TreeNode root) {\n     List<Integer> ans = new ArrayList<>();\n     TreeNode cur = root;\n     while (cur != null) {\n         if (cur.left == null) {\n             ans.add(cur.val);\n             cur = cur.right;\n         } else {\n             TreeNode pred = cur.left;\n             while (pred.right != null && pred.right != cur) pred = pred.right;\n             if (pred.right == null) {\n                 pred.right = cur;\n                 cur = cur.left;\n             } else {\n                 pred.right = null;\n                 ans.add(cur.val);\n                 cur = cur.right;\n             }\n         }\n     }\n     return ans;\n }"}]},{"id":119,"title":"Postorder Traversal","module":"Binary Trees","approaches":[{"label":"Optimal","explanation":"Postorder is left, right, root. Recursion must finish both subtrees before recording the node. That order is natural for problems that delete or aggregate bottom-up.","complexity":"O(n) time, O(h) stack.","code":"List<Integer> postorder(TreeNode root) {\n     List<Integer> ans = new ArrayList<>();\n     dfsPost(root, ans);\n     return ans;\n }\n void dfsPost(TreeNode node, List<Integer> ans) {\n     if (node == null) return;\n     dfsPost(node.left, ans);\n     dfsPost(node.right, ans);\n     ans.add(node.val);\n }"},{"label":"Better","explanation":"One stack variant pushes root, then repeatedly pops. If the popped node is not the stack's top left/right child in the right order, push it back and push its children so they are handled first. A last pointer tracks the last visited node to avoid revisiting.","complexity":"O(n) time, O(h) stack.","code":"List<Integer> postorderIterative(TreeNode root) {\n     List<Integer> ans = new ArrayList<>();\n     if (root == null) return ans;\n     Deque<TreeNode> st = new ArrayDeque<>();\n     st.push(root);\n     TreeNode last = null;\n     while (!st.isEmpty()) {\n         TreeNode peek = st.peek();\n         if (peek.left != null && last != peek.left && last != peek.right)\n             st.push(peek.left);\n         else if (peek.right != null && last != peek.right)\n             st.push(peek.right);\n         else {\n             last = st.pop();\n             ans.add(last.val);\n         }\n     }\n     return ans;\n }"}]},{"id":120,"title":"Level Order Traversal","module":"Binary Trees","approaches":[{"label":"Brute force","explanation":"For each depth d from 0 to height, scan the whole tree and collect nodes at depth d. Correct but revisits nodes many times.","complexity":"O(n * h) time, O(h) output per level.","code":"List<List<Integer>> levelOrderBrute(TreeNode root) {\n     List<List<Integer>> ans = new ArrayList<>();\n     int h = height(root);\n     for (int d = 0; d <= h; d++) {\n         List<Integer> row = new ArrayList<>();\n         collectDepth(root, d, row);\n         if (!row.isEmpty()) ans.add(row);\n     }\n     return ans;\n }\n int height(TreeNode node) {\n     if (node == null) return -1;\n     return 1 + Math.max(height(node.left), height(node.right));\n }\n void collectDepth(TreeNode node, int d, List<Integer> row) {\n     if (node == null) return;\n     if (d == 0) row.add(node.val);\n     else {\n         collectDepth(node.left, d - 1, row);\n         collectDepth(node.right, d - 1, row);\n     }\n }"},{"label":"Optimal","explanation":"BFS with a queue holds the frontier of the current level. Record the queue size before dequeuing so each level is its own list. Enqueue children left to right for standard order.","complexity":"O(n) time, O(w) space where w is max width.","code":"List<List<Integer>> levelOrder(TreeNode root) {\n     List<List<Integer>> ans = new ArrayList<>();\n     if (root == null) return ans;\n     Queue<TreeNode> q = new ArrayDeque<>();\n     q.offer(root);\n     while (!q.isEmpty()) {\n         int sz = q.size();\n         List<Integer> row = new ArrayList<>();\n         for (int i = 0; i < sz; i++) {\n             TreeNode node = q.poll();\n             row.add(node.val);\n             if (node.left != null) q.offer(node.left);\n             if (node.right != null) q.offer(node.right);\n         }\n         ans.add(row);\n     }\n     return ans;\n }"}]},{"id":121,"title":"Maximum Depth of Binary Tree","module":"Binary Trees","approaches":[{"label":"Brute force","explanation":"At every node recompute the height of left and right by full subtree walks. Each node is counted in many height calls.","complexity":"O(n^2) time on a skewed tree, O(h) stack.","code":"int maxDepthBrute(TreeNode root) {\n     if (root == null) return 0;\n     return 1 + Math.max(maxDepthBrute(root.left), maxDepthBrute(root.right));\n }"},{"label":"Optimal","explanation":"Single post-order pass: depth of a node is one plus the max of child depths. One visit per node.","complexity":"O(n) time, O(h) stack.","code":"int maxDepth(TreeNode root) {\n     if (root == null) return 0;\n     return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));\n }"}]},{"id":122,"title":"Diameter of Binary Tree","module":"Binary Trees","approaches":[{"label":"Brute force","explanation":"For every node, compute left height and right height independently and take their sum as a candidate diameter. Heights are recomputed from scratch each time.","complexity":"O(n^2) time, O(h) stack.","code":"int diameterBrute(TreeNode root) {\n     if (root == null) return 0;\n     int through = height(root.left) + height(root.right);\n     return Math.max(through, Math.max(diameterBrute(root.left), diameterBrute(root.right)));\n }\n int height(TreeNode node) {\n     if (node == null) return 0;\n     return 1 + Math.max(height(node.left), height(node.right));\n }"},{"label":"Optimal","explanation":"While computing height bottom-up, the longest path through the current node is leftHeight + rightHeight. Track the global maximum during the same DFS that returns height to the parent.","complexity":"O(n) time, O(h) stack.","code":"int diameterOfBinaryTree(TreeNode root) {\n     int[] best = new int[1];\n     heightDiameter(root, best);\n     return best[0];\n }\n int heightDiameter(TreeNode node, int[] best) {\n     if (node == null) return 0;\n     int L = heightDiameter(node.left, best);\n     int R = heightDiameter(node.right, best);\n     best[0] = Math.max(best[0], L + R);\n     return 1 + Math.max(L, R);\n }"}]},{"id":123,"title":"Balanced Binary Tree","module":"Binary Trees","approaches":[{"label":"Brute force","explanation":"A tree is balanced when every node's left and right heights differ by at most one. Check that predicate at every node with fresh height computations.","complexity":"O(n^2) time, O(h) stack.","code":"boolean isBalancedBrute(TreeNode root) {\n     if (root == null) return true;\n     int diff = Math.abs(height(root.left) - height(root.right));\n     return diff <= 1 && isBalancedBrute(root.left) && isBalancedBrute(root.right);\n }\n int height(TreeNode node) {\n     if (node == null) return 0;\n     return 1 + Math.max(height(node.left), height(node.right));\n }"},{"label":"Optimal","explanation":"Return height from DFS but use -1 as a sentinel when a subtree is already unbalanced. If either child fails or the current skew exceeds one, bubble -1 up immediately.","complexity":"O(n) time, O(h) stack.","code":"boolean isBalanced(TreeNode root) {\n     return checkBalance(root) != -1;\n }\n int checkBalance(TreeNode node) {\n     if (node == null) return 0;\n     int L = checkBalance(node.left);\n     if (L == -1) return -1;\n     int R = checkBalance(node.right);\n     if (R == -1) return -1;\n     if (Math.abs(L - R) > 1) return -1;\n     return 1 + Math.max(L, R);\n }"}]},{"id":124,"title":"Maximum Path Sum","module":"Binary Trees","approaches":[{"label":"Brute force","explanation":"Try  every  node  as  the  highest  point  of  a  path  and  explore  all  downward  paths  in  its  left  and  right  subtrees  to maximize sum. Exponential in path choices without pruning.","complexity":"O(2^n) time in worst case, O(h) stack.","code":"int maxPathSumBrute(TreeNode root) {\n     if (root == null) return Integer.MIN_VALUE / 4;\n     int alone = root.val;\n     int withLeft = root.val + bestDown(root.left);\n     int withRight = root.val + bestDown(root.right);\n     int through = root.val + bestDown(root.left) + bestDown(root.right);\n     int bestHere = Math.max(alone, Math.max(withLeft, Math.max(withRight, through)));\n     return Math.max(bestHere, Math.max(maxPathSumBrute(root.left), maxPathSumBrute(root.right)));\n }\n int bestDown(TreeNode node) {\n     if (node == null) return 0;\n     return Math.max(0, node.val + Math.max(bestDown(node.left), bestDown(node.right)));\n }"},{"label":"Optimal","explanation":"For each node, the best downward path through it to offer a parent is node.val plus the better nonnegative child gain. The best path that uses this node as a bend is node.val plus both child gains. Update a global answer; return only the single-arm gain to the parent.","complexity":"O(n) time, O(h) stack.","code":"int maxPathSum(TreeNode root) {\n     int[] best = new int[]{Integer.MIN_VALUE / 4};\n     gain(root, best);\n     return best[0];\n }\n int gain(TreeNode node, int[] best) {\n     if (node == null) return 0;\n     int L = Math.max(0, gain(node.left, best));\n     int R = Math.max(0, gain(node.right, best));\n     best[0] = Math.max(best[0], node.val + L + R);\n     return node.val + Math.max(L, R);\n }"}]},{"id":125,"title":"Same Tree","module":"Binary Trees","approaches":[{"label":"Brute force","explanation":"Serialize both trees to the same traversal string and compare. Any traversal works if null markers are explicit.","complexity":"O(n) time, O(n) space for strings.","code":"boolean isSameTreeSerialize(TreeNode p, TreeNode q) {\n     return serialize(p).equals(serialize(q));\n }\n String serialize(TreeNode node) {\n     if (node == null) return \"#,\";\n     return node.val + \",\" + serialize(node.left) + serialize(node.right);\n }"},{"label":"Optimal","explanation":"Walk both roots together. Mismatch on null pairing or value means false. Otherwise both left pairs and both right pairs must match.","complexity":"O(n) time, O(h) stack.","code":"boolean isSameTree(TreeNode p, TreeNode q) {\n     if (p == null || q == null) return p == q;\n     return p.val == q.val && isSameTree(p.left, q.left) && isSameTree(p.right, q.right);\n }"}]},{"id":126,"title":"Symmetric Tree","module":"Binary Trees","approaches":[{"label":"Optimal","explanation":"Mirror equality: the outer pair (left.left, right.right) and inner pair (left.right, right.left) must match values and mirror structure. Base case is two null nodes.","complexity":"O(n) time, O(h) stack.","code":"boolean isSymmetric(TreeNode root) {\n     return root == null || mirror(root.left, root.right);\n }\n boolean mirror(TreeNode a, TreeNode b) {\n     if (a == null || b == null) return a == b;\n     return a.val == b.val && mirror(a.left, b.right) && mirror(a.right, b.left);\n }"},{"label":"Better","explanation":"Iterative BFS enqueues pairs that should mirror each other. Each level check compares front pairs before pushing children in mirror order.","complexity":"O(n) time, O(w) queue space.","code":"boolean isSymmetricBfs(TreeNode root) {\n     if (root == null) return true;\n     Queue<TreeNode> q = new ArrayDeque<>();\n     q.offer(root.left);\n     q.offer(root.right);\n     while (!q.isEmpty()) {\n         TreeNode a = q.poll(), b = q.poll();\n         if (a == null && b == null) continue;\n         if (a == null || b == null || a.val != b.val) return false;\n         q.offer(a.left); q.offer(b.right);\n         q.offer(a.right); q.offer(b.left);\n     }\n     return true;\n }"}]},{"id":127,"title":"Zigzag Level Order","module":"Binary Trees","approaches":[{"label":"Better","explanation":"Standard level order, then reverse every other row in the answer list.","complexity":"O(n) time, O(w) space.","code":"List<List<Integer>> zigzagLevelOrderReverse(TreeNode root) {\n     List<List<Integer>> ans = levelOrder(root);\n     for (int i = 1; i < ans.size(); i += 2) Collections.reverse(ans.get(i));\n     return ans;\n }\n List<List<Integer>> levelOrder(TreeNode root) {\n     List<List<Integer>> ans = new ArrayList<>();\n     if (root == null) return ans;\n     Queue<TreeNode> q = new ArrayDeque<>();\n     q.offer(root);\n     while (!q.isEmpty()) {\n         int sz = q.size();\n         List<Integer> row = new ArrayList<>();\n         for (int i = 0; i < sz; i++) {\n             TreeNode node = q.poll();\n             row.add(node.val);\n             if (node.left != null) q.offer(node.left);\n             if (node.right != null) q.offer(node.right);\n         }\n         ans.add(row);\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"Use a deque as the level container. Even levels append at the back; odd levels insert at the front so the row is built reversed without a second pass.","complexity":"O(n) time, O(w) space.","code":"List<List<Integer>> zigzagLevelOrder(TreeNode root) {\n     List<List<Integer>> ans = new ArrayList<>();\n     if (root == null) return ans;\n     Queue<TreeNode> q = new ArrayDeque<>();\n     q.offer(root);\n     boolean leftToRight = true;\n     while (!q.isEmpty()) {\n         int sz = q.size();\n         LinkedList<Integer> row = new LinkedList<>();\n         for (int i = 0; i < sz; i++) {\n             TreeNode node = q.poll();\n             if (leftToRight) row.addLast(node.val);\n             else row.addFirst(node.val);\n             if (node.left != null) q.offer(node.left);\n             if (node.right != null) q.offer(node.right);\n         }\n         ans.add(row);\n         leftToRight = !leftToRight;\n     }\n     return ans;\n }"}]},{"id":128,"title":"Right Side View","module":"Binary Trees","approaches":[{"label":"Brute force","explanation":"For each depth, scan the tree and keep the last value seen at that depth during a preorder walk.","complexity":"O(n * h) time, O(h) stack.","code":"List<Integer> rightSideViewBrute(TreeNode root) {\n     List<Integer> ans = new ArrayList<>();\n     int h = maxDepth(root);\n     for (int d = 0; d < h; d++) {\n         int[] last = new int[]{0};\n         lastAtDepth(root, 0, d, last);\n         ans.add(last[0]);\n     }\n     return ans;\n }\n int maxDepth(TreeNode node) {\n     if (node == null) return 0;\n     return 1 + Math.max(maxDepth(node.left), maxDepth(node.right));\n }\n void lastAtDepth(TreeNode node, int cur, int target, int[] last) {\n     if (node == null) return;\n     if (cur == target) last[0] = node.val;\n     lastAtDepth(node.left, cur + 1, target, last);\n     lastAtDepth(node.right, cur + 1, target, last);\n }"},{"label":"Optimal","explanation":"BFS:  the  last  node  dequeued  at  each  level  is  visible  from  the  right.  DFS  preorder  visiting  right  before  left  also works: the first node hit at each depth wins.","complexity":"O(n) time, O(h) stack or O(w) queue.","code":"List<Integer> rightSideView(TreeNode root) {\n     List<Integer> ans = new ArrayList<>();\n     if (root == null) return ans;\n     dfsRight(root, 0, ans);\n     return ans;\n }\n void dfsRight(TreeNode node, int depth, List<Integer> ans) {\n     if (node == null) return;\n     if (depth == ans.size()) ans.add(node.val);\n     dfsRight(node.right, depth + 1, ans);\n     dfsRight(node.left, depth + 1, ans);\n }"}]},{"id":129,"title":"Boundary Traversal","module":"Binary Trees","approaches":[{"label":"Optimal","explanation":"Anti-clockwise  boundary:  root,  left  boundary  (exclude  leaves),  all  leaves  left  to  right,  right  boundary  bottom-up (exclude leaves). Mark leaves during left/right boundary walks so they are not duplicated.","complexity":"O(n) time, O(h) stack.","code":"List<Integer> boundaryTraversal(TreeNode root) {\n     List<Integer> ans = new ArrayList<>();\n     if (root == null) return ans;\n     if (!isLeaf(root)) ans.add(root.val);\n     addLeftBoundary(root.left, ans);\n     addLeaves(root, ans);\n     addRightBoundary(root.right, ans);\n     return ans;\n }\n boolean isLeaf(TreeNode node) {\n     return node != null && node.left == null && node.right == null;\n }\n void addLeftBoundary(TreeNode node, List<Integer> ans) {\n     while (node != null) {\n         if (!isLeaf(node)) ans.add(node.val);\n         node = node.left != null ? node.left : node.right;\n     }\n }\n void addLeaves(TreeNode node, List<Integer> ans) {\n     if (node == null) return;\n     if (isLeaf(node)) { ans.add(node.val); return; }\n     addLeaves(node.left, ans);\n     addLeaves(node.right, ans);\n }\n void addRightBoundary(TreeNode node, List<Integer> ans) {\n     Deque<Integer> stack = new ArrayDeque<>();\n     while (node != null) {\n         if (!isLeaf(node)) stack.push(node.val);\n         node = node.right != null ? node.right : node.left;\n     }\n     while (!stack.isEmpty()) ans.add(stack.pop());\n }"}]},{"id":130,"title":"Construct from Preorder and Inorder","module":"Binary Trees","approaches":[{"label":"Brute force","explanation":"The first preorder value is the root. Find it in inorder; everything left of that index is the left subtree, everything right is the right subtree. Recurse on the corresponding subarrays. Each step scans inorder for the root value.","complexity":"O(n^2) time, O(n) space.","code":"TreeNode buildTree(int[] pre, int[] in) {\n     return build(pre, 0, pre.length - 1, in, 0, in.length - 1);\n }\n TreeNode build(int[] pre, int pl, int pr, int[] in, int il, int ir) {\n     if (pl > pr) return null;\n     int rootVal = pre[pl];\n     int k = il;\n     while (in[k] != rootVal) k++;\n     int leftSize = k - il;\n     TreeNode root = new TreeNode(rootVal);\n     root.left = build(pre, pl + 1, pl + leftSize, in, il, k - 1);\n     root.right = build(pre, pl + leftSize + 1, pr, in, k + 1, ir);\n     return root;\n }"},{"label":"Optimal","explanation":"Hash inorder indices once. A preorder pointer picks the next root. Inorder bounds tell whether that root belongs in the current subtree. Recursion only chooses left or right child based on index comparisons.","complexity":"O(n) time, O(n) space.","code":"TreeNode buildTreeOpt(int[] pre, int[] in) {\n     Map<Integer, Integer> idx = new HashMap<>();\n     for (int i = 0; i < in.length; i++) idx.put(in[i], i);\n     int[] p = new int[]{0};\n     return build(pre, idx, p, 0, in.length - 1);\n }\n TreeNode build(int[] pre, Map<Integer, Integer> idx, int[] p, int lo, int hi) {\n     if (lo > hi) return null;\n     int val = pre[p[0]++];\n     TreeNode root = new TreeNode(val);\n     int mid = idx.get(val);\n     root.left = build(pre, idx, p, lo, mid - 1);\n     root.right = build(pre, idx, p, mid + 1, hi);\n     return root;\n }"}]},{"id":131,"title":"Lowest Common Ancestor","module":"Binary Trees","approaches":[{"label":"Brute force","explanation":"Build parent pointers from the root with BFS. Walk both nodes to the root recording depth. Align depths, then step both upward until they meet.","complexity":"O(n) time, O(n) space.","code":"TreeNode lowestCommonAncestorParent(TreeNode root, TreeNode p, TreeNode q) {\n     Map<TreeNode, TreeNode> par = new HashMap<>();\n     par.put(root, null);\n     Queue<TreeNode> qu = new ArrayDeque<>();\n     qu.offer(root);\n     while (!qu.isEmpty()) {\n         TreeNode node = qu.poll();\n         if (node.left != null) { par.put(node.left, node); qu.offer(node.left); }\n         if (node.right != null) { par.put(node.right, node); qu.offer(node.right); }\n     }\n     Set<TreeNode> seen = new HashSet<>();\n     for (TreeNode cur = p; cur != null; cur = par.get(cur)) seen.add(cur);\n     for (TreeNode cur = q; cur != null; cur = par.get(cur))\n         if (seen.contains(cur)) return cur;\n     return null;\n }"},{"label":"Optimal","explanation":"Post-order: if the current node is p or q, return it. If both subtrees return non-null, current is the LCA. If only one side returns non-null, bubble that answer up.","complexity":"O(n) time, O(h) stack.","code":"TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\n     if (root == null || root == p || root == q) return root;\n     TreeNode L = lowestCommonAncestor(root.left, p, q);\n     TreeNode R = lowestCommonAncestor(root.right, p, q);\n     if (L != null && R != null) return root;\n     return L != null ? L : R;\n }"}]},{"id":132,"title":"Search in BST","module":"Binary Search Trees","approaches":[{"label":"Brute force","explanation":"Inorder the tree into a list and binary search the target. Correct but ignores the BST shape.","complexity":"O(n) time, O(n) space.","code":"boolean searchBSTBrute(TreeNode root, int target) {\n     List<Integer> vals = new ArrayList<>();\n     inorder(root, vals);\n     int lo = 0, hi = vals.size() - 1;\n     while (lo <= hi) {\n         int mid = (lo + hi) >>> 1;\n         if (vals.get(mid) == target) return true;\n         if (vals.get(mid) < target) lo = mid + 1;\n         else hi = mid - 1;\n     }\n     return false;\n }\n void inorder(TreeNode node, List<Integer> vals) {\n     if (node == null) return;\n     inorder(node.left, vals);\n     vals.add(node.val);\n     inorder(node.right, vals);\n }"},{"label":"Optimal","explanation":"Compare target with the current value. Equal means found. Smaller means recurse left; larger means recurse right. Null means absent.","complexity":"O(h) time, O(h) stack.","code":"TreeNode searchBST(TreeNode root, int val) {\n     if (root == null || root.val == val) return root;\n     return val < root.val ? searchBST(root.left, val) : searchBST(root.right, val);\n }"}]},{"id":133,"title":"Minimum Element in BST","module":"Binary Search Trees","approaches":[{"label":"Brute force","explanation":"Track the minimum while visiting every node in any traversal.","complexity":"O(n) time, O(h) stack.","code":"int minValueBrute(TreeNode root) {\n     if (root == null) throw new IllegalArgumentException();\n     int[] mn = new int[]{Integer.MAX_VALUE};\n     visit(root, mn);\n     return mn[0];\n }\n void visit(TreeNode node, int[] mn) {\n     if (node == null) return;\n     mn[0] = Math.min(mn[0], node.val);\n     visit(node.left, mn);\n     visit(node.right, mn);\n }"},{"label":"Optimal","explanation":"The smallest value sits at the leftmost chain. Walk left until null.","complexity":"O(h) time, O(1) space.","code":"int minValue(TreeNode root) {\n     while (root.left != null) root = root.left;\n     return root.val;\n }"}]},{"id":134,"title":"Insert into BST","module":"Binary Search Trees","approaches":[{"label":"Brute force","explanation":"Inorder to a sorted list, insert the value, rebuild a balanced BST from the array. Works but destroys the original structure.","complexity":"O(n) time, O(n) space.","code":"TreeNode insertIntoBSTBrute(TreeNode root, int val) {\n     List<Integer> vals = new ArrayList<>();\n     inorder(root, vals);\n     int i = 0;\n     while (i < vals.size() && vals.get(i) < val) i++;\n     vals.add(i, val);\n     return sortedArrayToBST(vals, 0, vals.size() - 1);\n }\n void inorder(TreeNode node, List<Integer> vals) {\n     if (node == null) return;\n     inorder(node.left, vals);\n     vals.add(node.val);\n     inorder(node.right, vals);\n }\n TreeNode sortedArrayToBST(List<Integer> a, int lo, int hi) {\n     if (lo > hi) return null;\n     int mid = (lo + hi) >>> 1;\n     TreeNode node = new TreeNode(a.get(mid));\n     node.left = sortedArrayToBST(a, lo, mid - 1);\n     node.right = sortedArrayToBST(a, mid + 1, hi);\n     return node;\n }"},{"label":"Optimal","explanation":"Walk until null: if val is smaller go left, else go right. Attach a new leaf at the empty child pointer.","complexity":"O(h) time, O(h) stack or O(1) iterative.","code":"TreeNode insertIntoBST(TreeNode root, int val) {\n     if (root == null) return new TreeNode(val);\n     TreeNode cur = root;\n     while (true) {\n         if (val < cur.val) {\n             if (cur.left == null) { cur.left = new TreeNode(val); break; }\n             cur = cur.left;\n         } else {\n             if (cur.right == null) { cur.right = new TreeNode(val); break; }\n             cur = cur.right;\n         }\n     }\n     return root;\n }"}]},{"id":135,"title":"Delete Node in BST","module":"Binary Search Trees","approaches":[{"label":"Optimal","explanation":"Find  the  node.  No  left  child:  return  right.  No  right  child:  return  left.  Two  children:  replace  value  with  inorder successor from the right subtree's leftmost node, then delete that successor value from the right subtree.","complexity":"O(h) time, O(h) stack.","code":"TreeNode deleteNode(TreeNode root, int key) {\n     if (root == null) return null;\n     if (key < root.val) root.left = deleteNode(root.left, key);\n     else if (key > root.val) root.right = deleteNode(root.right, key);\n     else {\n         if (root.left == null) return root.right;\n         if (root.right == null) return root.left;\n         TreeNode succ = root.right;\n         while (succ.left != null) succ = succ.left;\n         root.val = succ.val;\n         root.right = deleteNode(root.right, succ.val);\n     }\n     return root;\n }"}]},{"id":136,"title":"Validate BST","module":"Binary Search Trees","approaches":[{"label":"Brute force","explanation":"Inorder must be strictly increasing. Copy values to a list and check neighbors.","complexity":"O(n) time, O(n) space.","code":"boolean isValidBSTBrute(TreeNode root) {\n     List<Integer> vals = new ArrayList<>();\n     inorder(root, vals);\n     for (int i = 1; i < vals.size(); i++)\n         if (vals.get(i) <= vals.get(i - 1)) return false;\n     return true;\n }\n void inorder(TreeNode node, List<Integer> vals) {\n     if (node == null) return;\n     inorder(node.left, vals);\n     vals.add(node.val);\n     inorder(node.right, vals);\n }"},{"label":"Optimal","explanation":"Pass down an open interval (lo, hi) each node must satisfy. Left child tightens the upper bound; right child tightens the lower bound. Null is valid.","complexity":"O(n) time, O(h) stack.","code":"boolean isValidBST(TreeNode root) {\n     return valid(root, null, null);\n }\n boolean valid(TreeNode node, Integer lo, Integer hi) {\n     if (node == null) return true;\n     if (lo != null && node.val <= lo) return false;\n     if (hi != null && node.val >= hi) return false;\n     return valid(node.left, lo, node.val) && valid(node.right, node.val, hi);\n }"}]},{"id":137,"title":"LCA in BST","module":"Binary Search Trees","approaches":[{"label":"Brute force","explanation":"Use the general binary-tree LCA with parent maps or post-order. Ignores BST ordering.","complexity":"O(n) time, O(n) space.","code":"TreeNode lowestCommonAncestorBSTBrute(TreeNode root, TreeNode p, TreeNode q) {\n     Map<TreeNode, TreeNode> par = new HashMap<>();\n     par.put(root, null);\n     Queue<TreeNode> qu = new ArrayDeque<>();\n     qu.offer(root);\n     while (!qu.isEmpty()) {\n         TreeNode node = qu.poll();\n         if (node.left != null) { par.put(node.left, node); qu.offer(node.left); }\n         if (node.right != null) { par.put(node.right, node); qu.offer(node.right); }\n     }\n     Set<TreeNode> seen = new HashSet<>();\n     for (TreeNode cur = p; cur != null; cur = par.get(cur)) seen.add(cur);\n     for (TreeNode cur = q; cur != null; cur = par.get(cur))\n         if (seen.contains(cur)) return cur;\n     return null;\n }"},{"label":"Optimal","explanation":"If both targets are smaller, LCA is in the left subtree. If both larger, LCA is in the right. Otherwise the split happens at the current node, which is the LCA.","complexity":"O(h) time, O(1) space.","code":"TreeNode lowestCommonAncestorBST(TreeNode root, TreeNode p, TreeNode q) {\n     int a = p.val, b = q.val;\n     while (root != null) {\n         if (a < root.val && b < root.val) root = root.left;\n         else if (a > root.val && b > root.val) root = root.right;\n         else return root;\n     }\n     return null;\n }"}]},{"id":138,"title":"Kth Smallest in BST","module":"Binary Search Trees","approaches":[{"label":"Better","explanation":"Inorder traversal stops after k nodes. Iterative stack mimics recursion.","complexity":"O(h + k) time, O(h) stack.","code":"int kthSmallestIterative(TreeNode root, int k) {\n     Deque<TreeNode> st = new ArrayDeque<>();\n     TreeNode cur = root;\n     while (true) {\n         while (cur != null) { st.push(cur); cur = cur.left; }\n         cur = st.pop();\n         if (--k == 0) return cur.val;\n         cur = cur.right;\n     }\n }"},{"label":"Optimal","explanation":"Augment  each  node  with  the  size  of  its  left  subtree.  If  leftSize  +  1  equals  k,  current  node  is  the  answer.  If  k  is smaller, go left with the same k. Otherwise go right with k reduced by leftSize + 1.","complexity":"O(h) time per query after O(n) augmentation, O(h) space.","code":"int kthSmallest(TreeNode root, int k) {\n     while (root != null) {\n         int left = size(root.left);\n         if (k == left + 1) return root.val;\n         if (k <= left) root = root.left;\n         else { k -= left + 1; root = root.right; }\n     }\n     return -1;\n }\n int size(TreeNode node) {\n     if (node == null) return 0;\n     return 1 + size(node.left) + size(node.right);\n }"}]},{"id":139,"title":"Merge Two BSTs","module":"Binary Search Trees","approaches":[{"label":"Brute force","explanation":"Inorder both trees into lists, merge the sorted lists, rebuild a balanced BST from the merged array.","complexity":"O(m + n) time, O(m + n) space.","code":"TreeNode mergeBSTsBrute(TreeNode root1, TreeNode root2) {\n     List<Integer> a = new ArrayList<>(), b = new ArrayList<>();\n     inorder(root1, a);\n     inorder(root2, b);\n     List<Integer> all = merge(a, b);\n     return build(all, 0, all.size() - 1);\n }\n void inorder(TreeNode node, List<Integer> out) {\n     if (node == null) return;\n     inorder(node.left, out);\n     out.add(node.val);\n     inorder(node.right, out);\n }\n List<Integer> merge(List<Integer> a, List<Integer> b) {\n     List<Integer> res = new ArrayList<>();\n     int i = 0, j = 0;\n     while (i < a.size() && j < b.size())\n         res.add(a.get(i) <= b.get(j) ? a.get(i++) : b.get(j++));\n     while (i < a.size()) res.add(a.get(i++));\n     while (j < b.size()) res.add(b.get(j++));\n     return res;\n }\n TreeNode build(List<Integer> v, int lo, int hi) {\n     if (lo > hi) return null;\n     int mid = (lo + hi) >>> 1;\n     TreeNode node = new TreeNode(v.get(mid));\n     node.left = build(v, lo, mid - 1);\n     node.right = build(v, mid + 1, hi);\n     return node;\n }"},{"label":"Optimal","explanation":"Inorder both with two stacks (iterative). Always take the smaller stack top value, advance that tree's inorder step, append to a list or link nodes in place. One linear merge pass.","complexity":"O(m + n) time, O(h1 + h2) stack.","code":"List<Integer> mergeBSTInorder(TreeNode root1, TreeNode root2) {\n     List<Integer> ans = new ArrayList<>();\n     Deque<TreeNode> s1 = new ArrayDeque<>(), s2 = new ArrayDeque<>();\n     pushLeft(root1, s1);\n     pushLeft(root2, s2);\n     while (!s1.isEmpty() || !s2.isEmpty()) {\n         if (s2.isEmpty() || (!s1.isEmpty() && s1.peek().val <= s2.peek().val)) {\n             TreeNode node = s1.pop();\n             ans.add(node.val);\n             pushLeft(node.right, s1);\n         } else {\n             TreeNode node = s2.pop();\n             ans.add(node.val);\n             pushLeft(node.right, s2);\n         }\n     }\n     return ans;\n }\n void pushLeft(TreeNode node, Deque<TreeNode> st) {\n     while (node != null) { st.push(node); node = node.left; }\n }"}]},{"id":140,"title":"Two Sum in BST","module":"Binary Search Trees","approaches":[{"label":"Brute force","explanation":"Inorder to a sorted list, two pointers from both ends like two-sum in a sorted array.","complexity":"O(n) time, O(n) space.","code":"boolean findTargetBrute(TreeNode root, int k) {\n     List<Integer> vals = new ArrayList<>();\n     inorder(root, vals);\n     int lo = 0, hi = vals.size() - 1;\n     while (lo < hi) {\n         int sum = vals.get(lo) + vals.get(hi);\n         if (sum == k) return true;\n         if (sum < k) lo++;\n         else hi--;\n     }\n     return false;\n }\n void inorder(TreeNode node, List<Integer> vals) {\n     if (node == null) return;\n     inorder(node.left, vals);\n     vals.add(node.val);\n     inorder(node.right, vals);\n }"},{"label":"Optimal","explanation":"Hash set while DFS: if k - node.val is already seen, pair exists. Otherwise insert node.val and continue.","complexity":"O(n) time, O(n) space.","code":"boolean findTarget(TreeNode root, int k) {\n     Set<Integer> seen = new HashSet<>();\n     return dfsTwoSum(root, k, seen);\n }\n boolean dfsTwoSum(TreeNode node, int k, Set<Integer> seen) {\n     if (node == null) return false;\n     if (seen.contains(k - node.val)) return true;\n     seen.add(node.val);\n     return dfsTwoSum(node.left, k, seen) || dfsTwoSum(node.right, k, seen);\n }"}]},{"id":141,"title":"Recover BST","module":"Binary Search Trees","approaches":[{"label":"Brute force","explanation":"Inorder  to  a  list,  find  the  two  indices  where  order  breaks,  swap  those  values  in  the  list,  write  back  with  another inorder walk. Needs parent pointers or rebuilding.","complexity":"O(n) time, O(n) space.","code":"void recoverTreeBrute(TreeNode root) {\n     List<TreeNode> nodes = new ArrayList<>();\n     List<Integer> vals = new ArrayList<>();\n     inorderCollect(root, nodes, vals);\n     int i = 0, j = vals.size() - 1;\n     while (vals.get(i) < vals.get(i + 1)) i++;\n     while (vals.get(j) > vals.get(j - 1)) j--;\n     int tmp = vals.get(i);\n     vals.set(i, vals.get(j));\n     vals.set(j, tmp);\n     assignInorder(root, vals, new int[]{0});\n }\n void inorderCollect(TreeNode node, List<TreeNode> nodes, List<Integer> vals) {\n     if (node == null) return;\n     inorderCollect(node.left, nodes, vals);\n     nodes.add(node);\n     vals.add(node.val);\n     inorderCollect(node.right, nodes, vals);\n }\n void assignInorder(TreeNode node, List<Integer> vals, int[] p) {\n     if (node == null) return;\n     assignInorder(node.left, vals, p);\n     node.val = vals.get(p[0]++);\n     assignInorder(node.right, vals, p);\n }"},{"label":"Optimal","explanation":"Inorder with three pointers: first and second swapped nodes, plus previous. Whenever current value is less than previous, the previous is a swap candidate. First time set first to previous; second time set second to current. Swap their values.","complexity":"O(n) time, O(h) stack.","code":"void recoverTree(TreeNode root) {\n     TreeNode[] first = new TreeNode[1], second = new TreeNode[1], prev = new TreeNode[0];\n     inorderFix(root, prev, first, second);\n     int tmp = first[0].val;\n     first[0].val = second[0].val;\n     second[0].val = tmp;\n }\n void inorderFix(TreeNode node, TreeNode[] prev, TreeNode[] first, TreeNode[] second) {\n     if (node == null) return;\n     inorderFix(node.left, prev, first, second);\n     if (prev[0] != null && node.val < prev[0].val) {\n         if (first[0] == null) first[0] = prev[0];\n         second[0] = node;\n     }\n     prev[0] = node;\n     inorderFix(node.right, prev, first, second);\n }"}]},{"id":142,"title":"Graph BFS Traversal","module":"Graphs","approaches":[{"label":"Optimal","explanation":"Queue  holds  the  frontier.  Dequeue  a  node,  append  to  order,  enqueue  unvisited  neighbors.  Mark  visited  when enqueued so nothing enters twice.","complexity":"O(V + E) time, O(V) space.","code":"List<Integer> bfs(int n, List<List<Integer>> adj, int start) {\n     boolean[] vis = new boolean[n];\n     List<Integer> order = new ArrayList<>();\n     Queue<Integer> q = new ArrayDeque<>();\n     q.offer(start);\n     vis[start] = true;\n     while (!q.isEmpty()) {\n         int u = q.poll();\n         order.add(u);\n         for (int v : adj.get(u))\n             if (!vis[v]) { vis[v] = true; q.offer(v); }\n     }\n     return order;\n }"}]},{"id":143,"title":"Graph DFS Traversal","module":"Graphs","approaches":[{"label":"Optimal","explanation":"Recursive DFS marks a node, records it, then visits each unvisited neighbor. Iterative version pushes neighbors on a stack in reverse order for the same order.","complexity":"O(V + E) time, O(V) space.","code":"List<Integer> dfs(int n, List<List<Integer>> adj, int start) {\n     boolean[] vis = new boolean[n];\n     List<Integer> order = new ArrayList<>();\n     dfsVisit(start, adj, vis, order);\n     return order;\n }\n void dfsVisit(int u, List<List<Integer>> adj, boolean[] vis, List<Integer> order) {\n     vis[u] = true;\n     order.add(u);\n     for (int v : adj.get(u))\n         if (!vis[v]) dfsVisit(v, adj, vis, order);\n }"}]},{"id":144,"title":"Number of Islands","module":"Graphs","approaches":[{"label":"Brute force","explanation":"For every land cell not yet counted, flood-fill the whole component and increment the count. Each cell is visited once across all floods.","complexity":"O(m * n) time, O(m * n) stack in worst case.","code":"int numIslands(char[][] grid) {\n     int rows = grid.length, cols = grid[0].length, count = 0;\n     for (int r = 0; r < rows; r++)\n         for (int c = 0; c < cols; c++)\n             if (grid[r][c] == '1') {\n                 count++;\n                 sink(grid, r, c);\n             }\n     return count;\n }\n void sink(char[][] grid, int r, int c) {\n     int rows = grid.length, cols = grid[0].length;\n     if (r < 0 || c < 0 || r >= rows || c >= cols || grid[r][c] == '0') return;\n     grid[r][c] = '0';\n     sink(grid, r + 1, c);\n     sink(grid, r - 1, c);\n     sink(grid, r, c + 1);\n     sink(grid, r, c - 1);\n }"},{"label":"Optimal","explanation":"Same flood fill but iterative BFS avoids deep recursion on large grids. Mark visited by flipping '1' to '0'.","complexity":"O(m * n) time, O(min(m, n)) queue.","code":"int numIslandsBfs(char[][] grid) {\n     int rows = grid.length, cols = grid[0].length, count = 0;\n     int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};\n     for (int r = 0; r < rows; r++)\n         for (int c = 0; c < cols; c++)\n             if (grid[r][c] == '1') {\n                 count++;\n                 Queue<int[]> q = new ArrayDeque<>();\n                 q.offer(new int[]{r, c});\n                 grid[r][c] = '0';\n                 while (!q.isEmpty()) {\n                     int[] cell = q.poll();\n                     for (int k = 0; k < 4; k++) {\n                         int nr = cell[0] + dr[k], nc = cell[1] + dc[k];\n                         if (nr >= 0 && nc >= 0 && nr < rows && nc < cols && grid[nr][nc] == '1') {\n                             grid[nr][nc] = '0';\n                             q.offer(new int[]{nr, nc});\n                         }\n                     }\n                 }\n             }\n     return count;\n }"}]},{"id":145,"title":"Flood Fill","module":"Graphs","approaches":[{"label":"Optimal","explanation":"DFS or BFS from (sr, sc) while the cell still matches the original color. Paint to newColor before expanding so the same cell is not reprocessed.","complexity":"O(m * n) time, O(m * n) stack or queue.","code":"int[][] floodFill(int[][] image, int sr, int sc, int newColor) {\n     int old = image[sr][sc];\n     if (old == newColor) return image;\n     dfsFill(image, sr, sc, old, newColor);\n     return image;\n }\n void dfsFill(int[][] img, int r, int c, int old, int neu) {\n     int rows = img.length, cols = img[0].length;\n     if (r < 0 || c < 0 || r >= rows || c >= cols || img[r][c] != old) return;\n     img[r][c] = neu;\n     dfsFill(img, r + 1, c, old, neu);\n     dfsFill(img, r - 1, c, old, neu);\n     dfsFill(img, r, c + 1, old, neu);\n     dfsFill(img, r, c - 1, old, neu);\n }"}]},{"id":146,"title":"Rotten Oranges","module":"Graphs","approaches":[{"label":"Optimal","explanation":"Multi-source BFS: enqueue all rotten oranges at time 0. Each wave infects fresh neighbors. Track minutes as BFS depth. If any fresh remains, return -1.","complexity":"O(m * n) time, O(m * n) queue.","code":"int orangesRotting(int[][] grid) {\n     int rows = grid.length, cols = grid[0].length;\n     Queue<int[]> q = new ArrayDeque<>();\n     int fresh = 0;\n     for (int r = 0; r < rows; r++)\n         for (int c = 0; c < cols; c++) {\n             if (grid[r][c] == 2) q.offer(new int[]{r, c, 0});\n             else if (grid[r][c] == 1) fresh++;\n         }\n     int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};\n     int ans = 0;\n     while (!q.isEmpty()) {\n         int[] cell = q.poll();\n         ans = cell[2];\n         for (int k = 0; k < 4; k++) {\n             int nr = cell[0] + dr[k], nc = cell[1] + dc[k];\n             if (nr >= 0 && nc >= 0 && nr < rows && nc < cols && grid[nr][nc] == 1) {\n                 grid[nr][nc] = 2;\n                 fresh--;\n                 q.offer(new int[]{nr, nc, cell[2] + 1});\n             }\n         }\n     }\n     return fresh == 0 ? ans : -1;\n }"}]},{"id":147,"title":"Cycle in Undirected Graph (DFS)","module":"Graphs","approaches":[{"label":"Optimal","explanation":"DFS with a parent pointer. An back edge to an already visited neighbor that is not the parent means a cycle.","complexity":"O(V + E) time, O(V) space.","code":"boolean hasCycleUndirected(int n, List<List<Integer>> adj) {\n     boolean[] vis = new boolean[n];\n     for (int i = 0; i < n; i++)\n         if (!vis[i] && dfsCycle(i, -1, adj, vis)) return true;\n     return false;\n }\n boolean dfsCycle(int u, int par, List<List<Integer>> adj, boolean[] vis) {\n     vis[u] = true;\n     for (int v : adj.get(u)) {\n         if (!vis[v]) {\n             if (dfsCycle(v, u, adj, vis)) return true;\n         } else if (v != par) return true;\n     }\n     return false;\n }"}]},{"id":148,"title":"Cycle in Undirected Graph (DSU)","module":"Graphs","approaches":[{"label":"Optimal","explanation":"Process edges: if find(u) == find(v) the edge closes a cycle. Otherwise union(u, v). Works for disconnected graphs too.","complexity":"O(E * alpha(V)) time, O(V) space.","code":"boolean hasCycleDSU(int n, int[][] edges) {\n     int[] parent = new int[n], rank = new int[n];\n     for (int i = 0; i < n; i++) parent[i] = i;\n     for (int[] e : edges) {\n         int a = find(e[0], parent), b = find(e[1], parent);\n         if (a == b) return true;\n         union(a, b, parent, rank);\n     }\n     return false;\n }\n int find(int x, int[] parent) {\n     if (parent[x] != x) parent[x] = find(parent[x], parent);\n     return parent[x];\n }\n void union(int a, int b, int[] parent, int[] rank) {\n     if (rank[a] < rank[b]) { int t = a; a = b; b = t; }\n     parent[b] = a;\n     if (rank[a] == rank[b]) rank[a]++;\n }"}]},{"id":149,"title":"Cycle in Directed Graph","module":"Graphs","approaches":[{"label":"Optimal","explanation":"Three colors: unvisited, in current recursion stack, finished. If DFS reaches an in-stack neighbor, there is a back edge and a cycle.","complexity":"O(V + E) time, O(V) space.","code":"boolean hasCycleDirected(int n, List<List<Integer>> adj) {\n     int[] state = new int[n];\n     for (int i = 0; i < n; i++)\n         if (state[i] == 0 && dfsDir(i, adj, state)) return true;\n     return false;\n }\n boolean dfsDir(int u, List<List<Integer>> adj, int[] state) {\n     state[u] = 1;\n     for (int v : adj.get(u)) {\n         if (state[v] == 1) return true;\n         if (state[v] == 0 && dfsDir(v, adj, state)) return true;\n     }\n     state[u] = 2;\n     return false;\n }"}]},{"id":150,"title":"Bipartite Graph Check","module":"Graphs","approaches":[{"label":"Optimal","explanation":"BFS colors the start 0. Each neighbor must be the opposite color. Any same-color edge across the frontier means not bipartite. Disconnected components each get their own BFS.","complexity":"O(V + E) time, O(V) space.","code":"boolean isBipartite(int n, List<List<Integer>> adj) {\n     int[] color = new int[n];\n     Arrays.fill(color, -1);\n     for (int i = 0; i < n; i++) {\n         if (color[i] != -1) continue;\n         Queue<Integer> q = new ArrayDeque<>();\n         q.offer(i);\n         color[i] = 0;\n         while (!q.isEmpty()) {\n             int u = q.poll();\n             for (int v : adj.get(u)) {\n                 if (color[v] == -1) {\n                     color[v] = color[u] ^ 1;\n                     q.offer(v);\n                 } else if (color[v] == color[u]) return false;\n             }\n         }\n     }\n     return true;\n }"},{"label":"Better","explanation":"DFS with the same coloring rule: try to paint neighbors opposite to the current node.","complexity":"O(V + E) time, O(V) space.","code":"boolean isBipartiteDfs(int n, List<List<Integer>> adj) {\n     int[] color = new int[n];\n     Arrays.fill(color, -1);\n     for (int i = 0; i < n; i++)\n         if (color[i] == -1 && !paint(i, 0, adj, color)) return false;\n     return true;\n }\n boolean paint(int u, int c, List<List<Integer>> adj, int[] color) {\n     color[u] = c;\n     for (int v : adj.get(u)) {\n         if (color[v] == -1) {\n             if (!paint(v, c ^ 1, adj, color)) return false;\n         } else if (color[v] == c) return false;\n     }\n     return true;\n }"}]},{"id":151,"title":"Number of Provinces","module":"Graphs","approaches":[{"label":"Brute force","explanation":"Floyd-Warshall to get transitive closure, then count rows that still connect. Heavy for this problem size.","complexity":"O(n^3) time, O(n^2) space.","code":"int findCircleNumFloyd(int[][] isConnected) {\n     int n = isConnected.length;\n     boolean[][] reach = new boolean[n][n];\n     for (int i = 0; i < n; i++) reach[i][i] = true;\n     for (int i = 0; i < n; i++)\n         for (int j = 0; j < n; j++)\n             if (isConnected[i][j] == 1) reach[i][j] = true;\n     for (int k = 0; k < n; k++)\n         for (int i = 0; i < n; i++)\n             for (int j = 0; j < n; j++)\n                 reach[i][j] = reach[i][j] || (reach[i][k] && reach[k][j]);\n     boolean[] vis = new boolean[n];\n     int comps = 0;\n     for (int i = 0; i < n; i++)\n         if (!vis[i]) {\n             comps++;\n             for (int j = 0; j < n; j++)\n                 if (reach[i][j]) vis[j] = true;\n         }\n     return comps;\n }"},{"label":"Optimal","explanation":"Treat the matrix as adjacency. DFS or DSU from each unvisited city counts one province per component.","complexity":"O(n^2) time, O(n) space.","code":"int findCircleNum(int[][] isConnected) {\n     int n = isConnected.length;\n     boolean[] vis = new boolean[n];\n     int comps = 0;\n     for (int i = 0; i < n; i++)\n         if (!vis[i]) {\n             dfsProv(i, isConnected, vis);\n             comps++;\n         }\n     return comps;\n }\n void dfsProv(int u, int[][] mat, boolean[] vis) {\n     vis[u] = true;\n     for (int v = 0; v < mat.length; v++)\n         if (mat[u][v] == 1 && !vis[v]) dfsProv(v, mat, vis);\n }"}]},{"id":152,"title":"Topological Sort (DFS)","module":"Graphs","approaches":[{"label":"Optimal","explanation":"DFS finishes deeper nodes first. Push a node onto the order stack after all outgoing edges are explored. Reverse is a valid topo order.","complexity":"O(V + E) time, O(V) space.","code":"List<Integer> topoSortDfs(int n, List<List<Integer>> adj) {\n     boolean[] vis = new boolean[n];\n     Deque<Integer> st = new ArrayDeque<>();\n     for (int i = 0; i < n; i++)\n         if (!vis[i]) dfsTopo(i, adj, vis, st);\n     List<Integer> order = new ArrayList<>();\n     while (!st.isEmpty()) order.add(st.pop());\n     return order;\n }\n void dfsTopo(int u, List<List<Integer>> adj, boolean[] vis, Deque<Integer> st) {\n     vis[u] = true;\n     for (int v : adj.get(u))\n         if (!vis[v]) dfsTopo(v, adj, vis, st);\n     st.push(u);\n }"}]},{"id":153,"title":"Topological Sort (Kahn BFS)","module":"Graphs","approaches":[{"label":"Optimal","explanation":"Compute  indegrees.  Enqueue  all  zero-indegree  nodes.  Dequeue,  append,  relax  neighbors  by  decrementing indegree; enqueue when it hits zero. If fewer than V nodes appear, a cycle exists.","complexity":"O(V + E) time, O(V) space.","code":"List<Integer> topoSortKahn(int n, List<List<Integer>> adj) {\n     int[] indeg = new int[n];\n     for (int u = 0; u < n; u++)\n         for (int v : adj.get(u)) indeg[v]++;\n     Queue<Integer> q = new ArrayDeque<>();\n     for (int i = 0; i < n; i++)\n         if (indeg[i] == 0) q.offer(i);\n     List<Integer> order = new ArrayList<>();\n     while (!q.isEmpty()) {\n         int u = q.poll();\n         order.add(u);\n         for (int v : adj.get(u))\n             if (--indeg[v] == 0) q.offer(v);\n     }\n     return order.size() == n ? order : new ArrayList<>();\n }"}]},{"id":154,"title":"Course Schedule I","module":"Graphs","approaches":[{"label":"Optimal","explanation":"Can finish iff the prerequisite graph has no cycle. Kahn's algorithm: if topo order length equals numCourses, true; else false.","complexity":"O(V + E) time, O(V) space.","code":"boolean canFinish(int numCourses, int[][] prerequisites) {\n     List<List<Integer>> adj = new ArrayList<>();\n     for (int i = 0; i < numCourses; i++) adj.add(new ArrayList<>());\n     int[] indeg = new int[numCourses];\n     for (int[] p : prerequisites) {\n         adj.get(p[1]).add(p[0]);\n         indeg[p[0]]++;\n     }\n     Queue<Integer> q = new ArrayDeque<>();\n     for (int i = 0; i < numCourses; i++)\n         if (indeg[i] == 0) q.offer(i);\n     int seen = 0;\n     while (!q.isEmpty()) {\n         int u = q.poll();\n         seen++;\n         for (int v : adj.get(u))\n             if (--indeg[v] == 0) q.offer(v);\n     }\n     return seen == numCourses;\n }"}]},{"id":155,"title":"Course Schedule II","module":"Graphs","approaches":[{"label":"Optimal","explanation":"Same Kahn topo as Course I but return the order list. Empty list when a cycle blocks some indegrees from reaching zero.","complexity":"O(V + E) time, O(V) space.","code":"int[] findOrder(int numCourses, int[][] prerequisites) {\n     List<Integer> order = topoSortKahn(numCourses, buildAdj(numCourses, prerequisites));\n     if (order.size() != numCourses) return new int[0];\n     int[] ans = new int[numCourses];\n     for (int i = 0; i < numCourses; i++) ans[i] = order.get(i);\n     return ans;\n }\n List<List<Integer>> buildAdj(int n, int[][] pre) {\n     List<List<Integer>> adj = new ArrayList<>();\n     for (int i = 0; i < n; i++) adj.add(new ArrayList<>());\n     for (int[] p : pre) adj.get(p[1]).add(p[0]);\n     return adj;\n }\n List<Integer> topoSortKahn(int n, List<List<Integer>> adj) {\n     int[] indeg = new int[n];\n     for (int u = 0; u < n; u++)\n         for (int v : adj.get(u)) indeg[v]++;\n     Queue<Integer> q = new ArrayDeque<>();\n     for (int i = 0; i < n; i++)\n         if (indeg[i] == 0) q.offer(i);\n     List<Integer> order = new ArrayList<>();\n     while (!q.isEmpty()) {\n         int u = q.poll();\n         order.add(u);\n         for (int v : adj.get(u))\n             if (--indeg[v] == 0) q.offer(v);\n     }\n     return order;\n }"}]},{"id":156,"title":"Alien Dictionary","module":"Graphs","approaches":[{"label":"Brute force","explanation":"Compare every adjacent word pair character by character to infer letter order, then topologically sort letters with brute force removal of sources. Fragile on large inputs.","complexity":"O(C + L^2) time where C is total chars.","code":"String alienOrderBrute(String[] words) {\n     Map<Character, Set<Character>> before = new HashMap<>();\n     Set<Character> chars = new HashSet<>();\n     for (String w : words)\n         for (char ch : w.toCharArray()) chars.add(ch);\n     for (int i = 0; i + 1 < words.length; i++) {\n         String a = words[i], b = words[i + 1];\n         if (a.length() > b.length() && a.startsWith(b)) return \"\";\n         for (int j = 0; j < Math.min(a.length(), b.length()); j++)\n             if (a.charAt(j) != b.charAt(j)) {\n                 before.computeIfAbsent(a.charAt(j), k -> new HashSet<>()).add(b.charAt(j));\n                 break;\n             }\n     }\n     StringBuilder sb = new StringBuilder();\n     while (!chars.isEmpty()) {\n         char pick = 0;\n         outer:\n         for (char c : chars) {\n             for (Set<Character> s : before.values())\n                 if (s.contains(c)) continue outer;\n             pick = c;\n             break;\n         }\n         if (pick == 0) return \"\";\n         sb.append(pick);\n         chars.remove(pick);\n         before.values().forEach(s -> s.remove(pick));\n     }\n     return sb.toString();\n }"},{"label":"Optimal","explanation":"Build  edges  from  first  mismatch  of  adjacent  words.  Validate  prefix  rule.  Kahn  on  26  letters  with  indegree  array. Concatenate zero-indegree removals; cycle if length mismatch.","complexity":"O(C + 26) time, O(26) space.","code":"String alienOrder(String[] words) {\n     int[] indeg = new int[26];\n     boolean[] seen = new boolean[26];\n     List<Set<Integer>> adj = new ArrayList<>();\n     for (int i = 0; i < 26; i++) adj.add(new HashSet<>());\n     for (String w : words)\n         for (char ch : w.toCharArray()) seen[ch - 'a'] = true;\n     for (int i = 0; i + 1 < words.length; i++) {\n         String a = words[i], b = words[i + 1];\n         if (a.length() > b.length() && a.startsWith(b)) return \"\";\n         for (int j = 0; j < Math.min(a.length(), b.length()); j++) {\n             int u = a.charAt(j) - 'a', v = b.charAt(j) - 'a';\n             if (u != v) {\n                 if (adj.get(u).add(v)) indeg[v]++;\n                 break;\n             }\n         }\n     }\n     Queue<Integer> q = new ArrayDeque<>();\n     for (int i = 0; i < 26; i++)\n         if (seen[i] && indeg[i] == 0) q.offer(i);\n     StringBuilder sb = new StringBuilder();\n     while (!q.isEmpty()) {\n         int u = q.poll();\n         sb.append((char) ('a' + u));\n         for (int v : adj.get(u))\n             if (--indeg[v] == 0) q.offer(v);\n     }\n     for (int i = 0; i < 26; i++)\n         if (seen[i] && indeg[i] > 0) return \"\";\n     return sb.toString();\n }"}]},{"id":157,"title":"Shortest Path in Unweighted Graph","module":"Graphs","approaches":[{"label":"Brute force","explanation":"DFS  enumerates  all  paths  from  source  to  target  tracking  length.  Minimum  length  wins.  Exponential  on  dense graphs.","complexity":"O(V!) worst case, O(V) stack.","code":"int shortestPathBrute(int n, List<List<Integer>> adj, int src, int dst) {\n     int[] best = new int[]{Integer.MAX_VALUE};\n     dfsPath(src, dst, adj, new boolean[n], 0, best);\n     return best[0] == Integer.MAX_VALUE ? -1 : best[0];\n }\n void dfsPath(int u, int dst, List<List<Integer>> adj, boolean[] vis, int len, int[] best) {\n     if (u == dst) { best[0] = Math.min(best[0], len); return; }\n     vis[u] = true;\n     for (int v : adj.get(u))\n         if (!vis[v]) dfsPath(v, dst, adj, vis, len + 1, best);\n     vis[u] = false;\n }"},{"label":"Optimal","explanation":"BFS from source assigns distance when a node is first dequeued. First time at dst is shortest edge count in an unweighted graph.","complexity":"O(V + E) time, O(V) space.","code":"int shortestPathUnweighted(int n, List<List<Integer>> adj, int src, int dst) {\n     int[] dist = new int[n];\n     Arrays.fill(dist, -1);\n     Queue<Integer> q = new ArrayDeque<>();\n     q.offer(src);\n     dist[src] = 0;\n     while (!q.isEmpty()) {\n         int u = q.poll();\n         if (u == dst) return dist[u];\n         for (int v : adj.get(u))\n             if (dist[v] == -1) {\n                 dist[v] = dist[u] + 1;\n                 q.offer(v);\n             }\n     }\n     return -1;\n }"}]},{"id":158,"title":"Shortest Path in DAG","module":"Graphs","approaches":[{"label":"Optimal","explanation":"Topo  order  guarantees  edges  go  forward.  Relax  each  outgoing  edge  once:  dist[v]  =  min(dist[v],  dist[u]  +  w). Initialize source 0, others INF.","complexity":"O(V + E) time, O(V) space.","code":"int[] shortestPathDAG(int n, int src, List<List<int[]>> adj) {\n     int[] dist = new int[n];\n     Arrays.fill(dist, Integer.MAX_VALUE / 4);\n     dist[src] = 0;\n     List<Integer> order = topoSortKahn(n, toListAdj(adj));\n     for (int u : order)\n         if (dist[u] < Integer.MAX_VALUE / 4)\n             for (int[] e : adj.get(u)) {\n                 int v = e[0], w = e[1];\n                 dist[v] = Math.min(dist[v], dist[u] + w);\n             }\n     return dist;\n }\n List<List<Integer>> toListAdj(List<List<int[]>> adj) {\n     List<List<Integer>> g = new ArrayList<>();\n     for (List<int[]> row : adj) {\n         List<Integer> lst = new ArrayList<>();\n         for (int[] e : row) lst.add(e[0]);\n         g.add(lst);\n     }\n     return g;\n }\n List<Integer> topoSortKahn(int n, List<List<Integer>> adj) {\n     int[] indeg = new int[n];\n     for (int u = 0; u < n; u++)\n         for (int v : adj.get(u)) indeg[v]++;\n     Queue<Integer> q = new ArrayDeque<>();\n     for (int i = 0; i < n; i++)\n         if (indeg[i] == 0) q.offer(i);\n     List<Integer> order = new ArrayList<>();\n     while (!q.isEmpty()) {\n         int u = q.poll();\n         order.add(u);\n         for (int v : adj.get(u))\n             if (--indeg[v] == 0) q.offer(v);\n     }\n     return order;\n }"}]},{"id":159,"title":"Dijkstra Shortest Path","module":"Graphs","approaches":[{"label":"Brute force","explanation":"Relax  all  edges  V  times  like  Bellman-Ford  without  early  exit  optimization  on  nonnegative  weights.  Simple  but slower than heap Dijkstra.","complexity":"O(V * E) time, O(V) space.","code":"int[] dijkstraBrute(int n, int src, List<List<int[]>> adj) {\n     int[] dist = new int[n];\n     Arrays.fill(dist, Integer.MAX_VALUE / 4);\n     dist[src] = 0;\n     for (int iter = 0; iter < n - 1; iter++)\n         for (int u = 0; u < n; u++)\n             if (dist[u] < Integer.MAX_VALUE / 4)\n                 for (int[] e : adj.get(u)) {\n                     int v = e[0], w = e[1];\n                     dist[v] = Math.min(dist[v], dist[u] + w);\n                 }\n     return dist;\n }"},{"label":"Optimal","explanation":"Min-heap stores (distance, node). Pop the smallest tentative distance; stale entries are skipped. Relax neighbors. Nonnegative weights make the first settlement final.","complexity":"O((V + E) log V) time, O(V) space.","code":"int[] dijkstra(int n, int src, List<List<int[]>> adj) {\n     int[] dist = new int[n];\n     Arrays.fill(dist, Integer.MAX_VALUE / 4);\n     dist[src] = 0;\n     PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));\n     pq.offer(new int[]{src, 0});\n     while (!pq.isEmpty()) {\n         int[] cur = pq.poll();\n         int u = cur[0], d = cur[1];\n         if (d != dist[u]) continue;\n         for (int[] e : adj.get(u)) {\n             int v = e[0], w = e[1];\n             if (dist[u] + w < dist[v]) {\n                 dist[v] = dist[u] + w;\n                 pq.offer(new int[]{v, dist[v]});\n             }\n         }\n     }\n     return dist;\n }"}]},{"id":160,"title":"Bellman-Ford","module":"Graphs","approaches":[{"label":"Optimal","explanation":"Relax  every  edge  V-1  times.  One  more  pass  detects  a  reachable  improvement,  which  means  a  negative  cycle. Handles negative weights unlike Dijkstra.","complexity":"O(V * E) time, O(V) space.","code":"int[] bellmanFord(int n, int src, int[][] edges) {\n     int[] dist = new int[n];\n     Arrays.fill(dist, Integer.MAX_VALUE / 4);\n     dist[src] = 0;\n     for (int i = 0; i < n - 1; i++)\n         for (int[] e : edges) {\n             int u = e[0], v = e[1], w = e[2];\n             if (dist[u] < Integer.MAX_VALUE / 4)\n                 dist[v] = Math.min(dist[v], dist[u] + w);\n         }\n     for (int[] e : edges) {\n         int u = e[0], v = e[1], w = e[2];\n         if (dist[u] < Integer.MAX_VALUE / 4 && dist[u] + w < dist[v])\n             return new int[0];\n     }\n     return dist;\n }"}]},{"id":161,"title":"Floyd-Warshall","module":"Graphs","approaches":[{"label":"Brute force","explanation":"Run Dijkstra from every vertex. Correct on nonnegative weights but repeats heap work V times.","complexity":"O(V * (V + E) log V) time.","code":"int[][] allPairsDijkstra(int n, List<List<int[]>> adj) {\n     int[][] ans = new int[n][n];\n     for (int i = 0; i < n; i++) {\n         int[] row = dijkstra(n, i, adj);\n         ans[i] = row;\n     }\n     return ans;\n }\n int[] dijkstra(int n, int src, List<List<int[]>> adj) {\n     int[] dist = new int[n];\n     Arrays.fill(dist, Integer.MAX_VALUE / 4);\n     dist[src] = 0;\n     PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));\n     pq.offer(new int[]{src, 0});\n     while (!pq.isEmpty()) {\n         int[] cur = pq.poll();\n         int u = cur[0], d = cur[1];\n         if (d != dist[u]) continue;\n         for (int[] e : adj.get(u)) {\n             int v = e[0], w = e[1];\n             if (dist[u] + w < dist[v]) {\n                 dist[v] = dist[u] + w;\n                 pq.offer(new int[]{v, dist[v]});\n             }\n         }\n     }\n     return dist;\n }"},{"label":"Optimal","explanation":"Dynamic  programming  on  intermediate  nodes:  dist[i][j]  =  min(dist[i][j],  dist[i][k]  +  dist[k][j])  for  each  k.  Works  with negative edges if no negative cycles.","complexity":"O(V^3) time, O(V^2) space.","code":"int[][] floydWarshall(int n, int[][] w) {\n     int[][] dist = new int[n][n];\n     for (int i = 0; i < n; i++)\n         dist[i] = Arrays.copyOf(w[i], n);\n     for (int k = 0; k < n; k++)\n         for (int i = 0; i < n; i++)\n             for (int j = 0; j < n; j++)\n                 if (dist[i][k] < Integer.MAX_VALUE / 4 && dist[k][j] < Integer.MAX_VALUE / 4)\n                     dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);\n     return dist;\n }"}]},{"id":162,"title":"Minimum Spanning Tree (Prim)","module":"Graphs","approaches":[{"label":"Optimal","explanation":"Grow a tree from start node 0. Min-heap holds cross edges (weight, to). Pop cheapest edge to an unvisited vertex, add its outgoing edges. Stop after V-1 edges or when heap empties.","complexity":"O((V + E) log V) time, O(V + E) space.","code":"int mstCostPrim(int n, List<List<int[]>> adj) {\n     boolean[] inTree = new boolean[n];\n     PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));\n     pq.offer(new int[]{0, 0});\n     int total = 0, used = 0;\n     while (!pq.isEmpty() && used < n) {\n         int[] cur = pq.poll();\n         int u = cur[0], w = cur[1];\n         if (inTree[u]) continue;\n         inTree[u] = true;\n         total += w;\n         used++;\n         for (int[] e : adj.get(u))\n             if (!inTree[e[0]]) pq.offer(new int[]{e[0], e[1]});\n     }\n     return total;\n }"}]},{"id":163,"title":"Minimum Spanning Tree (Kruskal)","module":"Graphs","approaches":[{"label":"Optimal","explanation":"Sort  edges  by  weight.  Add  an  edge  if  its  endpoints  are  in  different  DSU  components.  V-1  edges  form  the  MST when the graph is connected.","complexity":"O(E log E) time, O(V) DSU space.","code":"int mstCostKruskal(int n, int[][] edges) {\n     Arrays.sort(edges, Comparator.comparingInt(a -> a[2]));\n     int[] parent = new int[n], rank = new int[n];\n     for (int i = 0; i < n; i++) parent[i] = i;\n     int total = 0, cnt = 0;\n     for (int[] e : edges) {\n         int a = find(e[0], parent), b = find(e[1], parent);\n         if (a == b) continue;\n         union(a, b, parent, rank);\n         total += e[2];\n         if (++cnt == n - 1) break;\n     }\n     return total;\n }\n int find(int x, int[] parent) {\n     if (parent[x] != x) parent[x] = find(parent[x], parent);\n     return parent[x];\n }\n void union(int a, int b, int[] parent, int[] rank) {\n     if (rank[a] < rank[b]) { int t = a; a = b; b = t; }\n     parent[b] = a;\n     if (rank[a] == rank[b]) rank[a]++;\n }"}]},{"id":164,"title":"Accounts Merge","module":"Graphs","approaches":[{"label":"Brute force","explanation":"Union names that share an email by comparing every pair of accounts. Quadratic in account count.","complexity":"O(A^2 * E) time, O(A * E) space.","code":"List<List<String>> accountsMergeBrute(List<List<String>> accounts) {\n     int n = accounts.size();\n     int[] parent = new int[n];\n     for (int i = 0; i < n; i++) parent[i] = i;\n     for (int i = 0; i < n; i++)\n         for (int j = i + 1; j < n; j++)\n             if (shareEmail(accounts.get(i), accounts.get(j)))\n                 union(i, j, parent);\n     Map<Integer, List<String>> groups = new HashMap<>();\n     for (int i = 0; i < n; i++) {\n         int r = find(i, parent);\n         groups.computeIfAbsent(r, k -> new ArrayList<>()).addAll(accounts.get(i).subList(1, accounts.get(i).size()));\n     }\n     List<List<String>> ans = new ArrayList<>();\n     for (var e : groups.entrySet()) {\n         TreeSet<String> emails = new TreeSet<>(e.getValue());\n         List<String> row = new ArrayList<>();\n         row.add(accounts.get(e.getKey()).get(0));\n         row.addAll(emails);\n         ans.add(row);\n     }\n     return ans;\n }\n boolean shareEmail(List<String> a, List<String> b) {\n     Set<String> s = new HashSet<>(a.subList(1, a.size()));\n     for (int i = 1; i < b.size(); i++)\n         if (s.contains(b.get(i))) return true;\n     return false;\n }\n int find(int x, int[] parent) {\n     return parent[x] == x ? x : (parent[x] = find(parent[x], parent));\n }\n void union(int a, int b, int[] parent) {\n     parent[find(b, parent)] = find(a, parent);\n }"},{"label":"Optimal","explanation":"DSU  on  emails:  map  each  email  to  an  index,  union  first  email  of  each  account  with  every  other  email  in  that account. Then bucket emails by root and sort.","complexity":"O(N * K log K) where N accounts and K emails per account, near O(E alpha(N)).","code":"List<List<String>> accountsMerge(List<List<String>> accounts) {\n     Map<String, String> owner = new HashMap<>();\n     Map<String, String> parent = new HashMap<>();\n     for (List<String> acc : accounts) {\n         String name = acc.get(0);\n         for (int i = 1; i < acc.size(); i++) {\n             owner.putIfAbsent(acc.get(i), name);\n             parent.putIfAbsent(acc.get(i), acc.get(i));\n         }\n         for (int i = 2; i < acc.size(); i++) unionEmail(acc.get(1), acc.get(i), parent);\n     }\n     Map<String, TreeSet<String>> groups = new HashMap<>();\n     for (String email : parent.keySet()) {\n         String root = findEmail(email, parent);\n         groups.computeIfAbsent(root, k -> new TreeSet<>()).add(email);\n     }\n     List<List<String>> ans = new ArrayList<>();\n     for (var e : groups.entrySet()) {\n         List<String> row = new ArrayList<>();\n         row.add(owner.get(e.getKey()));\n         row.addAll(e.getValue());\n         ans.add(row);\n     }\n     return ans;\n }\n String findEmail(String x, Map<String, String> parent) {\n     if (!parent.get(x).equals(x)) parent.put(x, findEmail(parent.get(x), parent));\n     return parent.get(x);\n }\n void unionEmail(String a, String b, Map<String, String> parent) {\n     parent.put(findEmail(b, parent), findEmail(a, parent));\n }"}]},{"id":165,"title":"Kosaraju Strongly Connected Components","module":"Graphs","approaches":[{"label":"Optimal","explanation":"First DFS on the graph fills finish order. Reverse all edges. DFS again in reverse finish order; each DFS tree in pass two is one SCC.","complexity":"O(V + E) time, O(V + E) space.","code":"List<List<Integer>> kosaraju(int n, List<List<Integer>> adj) {\n     boolean[] vis = new boolean[n];\n     Deque<Integer> order = new ArrayDeque<>();\n     for (int i = 0; i < n; i++)\n         if (!vis[i]) dfs1(i, adj, vis, order);\n     List<List<Integer>> rev = reverseGraph(n, adj);\n     Arrays.fill(vis, false);\n     List<List<Integer>> sccs = new ArrayList<>();\n     while (!order.isEmpty()) {\n         int u = order.pop();\n         if (vis[u]) continue;\n         List<Integer> comp = new ArrayList<>();\n         dfs2(u, rev, vis, comp);\n         sccs.add(comp);\n     }\n     return sccs;\n }\n void dfs1(int u, List<List<Integer>> adj, boolean[] vis, Deque<Integer> order) {\n     vis[u] = true;\n     for (int v : adj.get(u))\n         if (!vis[v]) dfs1(v, adj, vis, order);\n     order.push(u);\n }\n void dfs2(int u, List<List<Integer>> rev, boolean[] vis, List<Integer> comp) {\n     vis[u] = true;\n     comp.add(u);\n     for (int v : rev.get(u))\n         if (!vis[v]) dfs2(v, rev, vis, comp);\n }\n List<List<Integer>> reverseGraph(int n, List<List<Integer>> adj) {\n     List<List<Integer>> rev = new ArrayList<>();\n     for (int i = 0; i < n; i++) rev.add(new ArrayList<>());\n     for (int u = 0; u < n; u++)\n         for (int v : adj.get(u)) rev.get(v).add(u);\n     return rev;\n }"}]},{"id":166,"title":"Bridges in Graph","module":"Graphs","approaches":[{"label":"Optimal","explanation":"Tarjan DFS tracks discovery time and low-link. Tree edge to v updates low from subtree. Back edge updates low from discovery time of v. If low[v] > disc[u], edge u-v is a bridge.","complexity":"O(V + E) time, O(V) space.","code":"List<int[]> findBridges(int n, List<List<Integer>> adj) {\n     int[] disc = new int[n], low = new int[n];\n     Arrays.fill(disc, -1);\n     int[] timer = new int[]{0};\n     List<int[]> bridges = new ArrayList<>();\n     for (int i = 0; i < n; i++)\n         if (disc[i] == -1) dfsBridge(i, -1, adj, disc, low, timer, bridges);\n     return bridges;\n }\n void dfsBridge(int u, int par, List<List<Integer>> adj, int[] disc, int[] low, int[] timer, List<int[]> bridges) {\n     disc[u] = low[u] = timer[0]++;\n     for (int v : adj.get(u)) {\n         if (v == par) continue;\n         if (disc[v] == -1) {\n             dfsBridge(v, u, adj, disc, low, timer, bridges);\n             low[u] = Math.min(low[u], low[v]);\n             if (low[v] > disc[u]) bridges.add(new int[]{u, v});\n         } else low[u] = Math.min(low[u], disc[v]);\n     }\n }"}]},{"id":167,"title":"Articulation Points","module":"Graphs","approaches":[{"label":"Optimal","explanation":"Same Tarjan low/disc. Root with two or more DFS children is articulation. Non-root u is articulation if some child v has low[v] >= disc[u].","complexity":"O(V + E) time, O(V) space.","code":"List<Integer> articulationPoints(int n, List<List<Integer>> adj) {\n     int[] disc = new int[n], low = new int[n];\n     Arrays.fill(disc, -1);\n     boolean[] isAp = new boolean[n];\n     int[] timer = new int[]{0};\n     for (int i = 0; i < n; i++)\n         if (disc[i] == -1) dfsAp(i, -1, adj, disc, low, timer, isAp, new int[]{0});\n     List<Integer> ans = new ArrayList<>();\n     for (int i = 0; i < n; i++)\n         if (isAp[i]) ans.add(i);\n     return ans;\n }\n void dfsAp(int u, int par, List<List<Integer>> adj, int[] disc, int[] low, int[] timer, boolean[] isAp, int[] children) {\n     disc[u] = low[u] = timer[0]++;\n     int childCount = 0;\n     for (int v : adj.get(u)) {\n         if (v == par) continue;\n         if (disc[v] == -1) {\n             childCount++;\n             dfsAp(v, u, adj, disc, low, timer, isAp, children);\n             low[u] = Math.min(low[u], low[v]);\n             if (par != -1 && low[v] >= disc[u]) isAp[u] = true;\n         } else low[u] = Math.min(low[u], disc[v]);\n     }\n     if (par == -1 && childCount > 1) isAp[u] = true;\n }"}]},{"id":168,"title":"Word Ladder","module":"Graphs","approaches":[{"label":"Brute force","explanation":"DFS  from  beginWord  trying  every  single-letter  change  that  exists  in  the  word  set.  Track  minimum  depth  when endWord is reached. Exponential without BFS layering.","complexity":"O(N * L * 26^L) worst case, O(L) stack.","code":"int ladderLengthBrute(String beginWord, String endWord, List<String> wordList) {\n     Set<String> dict = new HashSet<>(wordList);\n     if (!dict.contains(endWord)) return 0;\n     int[] best = new int[]{Integer.MAX_VALUE};\n     dfsLadder(beginWord, endWord, dict, new HashSet<>(), 1, best);\n     return best[0] == Integer.MAX_VALUE ? 0 : best[0];\n }\n void dfsLadder(String cur, String end, Set<String> dict, Set<String> used, int steps, int[] best) {\n     if (cur.equals(end)) { best[0] = Math.min(best[0], steps); return; }\n     if (steps >= best[0]) return;\n     char[] arr = cur.toCharArray();\n     for (int i = 0; i < arr.length; i++) {\n         char old = arr[i];\n         for (char c = 'a'; c <= 'z'; c++) {\n             arr[i] = c;\n             String nxt = new String(arr);\n             if (dict.contains(nxt) && !used.contains(nxt)) {\n                 used.add(nxt);\n                 dfsLadder(nxt, end, dict, used, steps + 1, best);\n                 used.remove(nxt);\n             }\n         }\n         arr[i] = old;\n     }\n }"},{"label":"Optimal","explanation":"BFS on words: each level is one letter change. For each word try all 26 letters at each position. First time endWord is dequeued, return level count.","complexity":"O(N * L * 26) time, O(N) space.","code":"int ladderLength(String beginWord, String endWord, List<String> wordList) {\n     Set<String> dict = new HashSet<>(wordList);\n     if (!dict.contains(endWord)) return 0;\n     Queue<String> q = new ArrayDeque<>();\n     q.offer(beginWord);\n     int steps = 1;\n     while (!q.isEmpty()) {\n         int sz = q.size();\n         for (int t = 0; t < sz; t++) {\n             String word = q.poll();\n             if (word.equals(endWord)) return steps;\n             char[] arr = word.toCharArray();\n             for (int i = 0; i < arr.length; i++) {\n                 char old = arr[i];\n                 for (char c = 'a'; c <= 'z'; c++) {\n                     arr[i] = c;\n                     String nxt = new String(arr);\n                     if (dict.remove(nxt)) q.offer(nxt);\n                 }\n                 arr[i] = old;\n             }\n         }\n         steps++;\n     }\n     return 0;\n }"}]},{"id":169,"title":"Climbing Stairs","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"From step i you may go to i+1 or i+2. The number of ways to reach n is the sum of ways from n-1 and n-2. Recurse without caching and the same (n) is recomputed many times.","complexity":"O(2^n) time, O(n) stack.","code":"int climbStairs(int n) {\n     if (n <= 2) return n;\n     return climbStairs(n - 1) + climbStairs(n - 2);\n }"},{"label":"Memoization","explanation":"The recurrence is Fibonacci: dp[i] = dp[i-1] + dp[i-2]. Cache dp[n] after the first compute.","complexity":"O(n) time, O(n) space.","code":"int climbStairs(int n) {\n     int[] memo = new int[n + 1];\n     Arrays.fill(memo, -1);\n     return ways(n, memo);\n }\n int ways(int n, int[] memo) {\n     if (n <= 2) return n;\n     if (memo[n] != -1) return memo[n];\n     return memo[n] = ways(n - 1, memo) + ways(n - 2, memo);\n }"},{"label":"Tabulation","explanation":"Fill bottom-up with two rolling variables instead of an array.","complexity":"O(n) time, O(1) space.","code":"int climbStairs(int n) {\n     if (n <= 2) return n;\n     int a = 1, b = 2;\n     for (int i = 3; i <= n; i++) {\n         int c = a + b;\n         a = b;\n         b = c;\n     }\n     return b;\n }"}]},{"id":170,"title":"Frog Jump (Minimum Cost)","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"From index i jump to i+1 or i+2 and pay |height[i]-height[j]|. Try both jumps recursively from every start.","complexity":"O(2^n) time, O(n) stack.","code":"int minCost(int[] h) {\n     return cost(h, 0);\n }\n int cost(int[] h, int i) {\n     if (i >= h.length - 1) return 0;\n     int one = Math.abs(h[i] - h[i + 1]) + cost(h, i + 1);\n     int two = (i + 2 < h.length)\n         ? Math.abs(h[i] - h[i + 2]) + cost(h, i + 2)\n         : Integer.MAX_VALUE / 2;\n     return Math.min(one, two);\n }"},{"label":"Memoization","explanation":"State is the current index. dp[i] = min cost to reach the end from i.","complexity":"O(n) time, O(n) space.","code":"int minCost(int[] h) {\n     int n = h.length;\n     int[] memo = new int[n];\n     Arrays.fill(memo, -1);\n     return dp(h, 0, memo);\n }\n int dp(int[] h, int i, int[] memo) {\n     if (i >= h.length - 1) return 0;\n     if (memo[i] != -1) return memo[i];\n     int best = Math.abs(h[i] - h[i + 1]) + dp(h, i + 1, memo);\n     if (i + 2 < h.length)\n         best = Math.min(best, Math.abs(h[i] - h[i + 2]) + dp(h, i + 2, memo));\n     return memo[i] = best;\n }"},{"label":"Tabulation","explanation":"dp[i] = min cost from i to end; answer is dp[0]. Fill from n-1 down to 0.","complexity":"O(n) time, O(n) space.","code":"int minCost(int[] h) {\n     int n = h.length;\n     int[] dp = new int[n];\n     dp[n - 1] = 0;\n     for (int i = n - 2; i >= 0; i--) {\n         dp[i] = Math.abs(h[i] - h[i + 1]) + dp[i + 1];\n         if (i + 2 < n)\n             dp[i] = Math.min(dp[i], Math.abs(h[i] - h[i + 2]) + dp[i + 2]);\n     }\n     return dp[0];\n }"}]},{"id":171,"title":"House Robber","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"At each house, rob it (skip the next) or skip it. Explore both branches on the suffix.","complexity":"O(2^n) time, O(n) stack.","code":"int rob(int[] a) {\n     return pick(a, 0);\n }\n int pick(int[] a, int i) {\n     if (i >= a.length) return 0;\n     int take = a[i] + pick(a, i + 2);\n     int skip = pick(a, i + 1);\n     return Math.max(take, skip);\n }"},{"label":"Memoization","explanation":"dp[i] = max money from houses i..end. Either rob i and jump to i+2, or skip i.","complexity":"O(n) time, O(n) space.","code":"int rob(int[] a) {\n     int[] memo = new int[a.length];\n     Arrays.fill(memo, -1);\n     return dp(a, 0, memo);\n }\n int dp(int[] a, int i, int[] memo) {\n     if (i >= a.length) return 0;\n     if (memo[i] != -1) return memo[i];\n     return memo[i] = Math.max(a[i] + dp(a, i + 2, memo), dp(a, i + 1, memo));\n }"},{"label":"Tabulation","explanation":"Track best if the previous house was robbed (skip current) vs not robbed (may rob current).","complexity":"O(n) time, O(1) space.","code":"int rob(int[] a) {\n     int robbed = 0, notRobbed = 0;\n     for (int x : a) {\n         int prevNot = notRobbed;\n         notRobbed = Math.max(notRobbed, robbed + x);\n         robbed = prevNot;\n     }\n     return Math.max(robbed, notRobbed);\n }"}]},{"id":172,"title":"House Robber II (Circular)","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"First  and  last  houses  are  adjacent,  so  either  drop  house  0  or  drop  house  n-1.  Run  the  linear  robber  on  each shortened range and take the max.","complexity":"O(2^n) per range without DP; use memo on each slice for practice.","code":"int rob(int[] a) {\n     if (a.length == 1) return a[0];\n     return Math.max(robRange(a, 0, a.length - 2), robRange(a, 1, a.length - 1));\n }\n int robRange(int[] a, int lo, int hi) {\n     int[] memo = new int[hi - lo + 1];\n     Arrays.fill(memo, -1);\n     return dp(a, lo, hi, lo, memo);\n }\n int dp(int[] a, int lo, int hi, int i, int[] memo) {\n     if (i > hi) return 0;\n     int idx = i - lo;\n     if (memo[idx] != -1) return memo[idx];\n     return memo[idx] = Math.max(a[i] + dp(a, lo, hi, i + 2, memo),\n         dp(a, lo, hi, i + 1, memo));\n }"},{"label":"Tabulation","explanation":"Linear DP on [0..n-2] and [1..n-1]; same rolling robbed / notRobbed as House Robber I.","complexity":"O(n) time, O(1) space.","code":"int rob(int[] a) {\n     if (a.length == 1) return a[0];\n     return Math.max(linear(a, 0, a.length - 2), linear(a, 1, a.length - 1));\n }\n int linear(int[] a, int lo, int hi) {\n     int robbed = 0, notRobbed = 0;\n     for (int i = lo; i <= hi; i++) {\n         int prevNot = notRobbed;\n         notRobbed = Math.max(notRobbed, robbed + a[i]);\n         robbed = prevNot;\n     }\n     return Math.max(robbed, notRobbed);\n }"}]},{"id":173,"title":"Unique Paths in a Grid","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"From (0,0) move only right or down until (m-1,n-1). Count every path by exploring both moves.","complexity":"O(C(m+n) choose m) paths, exponential recursion without memo.","code":"int uniquePaths(int m, int n) {\n     return paths(0, 0, m - 1, n - 1);\n }\n int paths(int r, int c, int er, int ec) {\n     if (r > er || c > ec) return 0;\n     if (r == er && c == ec) return 1;\n     return paths(r + 1, c, er, ec) + paths(r, c + 1, er, ec);\n }"},{"label":"Memoization","explanation":"Subproblem  (r,c)  =  number  of  paths  from  (r,c)  to  the  bottom-right.  Only  right/down  so  dp[r][c]  =  dp[r+1][c]  + dp[r][c+1].","complexity":"O(mn) time, O(mn) space.","code":"int uniquePaths(int m, int n) {\n     int[][] memo = new int[m][n];\n     for (int[] row : memo) Arrays.fill(row, -1);\n     return dp(0, 0, m - 1, n - 1, memo);\n }\n int dp(int r, int c, int er, int ec, int[][] memo) {\n     if (r > er || c > ec) return 0;\n     if (r == er && c == ec) return 1;\n     if (memo[r][c] != -1) return memo[r][c];\n     return memo[r][c] = dp(r + 1, c, er, ec, memo) + dp(r, c + 1, er, ec, memo);\n }"},{"label":"Tabulation","explanation":"First row and column are 1. Each cell is sum of cell above and left.","complexity":"O(mn) time, O(n) space with one row.","code":"int uniquePaths(int m, int n) {\n     int[] row = new int[n];\n     Arrays.fill(row, 1);\n     for (int i = 1; i < m; i++)\n         for (int j = 1; j < n; j++)\n             row[j] += row[j - 1];\n     return row[n - 1];\n }"}]},{"id":174,"title":"Minimum Path Sum in a Grid","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"From each cell go right or down and track the path sum. Keep the minimum over all paths to the bottom-right.","complexity":"Exponential paths, O(m+n) stack.","code":"int minPathSum(int[][] g) {\n     return walk(g, 0, 0, g[0][0]);\n }\n int walk(int[][] g, int r, int c, int sum) {\n     int m = g.length, n = g[0].length;\n     if (r == m - 1 && c == n - 1) return sum;\n     int best = Integer.MAX_VALUE;\n     if (r + 1 < m) best = Math.min(best, walk(g, r + 1, c, sum + g[r + 1][c]));\n     if (c + 1 < n) best = Math.min(best, walk(g, r, c + 1, sum + g[r][c + 1]));\n     return best;\n }"},{"label":"Memoization","explanation":"dp[r][c] = min sum from (r,c) to corner. Transition adds g[r][c] to min of down/right.","complexity":"O(mn) time, O(mn) space.","code":"int minPathSum(int[][] g) {\n     int m = g.length, n = g[0].length;\n     int[][] memo = new int[m][n];\n     for (int[] row : memo) Arrays.fill(row, -1);\n     return dp(g, 0, 0, memo);\n }\n int dp(int[][] g, int r, int c, int[][] memo) {\n     int m = g.length, n = g[0].length;\n     if (r == m - 1 && c == n - 1) return g[r][c];\n     if (memo[r][c] != -1) return memo[r][c];\n     int best = Integer.MAX_VALUE;\n     if (r + 1 < m) best = Math.min(best, dp(g, r + 1, c, memo));\n     if (c + 1 < n) best = Math.min(best, dp(g, r, c + 1, memo));\n     return memo[r][c] = g[r][c] + best;\n }"},{"label":"Tabulation","explanation":"Fill dp in row-major order; first row/column only have one predecessor.","complexity":"O(mn) time, O(n) space.","code":"int minPathSum(int[][] g) {\n     int m = g.length, n = g[0].length;\n     int[] dp = new int[n];\n     dp[0] = g[0][0];\n     for (int j = 1; j < n; j++) dp[j] = dp[j - 1] + g[0][j];\n     for (int i = 1; i < m; i++) {\n         dp[0] += g[i][0];\n         for (int j = 1; j < n; j++)\n             dp[j] = g[i][j] + Math.min(dp[j], dp[j - 1]);\n     }\n     return dp[n - 1];\n }"}]},{"id":175,"title":"Triangle — Minimum Path Sum","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"From row r, column c you may go to (r+1,c) or (r+1,c+1). Sum the path and minimize over all routes to the last row.","complexity":"O(2^n) time, O(n) stack.","code":"int minimumTotal(List<List<Integer>> t) {\n     return dfs(t, 0, 0);\n }\n int dfs(List<List<Integer>> t, int r, int c) {\n     if (r == t.size() - 1) return t.get(r).get(c);\n     return t.get(r).get(c) + Math.min(dfs(t, r + 1, c), dfs(t, r + 1, c + 1));\n }"},{"label":"Memoization","explanation":"State (r,c) is min sum from that cell to the bottom.","complexity":"O(n^2) time, O(n^2) space.","code":"int minimumTotal(List<List<Integer>> t) {\n     int n = t.size();\n     int[][] memo = new int[n][n];\n     for (int[] row : memo) Arrays.fill(row, -1);\n     return dp(t, 0, 0, memo);\n }\n int dp(List<List<Integer>> t, int r, int c, int[][] memo) {\n     if (r == t.size() - 1) return t.get(r).get(c);\n     if (memo[r][c] != -1) return memo[r][c];\n     return memo[r][c] = t.get(r).get(c)\n         + Math.min(dp(t, r + 1, c, memo), dp(t, r + 1, c + 1, memo));\n }"},{"label":"Tabulation","explanation":"Start from the bottom row and for each row take min of the two children below.","complexity":"O(n^2) time, O(n) space.","code":"int minimumTotal(List<List<Integer>> t) {\n     int n = t.size();\n     int[] dp = new int[n];\n     for (int c = 0; c < n; c++) dp[c] = t.get(n - 1).get(c);\n     for (int r = n - 2; r >= 0; r--)\n         for (int c = 0; c <= r; c++)\n             dp[c] = t.get(r).get(c) + Math.min(dp[c], dp[c + 1]);\n     return dp[0];\n }"}]},{"id":176,"title":"Minimum Falling Path Sum","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"From (r,c) fall to (r+1,c-1), (r+1,c), or (r+1,c+1). Try all downward paths and minimize total.","complexity":"O(3^n) time, O(n) stack.","code":"int minFallingPathSum(int[][] m) {\n     int n = m.length, best = Integer.MAX_VALUE;\n     for (int c = 0; c < n; c++)\n         best = Math.min(best, fall(m, 0, c));\n     return best;\n }\n int fall(int[][] m, int r, int c) {\n     int n = m.length;\n     if (r == n - 1) return m[r][c];\n     int best = Integer.MAX_VALUE;\n     for (int nc = Math.max(0, c - 1); nc <= Math.min(n - 1, c + 1); nc++)\n         best = Math.min(best, fall(m, r + 1, nc));\n     return m[r][c] + best;\n }"},{"label":"Memoization","explanation":"dp[r][c] = min sum from (r,c) to the last row following falling rules.","complexity":"O(n^2) time, O(n^2) space.","code":"int minFallingPathSum(int[][] m) {\n     int n = m.length;\n     int[][] memo = new int[n][n];\n     for (int[] row : memo) Arrays.fill(row, -1);\n     int best = Integer.MAX_VALUE;\n     for (int c = 0; c < n; c++) best = Math.min(best, dp(m, 0, c, memo));\n     return best;\n }\n int dp(int[][] m, int r, int c, int[][] memo) {\n     int n = m.length;\n     if (r == n - 1) return m[r][c];\n     if (memo[r][c] != -1) return memo[r][c];\n     int best = Integer.MAX_VALUE;\n     for (int nc = Math.max(0, c - 1); nc <= Math.min(n - 1, c + 1); nc++)\n         best = Math.min(best, dp(m, r + 1, nc, memo));\n     return memo[r][c] = m[r][c] + best;\n }"},{"label":"Tabulation","explanation":"Copy the matrix and pull each cell from the min of up to three parents in the row below.","complexity":"O(n^2) time, O(n) space.","code":"int minFallingPathSum(int[][] m) {\n     int n = m.length;\n     int[] dp = m[n - 1].clone();\n     for (int r = n - 2; r >= 0; r--) {\n         int[] next = new int[n];\n         for (int c = 0; c < n; c++) {\n             int best = dp[c];\n             if (c > 0) best = Math.min(best, dp[c - 1]);\n             if (c + 1 < n) best = Math.min(best, dp[c + 1]);\n             next[c] = m[r][c] + best;\n         }\n         dp = next;\n     }\n     int ans = Integer.MAX_VALUE;\n     for (int x : dp) ans = Math.min(ans, x);\n     return ans;\n }"}]},{"id":177,"title":"Partition Equal Subset Sum","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"Try every subset for sum S; the complement must also be S, so total must be even and some subset hits sum/2.","complexity":"O(2^n) time, O(n) stack.","code":"boolean canPartition(int[] a) {\n     int sum = 0;\n     for (int x : a) sum += x;\n     if (sum % 2 == 1) return false;\n     return subset(a, 0, sum / 2);\n }\n boolean subset(int[] a, int i, int target) {\n     if (target == 0) return true;\n     if (i == a.length || target < 0) return false;\n     return subset(a, i + 1, target - a[i]) || subset(a, i + 1, target);\n }"},{"label":"Memoization","explanation":"State (i, target) = can we reach target using elements from index i onward.","complexity":"O(n * sum) time, O(n * sum) space.","code":"boolean canPartition(int[] a) {\n     int sum = 0;\n     for (int x : a) sum += x;\n     if (sum % 2 == 1) return false;\n     int half = sum / 2;\n     Boolean[][] memo = new Boolean[a.length][half + 1];\n     return dp(a, 0, half, memo);\n }\n boolean dp(int[] a, int i, int t, Boolean[][] memo) {\n     if (t == 0) return true;\n     if (i == a.length || t < 0) return false;\n     if (memo[i][t] != null) return memo[i][t];\n     return memo[i][t] = dp(a, i + 1, t - a[i], memo) || dp(a, i + 1, t, memo);\n }"},{"label":"Tabulation","explanation":"Boolean knapsack: dp[j] true if sum j is reachable. Roll from right to left when taking a[i].","complexity":"O(n * sum) time, O(sum) space.","code":"boolean canPartition(int[] a) {\n     int sum = 0;\n     for (int x : a) sum += x;\n     if (sum % 2 == 1) return false;\n     int half = sum / 2;\n     boolean[] dp = new boolean[half + 1];\n     dp[0] = true;\n     for (int x : a)\n         for (int j = half; j >= x; j--)\n             dp[j] |= dp[j - x];\n     return dp[half];\n }"}]},{"id":178,"title":"0/1 Knapsack","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"For each item, include it in the knapsack or skip it. Maximize value without exceeding capacity W.","complexity":"O(2^n) time, O(n) stack.","code":"int knapsack(int[] wt, int[] val, int W) {\n     return pick(wt, val, 0, W);\n }\n int pick(int[] wt, int[] val, int i, int cap) {\n     if (i == wt.length || cap == 0) return 0;\n     int skip = pick(wt, val, i + 1, cap);\n     int take = 0;\n     if (wt[i] <= cap) take = val[i] + pick(wt, val, i + 1, cap - wt[i]);\n     return Math.max(skip, take);\n }"},{"label":"Memoization","explanation":"State (i, cap) = best value using items i..end with remaining capacity cap.","complexity":"O(n * W) time, O(n * W) space.","code":"int knapsack(int[] wt, int[] val, int W) {\n     int[][] memo = new int[wt.length][W + 1];\n     for (int[] row : memo) Arrays.fill(row, -1);\n     return dp(wt, val, 0, W, memo);\n }\n int dp(int[] wt, int[] val, int i, int cap, int[][] memo) {\n     if (i == wt.length || cap == 0) return 0;\n     if (memo[i][cap] != -1) return memo[i][cap];\n     int best = dp(wt, val, i + 1, cap, memo);\n     if (wt[i] <= cap)\n         best = Math.max(best, val[i] + dp(wt, val, i + 1, cap - wt[i], memo));\n     return memo[i][cap] = best;\n }"},{"label":"Tabulation","explanation":"dp[cap] = max value for that capacity. Process each item once, iterating capacity downward.","complexity":"O(n * W) time, O(W) space.","code":"int knapsack(int[] wt, int[] val, int W) {\n     int[] dp = new int[W + 1];\n     for (int i = 0; i < wt.length; i++)\n         for (int c = W; c >= wt[i]; c--)\n             dp[c] = Math.max(dp[c], dp[c - wt[i]] + val[i]);\n     return dp[W];\n }"}]},{"id":179,"title":"Coin Change (Minimum Coins)","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"Try every coin as the first pick and recurse on amount - coin. Minimize 1 + best sub-answer.","complexity":"O(S^n) time for amount S and n coin types, exponential stack.","code":"int coinChange(int[] coins, int amount) {\n     int ans = minCoins(coins, amount);\n     return ans >= Integer.MAX_VALUE / 2 ? -1 : ans;\n }\n int minCoins(int[] coins, int left) {\n     if (left == 0) return 0;\n     if (left < 0) return Integer.MAX_VALUE / 2;\n     int best = Integer.MAX_VALUE / 2;\n     for (int c : coins) best = Math.min(best, 1 + minCoins(coins, left - c));\n     return best;\n }"},{"label":"Memoization","explanation":"dp[a] = min coins to make amount a. Same recurrence with a cache on amount.","complexity":"O(n * amount) time, O(amount) space.","code":"int coinChange(int[] coins, int amount) {\n     int[] memo = new int[amount + 1];\n     Arrays.fill(memo, -1);\n     int ans = dp(coins, amount, memo);\n     return ans >= Integer.MAX_VALUE / 2 ? -1 : ans;\n }\n int dp(int[] coins, int left, int[] memo) {\n     if (left == 0) return 0;\n     if (left < 0) return Integer.MAX_VALUE / 2;\n     if (memo[left] != -1) return memo[left];\n     int best = Integer.MAX_VALUE / 2;\n     for (int c : coins) best = Math.min(best, 1 + dp(coins, left - c, memo));\n     return memo[left] = best;\n }"},{"label":"Tabulation","explanation":"Fill dp[0..amount] with INF; dp[0]=0. For each coin, improve every reachable amount.","complexity":"O(n * amount) time, O(amount) space.","code":"int coinChange(int[] coins, int amount) {\n     int[] dp = new int[amount + 1];\n     Arrays.fill(dp, amount + 1);\n     dp[0] = 0;\n     for (int c : coins)\n         for (int a = c; a <= amount; a++)\n             dp[a] = Math.min(dp[a], dp[a - c] + 1);\n     return dp[amount] > amount ? -1 : dp[amount];\n }"}]},{"id":180,"title":"Target Sum","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"Assign + or - to each number. At index i, branch on +nums[i] and -nums[i] and check if the running sum hits 0 at the end.","complexity":"O(2^n) time, O(n) stack.","code":"int findTargetSumWays(int[] a, int target) {\n     return ways(a, 0, 0, target);\n }\n int ways(int[] a, int i, int sum, int target) {\n     if (i == a.length) return sum == target ? 1 : 0;\n     return ways(a, i + 1, sum + a[i], target) + ways(a, i + 1, sum - a[i], target);\n }"},{"label":"Memoization","explanation":"State (i, sum) counts assignments on suffix i.. that reach target from partial sum sum.","complexity":"O(n * sum range) time, O(n * sum) space.","code":"int findTargetSumWays(int[] a, int target) {\n     int total = 0;\n     for (int x : a) total += x;\n     if ((total + target) % 2 != 0 || Math.abs(target) > total) return 0;\n     int need = (total + target) / 2;\n     int[][] memo = new int[a.length][need + 1];\n     for (int[] row : memo) Arrays.fill(row, -1);\n     return subset(a, 0, need, memo);\n }\n int subset(int[] a, int i, int t, int[][] memo) {\n     if (t == 0) return 1;\n     if (i == a.length || t < 0) return 0;\n     if (memo[i][t] != -1) return memo[i][t];\n     return memo[i][t] = subset(a, i + 1, t - a[i], memo) + subset(a, i + 1, t, memo);\n }"},{"label":"Tabulation","explanation":"Reduce to counting subsets with sum (total + target) / 2. dp[j] += ways to reach j.","complexity":"O(n * sum) time, O(sum) space.","code":"int findTargetSumWays(int[] a, int target) {\n     int total = 0;\n     for (int x : a) total += x;\n     if ((total + target) % 2 != 0 || Math.abs(target) > total) return 0;\n     int need = (total + target) / 2;\n     int[] dp = new int[need + 1];\n     dp[0] = 1;\n     for (int x : a)\n         for (int j = need; j >= x; j--)\n             dp[j] += dp[j - x];\n     return dp[need];\n }"}]},{"id":181,"title":"Best Time to Buy and Sell Stock","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"Try every buy day i and every sell day j > i. Track max(prices[j] - prices[i]).","complexity":"O(n^2) time, O(1) space.","code":"int maxProfit(int[] prices) {\n     int best = 0;\n     for (int i = 0; i < prices.length; i++)\n         for (int j = i + 1; j < prices.length; j++)\n             best = Math.max(best, prices[j] - prices[i]);\n     return best;\n }"},{"label":"Better","explanation":"One pass: min price seen so far is the best buy before today; update best profit with today’s price.","complexity":"O(n) time, O(1) space.","code":"int maxProfit(int[] prices) {\n     int best = 0, buy = prices[0];\n     for (int i = 1; i < prices.length; i++) {\n         best = Math.max(best, prices[i] - buy);\n         buy = Math.min(buy, prices[i]);\n     }\n     return best;\n }"}]},{"id":182,"title":"Best Time to Buy and Sell Stock with Cooldown","module":"Dynamic Programming","approaches":[{"label":"Memoization","explanation":"State (i, hold) where hold is 0 (free to buy) or 1 (holding stock). Buy, sell (+ cooldown day), or rest.","complexity":"O(n) time, O(n) space.","code":"int maxProfit(int[] p) {\n     int[][] memo = new int[p.length][2];\n         for (int[] row : memo) Arrays.fill(row, -1);\n     return dp(p, 0, 0, memo);\n }\n int dp(int[] p, int i, int hold, int[][] memo) {\n     if (i == p.length) return 0;\n     if (memo[i][hold] != -1) return memo[i][hold];\n     if (hold == 0)\n         return memo[i][hold] = Math.max(dp(p, i + 1, 0, memo), -p[i] + dp(p, i + 1, 1, memo));\n     return memo[i][hold] = Math.max(dp(p, i + 1, 1, memo), p[i] + dp(p, i + 2, 0, memo));\n }"},{"label":"Tabulation","explanation":"Three rolling states: sold (just sold), hold, rest (cooldown finished). Transitions match the recursion.","complexity":"O(n) time, O(1) space.","code":"int maxProfit(int[] p) {\n     int sold = 0, hold = Integer.MIN_VALUE / 2, rest = 0;\n     for (int x : p) {\n         int prevSold = sold;\n         sold = hold + x;\n         hold = Math.max(hold, rest - x);\n         rest = Math.max(rest, prevSold);\n     }\n     return Math.max(sold, rest);\n }"}]},{"id":183,"title":"Best Time to Buy and Sell Stock (At Most k Transactions)","module":"Dynamic Programming","approaches":[{"label":"Memoization","explanation":"State (day, k left, hold). Each day: buy (spend one transaction slot), sell, or skip.","complexity":"O(n * k) time, O(n * k) space.","code":"int maxProfit(int k, int[] p) {\n     if (k >= p.length / 2) {\n         int profit = 0;\n         for (int i = 1; i < p.length; i++)\n             if (p[i] > p[i - 1]) profit += p[i] - p[i - 1];\n         return profit;\n     }\n     int[][][] memo = new int[p.length][k + 1][2];\n     for (int[][] a : memo)\n         for (int[] b : a) Arrays.fill(b, -1);\n     return dp(p, 0, k, 0, memo);\n }\n int dp(int[] p, int i, int k, int hold, int[][][] memo) {\n     if (i == p.length) return 0;\n     if (memo[i][k][hold] != -1) return memo[i][k][hold];\n     if (hold == 0) {\n         int skip = dp(p, i + 1, k, 0, memo);\n         int buy = (k > 0) ? -p[i] + dp(p, i + 1, k - 1, 1, memo) : Integer.MIN_VALUE / 2;\n         return memo[i][k][hold] = Math.max(skip, buy);\n     }\n     int skip = dp(p, i + 1, k, 1, memo);\n     int sell = p[i] + dp(p, i + 1, k, 0, memo);\n     return memo[i][k][hold] = Math.max(skip, sell);\n }"},{"label":"Tabulation","explanation":"buy[j] = max profit after j buys; sell[j] = max after j complete transactions. Update in one forward pass.","complexity":"O(n * k) time, O(k) space.","code":"int maxProfit(int k, int[] p) {\n     if (k >= p.length / 2) {\n         int profit = 0;\n         for (int i = 1; i < p.length; i++)\n             if (p[i] > p[i - 1]) profit += p[i] - p[i - 1];\n         return profit;\n     }\n     int[] buy = new int[k + 1];\n     int[] sell = new int[k + 1];\n     Arrays.fill(buy, Integer.MIN_VALUE / 2);\n     for (int x : p) {\n         for (int j = 1; j <= k; j++) {\n             buy[j] = Math.max(buy[j], sell[j - 1] - x);\n             sell[j] = Math.max(sell[j], buy[j] + x);\n         }\n     }\n     return sell[k];\n }"}]},{"id":184,"title":"Longest Increasing Subsequence","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"For each start index, extend while values strictly increase. Track the longest length.","complexity":"O(2^n) if generating all subsequences; O(n^2) greedy extension per start.","code":"int lengthOfLIS(int[] a) {\n     int best = 0;\n     for (int i = 0; i < a.length; i++) best = Math.max(best, extend(a, i));\n     return best;\n }\n int extend(int[] a, int i) {\n     int len = 1;\n     for (int j = i + 1; j < a.length; j++)\n         if (a[j] > a[i]) len = Math.max(len, 1 + extend(a, j));\n     return len;\n }"},{"label":"Tabulation","explanation":"dp[i] = LIS ending at i. For every j < i with a[j] < a[i], dp[i] = max(dp[i], dp[j] + 1).","complexity":"O(n^2) time, O(n) space.","code":"int lengthOfLIS(int[] a) {\n     int n = a.length, best = 0;\n     int[] dp = new int[n];\n     Arrays.fill(dp, 1);\n     for (int i = 0; i < n; i++) {\n         for (int j = 0; j < i; j++)\n             if (a[j] < a[i]) dp[i] = Math.max(dp[i], dp[j] + 1);\n         best = Math.max(best, dp[i]);\n     }\n     return best;\n }"},{"label":"Optimal","explanation":"tails[len] = smallest ending value of an increasing subsequence of length len+1. Binary search the position of a[i].","complexity":"O(n log n) time, O(n) space.","code":"int lengthOfLIS(int[] a) {\n     int[] tails = new int[a.length];\n     int len = 0;\n     for (int x : a) {\n         int lo = 0, hi = len;\n         while (lo < hi) {\n             int mid = (lo + hi) >>> 1;\n             if (tails[mid] < x) lo = mid + 1;\n             else hi = mid;\n         }\n         tails[lo] = x;\n         if (lo == len) len++;\n     }\n     return len;\n }"}]},{"id":185,"title":"Longest Common Subsequence","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"Recurse on both strings: match advances both; mismatch tries skipping either side.","complexity":"O(2^(m+n)) time, O(m+n) stack.","code":"int longestCommonSubsequence(String s, String t) {\n     return lcs(s, t, 0, 0);\n }\n int lcs(String s, String t, int i, int j) {\n     if (i == s.length() || j == t.length()) return 0;\n     if (s.charAt(i) == t.charAt(j))\n         return 1 + lcs(s, t, i + 1, j + 1);\n     return Math.max(lcs(s, t, i + 1, j), lcs(s, t, i, j + 1));\n }"},{"label":"Memoization","explanation":"dp[i][j] = LCS length of suffixes s[i..] and t[j..].","complexity":"O(mn) time, O(mn) space.","code":"int longestCommonSubsequence(String s, String t) {\n     int[][] memo = new int[s.length()][t.length()];\n     for (int[] row : memo) Arrays.fill(row, -1);\n     return dp(s, t, 0, 0, memo);\n }\n int dp(String s, String t, int i, int j, int[][] memo) {\n     if (i == s.length() || j == t.length()) return 0;\n     if (memo[i][j] != -1) return memo[i][j];\n     if (s.charAt(i) == t.charAt(j))\n         return memo[i][j] = 1 + dp(s, t, i + 1, j + 1, memo);\n     return memo[i][j] = Math.max(dp(s, t, i + 1, j, memo), dp(s, t, i, j + 1, memo));\n }"},{"label":"Tabulation","explanation":"Fill a table where match extends diagonal, else max of up/left.","complexity":"O(mn) time, O(n) space.","code":"int longestCommonSubsequence(String s, String t) {\n     int m = s.length(), n = t.length();\n     int[] prev = new int[n + 1], cur = new int[n + 1];\n     for (int i = 1; i <= m; i++) {\n         for (int j = 1; j <= n; j++) {\n             if (s.charAt(i - 1) == t.charAt(j - 1)) cur[j] = prev[j - 1] + 1;\n             else cur[j] = Math.max(prev[j], cur[j - 1]);\n         }\n         int[] tmp = prev; prev = cur; cur = tmp;\n         Arrays.fill(cur, 0);\n     }\n     return prev[n];\n }"}]},{"id":186,"title":"Edit Distance","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"Align prefixes: match both, or insert, delete, or replace on word1 to match word2.","complexity":"O(3^(m+n)) time without memo, O(m+n) stack.","code":"int minDistance(String a, String b) {\n     return edit(a, b, 0, 0);\n }\n int edit(String a, String b, int i, int j) {\n     if (i == a.length()) return b.length() - j;\n     if (j == b.length()) return a.length() - i;\n     if (a.charAt(i) == b.charAt(j)) return edit(a, b, i + 1, j + 1);\n     int rep = 1 + edit(a, b, i + 1, j + 1);\n     int del = 1 + edit(a, b, i + 1, j);\n     int ins = 1 + edit(a, b, i, j + 1);\n     return Math.min(rep, Math.min(del, ins));\n }"},{"label":"Memoization","explanation":"dp[i][j] = min edits to turn a[i..] into b[j..].","complexity":"O(mn) time, O(mn) space.","code":"int minDistance(String a, String b) {\n     int[][] memo = new int[a.length()][b.length()];\n     for (int[] row : memo) Arrays.fill(row, -1);\n     return dp(a, b, 0, 0, memo);\n }\n int dp(String a, String b, int i, int j, int[][] memo) {\n     if (i == a.length()) return b.length() - j;\n     if (j == b.length()) return a.length() - i;\n     if (memo[i][j] != -1) return memo[i][j];\n     if (a.charAt(i) == b.charAt(j)) return memo[i][j] = dp(a, b, i + 1, j + 1, memo);\n     int rep = 1 + dp(a, b, i + 1, j + 1, memo);\n     int del = 1 + dp(a, b, i + 1, j, memo);\n     int ins = 1 + dp(a, b, i, j + 1, memo);\n     return memo[i][j] = Math.min(rep, Math.min(del, ins));\n }"},{"label":"Tabulation","explanation":"Base cases: empty prefix costs equal to other string length. Fill row by row.","complexity":"O(mn) time, O(n) space.","code":"int minDistance(String a, String b) {\n     int m = a.length(), n = b.length();\n     int[] prev = new int[n + 1], cur = new int[n + 1];\n     for (int j = 0; j <= n; j++) prev[j] = j;\n     for (int i = 1; i <= m; i++) {\n         cur[0] = i;\n         for (int j = 1; j <= n; j++) {\n             if (a.charAt(i - 1) == b.charAt(j - 1)) cur[j] = prev[j - 1];\n             else cur[j] = 1 + Math.min(prev[j - 1], Math.min(prev[j], cur[j - 1]));\n         }\n         int[] tmp = prev; prev = cur; cur = tmp;\n     }\n     return prev[n];\n }"}]},{"id":187,"title":"Distinct Subsequences","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"Walk s with index i and t with j. Match advances both; on s you may skip the current char or take it if it matches t[j].","complexity":"O(2^m) time, O(m+n) stack.","code":"int numDistinct(String s, String t) {\n     return count(s, t, 0, 0);\n }\n int count(String s, String t, int i, int j) {\n     if (j == t.length()) return 1;\n     if (i == s.length()) return 0;\n     long ways = count(s, t, i + 1, j);\n     if (s.charAt(i) == t.charAt(j)) ways += count(s, t, i + 1, j + 1);\n     return (int) ways;\n }"},{"label":"Memoization","explanation":"dp[i][j] = ways to form t[j..] using s[i..]. Add dp[i+1][j+1] on match plus skip s[i].","complexity":"O(mn) time, O(mn) space.","code":"int numDistinct(String s, String t) {\n     int[][] memo = new int[s.length()][t.length()];\n     for (int[] row : memo) Arrays.fill(row, -1);\n     return dp(s, t, 0, 0, memo);\n }\n int dp(String s, String t, int i, int j, int[][] memo) {\n     if (j == t.length()) return 1;\n     if (i == s.length()) return 0;\n     if (memo[i][j] != -1) return memo[i][j];\n     long ways = dp(s, t, i + 1, j, memo);\n     if (s.charAt(i) == t.charAt(j)) ways += dp(s, t, i + 1, j + 1, memo);\n     return memo[i][j] = (int) ways;\n }"},{"label":"Tabulation","explanation":"dp[j] = ways to match t[0..j). Scan s left to right, update dp backward on matches.","complexity":"O(mn) time, O(n) space.","code":"int numDistinct(String s, String t) {\n     int n = t.length();\n     int[] dp = new int[n + 1];\n     dp[0] = 1;\n     for (int i = 0; i < s.length(); i++)\n         for (int j = n - 1; j >= 0; j--)\n             if (s.charAt(i) == t.charAt(j)) dp[j + 1] += dp[j];\n     return dp[n];\n }"}]},{"id":188,"title":"Wildcard Matching","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"'?' matches one char; '*' matches any sequence (including empty). Branch on both interpretations for '*'.","complexity":"Exponential without memo, O(m+n) stack.","code":"boolean isMatch(String s, String p) {\n     return match(s, p, 0, 0);\n }\n boolean match(String s, String p, int i, int j) {\n     if (j == p.length()) return i == s.length();\n     if (p.charAt(j) == '*')\n         return match(s, p, i, j + 1) || (i < s.length() && match(s, p, i + 1, j));\n     if (i == s.length()) return false;\n     if (p.charAt(j) == '?' || p.charAt(j) == s.charAt(i))\n         return match(s, p, i + 1, j + 1);\n     return false;\n }"},{"label":"Memoization","explanation":"Cache (i,j) for the same recursive cases.","complexity":"O(mn) time, O(mn) space.","code":"boolean isMatch(String s, String p) {\n     Boolean[][] memo = new Boolean[s.length()][p.length()];\n     return dp(s, p, 0, 0, memo);\n }\n boolean dp(String s, String p, int i, int j, Boolean[][] memo) {\n     if (j == p.length()) return i == s.length();\n     if (memo[i][j] != null) return memo[i][j];\n     boolean ans;\n     if (p.charAt(j) == '*')\n         ans = dp(s, p, i, j + 1, memo) || (i < s.length() && dp(s, p, i + 1, j, memo));\n     else if (i == s.length()) ans = false;\n     else if (p.charAt(j) == '?' || p.charAt(j) == s.charAt(i))\n         ans = dp(s, p, i + 1, j + 1, memo);\n     else ans = false;\n     return memo[i][j] = ans;\n }"},{"label":"Tabulation","explanation":"dp[i][j] = match s[0..i) with p[0..j). Star row: empty match or extend match with one more char.","complexity":"O(mn) time, O(n) space.","code":"boolean isMatch(String s, String p) {\n     int m = s.length(), n = p.length();\n     boolean[] prev = new boolean[n + 1];\n     prev[0] = true;\n     for (int j = 1; j <= n; j++)\n         if (p.charAt(j - 1) != '*') prev[j] = false;\n     for (int i = 1; i <= m; i++) {\n         boolean[] cur = new boolean[n + 1];\n         for (int j = 1; j <= n; j++) {\n             char pc = p.charAt(j - 1);\n             if (pc == '*') cur[j] = cur[j - 1] || prev[j];\n             else if (pc == '?' || s.charAt(i - 1) == pc) cur[j] = prev[j - 1];\n         }\n         prev = cur;\n     }\n     return prev[n];\n }"}]},{"id":189,"title":"Matrix Chain Multiplication","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"Try every split k between i and j for matrices i..j. Cost = left cost + right cost + multiply sizes.","complexity":"O(2^n) time, O(n) stack.","code":"int matrixChainOrder(int[] dim) {\n     int n = dim.length - 1;\n     return mcm(dim, 1, n);\n }\n int mcm(int[] dim, int i, int j) {\n     if (i >= j) return 0;\n     int best = Integer.MAX_VALUE;\n     for (int k = i; k < j; k++) {\n         int cost = mcm(dim, i, k) + mcm(dim, k + 1, j)\n             + dim[i - 1] * dim[k] * dim[j];\n         best = Math.min(best, cost);\n     }\n     return best;\n }"},{"label":"Memoization","explanation":"dp[i][j] = min scalar multiplications for chain i..j (1-based matrix indices).","complexity":"O(n^3) time, O(n^2) space.","code":"int matrixChainOrder(int[] dim) {\n     int n = dim.length - 1;\n     int[][] memo = new int[n + 1][n + 1];\n     for (int[] row : memo) Arrays.fill(row, -1);\n     return dp(dim, 1, n, memo);\n }\n int dp(int[] dim, int i, int j, int[][] memo) {\n     if (i >= j) return 0;\n     if (memo[i][j] != -1) return memo[i][j];\n     int best = Integer.MAX_VALUE;\n     for (int k = i; k < j; k++) {\n         int cost = dp(dim, i, k, memo) + dp(dim, k + 1, j, memo)\n             + dim[i - 1] * dim[k] * dim[j];\n         best = Math.min(best, cost);\n     }\n     return memo[i][j] = best;\n }"},{"label":"Tabulation","explanation":"Increase chain length L from 2 to n and try every split inside [i..j].","complexity":"O(n^3) time, O(n^2) space.","code":"int matrixChainOrder(int[] dim) {\n     int n = dim.length - 1;\n     int[][] dp = new int[n + 1][n + 1];\n     for (int len = 2; len <= n; len++)\n         for (int i = 1; i + len - 1 <= n; i++) {\n             int j = i + len - 1;\n             dp[i][j] = Integer.MAX_VALUE;\n             for (int k = i; k < j; k++)\n                 dp[i][j] = Math.min(dp[i][j],\n                     dp[i][k] + dp[k + 1][j] + dim[i - 1] * dim[k] * dim[j]);\n         }\n     return dp[1][n];\n }"}]},{"id":190,"title":"Burst Balloons","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"Pick the last balloon k to burst in range (i,j); coins = nums[i]*nums[k]*nums[j] plus left and right sub-ranges.","complexity":"O(4^n) time without memo.","code":"int maxCoins(int[] nums) {\n     int n = nums.length;\n     int[] a = new int[n + 2];\n     a[0] = a[n + 1] = 1;\n     for (int i = 0; i < n; i++) a[i + 1] = nums[i];\n     return burst(a, 0, n + 1);\n }\n int burst(int[] a, int i, int j) {\n     if (i + 1 >= j) return 0;\n     int best = 0;\n     for (int k = i + 1; k < j; k++) {\n         int gain = a[i] * a[k] * a[j]\n             + burst(a, i, k) + burst(a, k, j);\n         best = Math.max(best, gain);\n     }\n     return best;\n }"},{"label":"Memoization","explanation":"Pad with 1s. dp[i][j] = max coins for open interval (i,j) excluding borders.","complexity":"O(n^3) time, O(n^2) space.","code":"int maxCoins(int[] nums) {\n     int n = nums.length;\n     int[] a = new int[n + 2];\n     a[0] = a[n + 1] = 1;\n     for (int i = 0; i < n; i++) a[i + 1] = nums[i];\n     int[][] memo = new int[n + 2][n + 2];\n     for (int[] row : memo) Arrays.fill(row, -1);\n     return dp(a, 0, n + 1, memo);\n }\n int dp(int[] a, int i, int j, int[][] memo) {\n     if (i + 1 >= j) return 0;\n     if (memo[i][j] != -1) return memo[i][j];\n     int best = 0;\n     for (int k = i + 1; k < j; k++) {\n         int gain = a[i] * a[k] * a[j] + dp(a, i, k, memo) + dp(a, k, j, memo);\n         best = Math.max(best, gain);\n     }\n     return memo[i][j] = best;\n }"},{"label":"Tabulation","explanation":"Same interval DP as memo, increasing window length on the padded array.","complexity":"O(n^3) time, O(n^2) space.","code":"int maxCoins(int[] nums) {\n     int n = nums.length;\n     int[] a = new int[n + 2];\n     a[0] = a[n + 1] = 1;\n     for (int i = 0; i < n; i++) a[i + 1] = nums[i];\n     int m = n + 2;\n     int[][] dp = new int[m][m];\n     for (int len = 3; len <= m; len++)\n         for (int i = 0; i + len - 1 < m; i++) {\n             int j = i + len - 1;\n             for (int k = i + 1; k < j; k++)\n                 dp[i][j] = Math.max(dp[i][j],\n                     a[i] * a[k] * a[j] + dp[i][k] + dp[k][j]);\n         }\n     return dp[0][m - 1];\n }"}]},{"id":191,"title":"Palindrome Partitioning II (Minimum Cuts)","module":"Dynamic Programming","approaches":[{"label":"Brute force","explanation":"Try every cut position after i if s[0..i] is a palindrome; 1 + min cuts on the suffix.","complexity":"O(2^n) time, O(n) stack.","code":"int minCut(String s) {\n     return cuts(s, 0);\n }\n int cuts(String s, int start) {\n     if (start == s.length()) return -1;\n     int best = Integer.MAX_VALUE;\n     for (int end = start; end < s.length(); end++)\n         if (isPal(s, start, end))\n             best = Math.min(best, 1 + cuts(s, end + 1));\n     return best;\n }\n boolean isPal(String s, int l, int r) {\n     while (l < r) if (s.charAt(l++) != s.charAt(r--)) return false;\n     return true;\n }"},{"label":"Memoization","explanation":"dp[i] = min cuts for suffix s[i..]. Precompute palindrome table to check segments in O(1).","complexity":"O(n^2) time, O(n^2) space.","code":"int minCut(String s) {\n     int n = s.length();\n     boolean[][] pal = new boolean[n][n];\n     for (int i = n - 1; i >= 0; i--)\n         for (int j = i; j < n; j++)\n             pal[i][j] = s.charAt(i) == s.charAt(j)\n                 && (j - i < 2 || pal[i + 1][j - 1]);\n     int[] memo = new int[n];\n     Arrays.fill(memo, -1);\n     return dp(s, 0, pal, memo);\n }\n int dp(String s, int i, boolean[][] pal, int[] memo) {\n     if (i == s.length()) return -1;\n     if (memo[i] != -1) return memo[i];\n     int best = Integer.MAX_VALUE;\n     for (int j = i; j < s.length(); j++)\n         if (pal[i][j]) best = Math.min(best, 1 + dp(s, j + 1, pal, memo));\n     return memo[i] = best;\n }"},{"label":"Tabulation","explanation":"cuts[i] = min cuts for s[i..]. If s[i..j] palindrome, cuts[i] = min(cuts[i], cuts[j+1]+1).","complexity":"O(n^2) time, O(n^2) space.","code":"int minCut(String s) {\n     int n = s.length();\n     boolean[][] pal = new boolean[n][n];\n     for (int i = n - 1; i >= 0; i--)\n         for (int j = i; j < n; j++)\n             pal[i][j] = s.charAt(i) == s.charAt(j)\n                 && (j - i < 2 || pal[i + 1][j - 1]);\n     int[] cuts = new int[n];\n     for (int i = 0; i < n; i++) {\n         cuts[i] = i;\n         for (int j = 0; j <= i; j++)\n             if (pal[j][i]) cuts[i] = Math.min(cuts[i], (j > 0 ? cuts[j - 1] : -1) + 1);\n     }\n     return cuts[n - 1];\n }"}]},{"id":192,"title":"Implement Trie (Prefix Tree)","module":"Tries","approaches":[{"label":"Brute force","explanation":"Store every word in a list. Search and startsWith scan all strings and compare character by character.","complexity":"O(n * L) per query, n words, L average length.","code":"class WordList {\n     List<String> words = new ArrayList<>();\n     void insert(String w) { words.add(w); }\n     boolean search(String w) { return words.contains(w); }\n     boolean startsWith(String p) {\n         for (String s : words) if (s.startsWith(p)) return true;\n         return false;\n     }\n }"},{"label":"Better","explanation":"Array of 26 children per node plus end-of-word flag. Walk one char per edge; missing child means no match.","complexity":"O(L) per operation, O(total chars) space.","code":"class Trie {\n     static class Node {\n         Node[] next = new Node[26];\n         boolean end;\n     }\n     Node root = new Node();\n     public void insert(String w) {\n         Node cur = root;\n         for (char ch : w.toCharArray()) {\n             int i = ch - 'a';\n             if (cur.next[i] == null) cur.next[i] = new Node();\n             cur = cur.next[i];\n         }\n         cur.end = true;\n     }\n     public boolean search(String w) {\n         Node node = walk(w);\n         return node != null && node.end;\n     }\n     public boolean startsWith(String p) {\n         return walk(p) != null;\n     }\n     Node walk(String s) {\n         Node cur = root;\n         for (char ch : s.toCharArray()) {\n             int i = ch - 'a';\n             if (cur.next[i] == null) return null;\n             cur = cur.next[i];\n         }\n         return cur;\n     }\n }"}]},{"id":193,"title":"Design Add and Search Words Data Structure","module":"Tries","approaches":[{"label":"Brute force","explanation":"Keep a list of inserted words. Search with '.' tries every letter at that position across all words.","complexity":"O(n * 26^d) worst case for n words and d dots.","code":"class WordDictionary {\n     List<String> words = new ArrayList<>();\n     public void addWord(String w) { words.add(w); }\n     public boolean search(String w) {\n         for (String s : words) if (match(s, w, 0)) return true;\n         return false;\n     }\n     boolean match(String s, String w, int i) {\n         if (i == w.length()) return s.length() == w.length();\n         char c = w.charAt(i);\n         if (c == '.') {\n             for (char ch = 'a'; ch <= 'z'; ch++)\n                 if (i < s.length() && s.charAt(i) == ch && match(s, w, i + 1)) return true;\n             return false;\n         }\n         return i < s.length() && s.charAt(i) == c && match(s, w, i + 1);\n     }\n }"},{"label":"Optimal","explanation":"Trie for exact letters; on '.' DFS all 26 children at that level.","complexity":"O(L) for exact search; O(26^k * L) with k wildcards.","code":"class WordDictionary {\n     static class Node {\n         Node[] next = new Node[26];\n         boolean end;\n     }\n     Node root = new Node();\n     public void addWord(String w) {\n         Node cur = root;\n         for (char ch : w.toCharArray()) {\n             int i = ch - 'a';\n             if (cur.next[i] == null) cur.next[i] = new Node();\n             cur = cur.next[i];\n         }\n         cur.end = true;\n     }\n     public boolean search(String w) { return dfs(root, w, 0); }\n     boolean dfs(Node node, String w, int i) {\n         if (node == null) return false;\n         if (i == w.length()) return node.end;\n         char c = w.charAt(i);\n         if (c == '.') {\n             for (int k = 0; k < 26; k++)\n                 if (dfs(node.next[k], w, i + 1)) return true;\n             return false;\n         }\n         return dfs(node.next[c - 'a'], w, i + 1);\n     }\n }"}]},{"id":194,"title":"Longest Word in Dictionary (Complete String)","module":"Tries","approaches":[{"label":"Brute force","explanation":"Sort words by length then lex order. A word is valid only if every proper prefix exists in the set.","complexity":"O(n * L^2) time checking prefixes, O(n * L) space.","code":"String longestWord(String[] words) {\n         Set<String> set = new HashSet<>(Arrays.asList(words));\n         Arrays.sort(words, (a, b) -> a.length() != b.length()\n             ? a.length() - b.length() : a.compareTo(b));\n         String best = \"\";\n         for (String w : words) {\n             if (!canBuild(w, set)) continue;\n             if (w.length() > best.length()\n                 || (w.length() == best.length() && w.compareTo(best) < 0))\n                 best = w;\n         }\n         return best;\n     }\n     boolean canBuild(String w, Set<String> set) {\n         for (int i = 1; i < w.length(); i++)\n             if (!set.contains(w.substring(0, i))) return false;\n         return true;\n     }"},{"label":"Optimal","explanation":"Insert into trie; DFS from root following only nodes marked end. Track longest complete path.","complexity":"O(total chars) time and space.","code":"String longestWord(String[] words) {\n         TrieNode root = new TrieNode();\n         for (String w : words) insert(root, w);\n         String[] best = {\"\"};\n         dfs(root, new StringBuilder(), best);\n         return best[0];\n     }\n     static class TrieNode {\n         TrieNode[] next = new TrieNode[26];\n         boolean end;\n     }\n     void insert(TrieNode root, String w) {\n         TrieNode cur = root;\n         for (char ch : w.toCharArray()) {\n             int i = ch - 'a';\n             if (cur.next[i] == null) cur.next[i] = new TrieNode();\n             cur = cur.next[i];\n         }\n         cur.end = true;\n     }\n     void dfs(TrieNode node, StringBuilder path, String[] best) {\n         if (node.end) {\n             String s = path.toString();\n             if (s.length() > best[0].length()\n                 || (s.length() == best[0].length() && s.compareTo(best[0]) < 0))\n                 best[0] = s;\n         }\n         for (int i = 0; i < 26; i++) {\n             if (node.next[i] == null) continue;\n             if (path.length() > 0 && !node.end) continue;\n             path.append((char) ('a' + i));\n             dfs(node.next[i], path, best);\n             path.deleteCharAt(path.length() - 1);\n         }\n     }"}]},{"id":195,"title":"Count Distinct Substrings","module":"Tries","approaches":[{"label":"Brute force","explanation":"Every substring s[i..j] goes into a hash set. Answer is set size.","complexity":"O(n^2 * L) hash work, O(n^2) space.","code":"int countDistinct(String s) {\n         Set<String> seen = new HashSet<>();\n         for (int i = 0; i < s.length(); i++)\n             for (int j = i; j < s.length(); j++)\n                 seen.add(s.substring(i, j + 1));\n         return seen.size();\n     }"},{"label":"Optimal","explanation":"Trie of all suffixes: each new edge while inserting s[i..] is one new distinct substring.","complexity":"O(n^2) time worst case, O(n^2) space.","code":"int countDistinct(String s) {\n         TrieNode root = new TrieNode();\n         int count = 0;\n         for (int i = 0; i < s.length(); i++)\n             count += insertSuffix(root, s, i);\n         return count;\n     }\n     static class TrieNode {\n         TrieNode[] next = new TrieNode[26];\n     }\n     int insertSuffix(TrieNode root, String s, int start) {\n         TrieNode cur = root;\n         int added = 0;\n         for (int i = start; i < s.length(); i++) {\n             int idx = s.charAt(i) - 'a';\n             if (cur.next[idx] == null) {\n                 cur.next[idx] = new TrieNode();\n                 added++;\n             }\n             cur = cur.next[idx];\n         }\n         return added;\n     }"}]},{"id":196,"title":"Maximum XOR of Two Numbers in an Array","module":"Tries","approaches":[{"label":"Brute force","explanation":"Compare every pair and keep the maximum XOR.","complexity":"O(n^2) time, O(1) space.","code":"int findMaximumXOR(int[] nums) {\n         int best = 0;\n         for (int i = 0; i < nums.length; i++)\n             for (int j = i + 1; j < nums.length; j++)\n                 best = Math.max(best, nums[i] ^ nums[j]);\n         return best;\n     }"},{"label":"Better","explanation":"Binary trie on 31-bit representation. For each number, greedily pick the opposite bit child when it exists.","complexity":"O(n * 32) time, O(n * 32) space.","code":"int findMaximumXOR(int[] nums) {\n         TrieNode root = new TrieNode();\n         for (int x : nums) insert(root, x);\n         int best = 0;\n         for (int x : nums) best = Math.max(best, query(root, x));\n         return best;\n     }\n     static class TrieNode {\n         TrieNode[] next = new TrieNode[2];\n     }\n     void insert(TrieNode root, int x) {\n         TrieNode cur = root;\n         for (int b = 31; b >= 0; b--) {\n             int bit = (x >> b) & 1;\n             if (cur.next[bit] == null) cur.next[bit] = new TrieNode();\n             cur = cur.next[bit];\n         }\n     }\n     int query(TrieNode root, int x) {\n         TrieNode cur = root;\n         int ans = 0;\n         for (int b = 31; b >= 0; b--) {\n             int bit = (x >> b) & 1;\n             int want = 1 - bit;\n             if (cur.next[want] != null) {\n                 ans |= (1 << b);\n                 cur = cur.next[want];\n             } else cur = cur.next[bit];\n         }\n         return ans;\n     }"}]},{"id":197,"title":"Maximum XOR Queries (Offline)","module":"Tries","approaches":[{"label":"Brute force","explanation":"For each query (x, m), scan all nums with value <= m and maximize x XOR num.","complexity":"O(q * n) time.","code":"int[] maximizeXor(int[] nums, int[][] queries) {\n         int[] ans = new int[queries.length];\n         for (int i = 0; i < queries.length; i++) {\n             int x = queries[i][0], m = queries[i][1];\n             int best = -1;\n             for (int v : nums) if (v <= m) best = Math.max(best, x ^ v);\n             ans[i] = best;\n         }\n         return ans;\n     }"},{"label":"Optimal","explanation":"Sort nums and queries by limit m. Grow a binary trie as eligible nums increase; answer each query with greedy XOR walk.","complexity":"O((n + q) log U) time for U = max value, O(n * 32) space.","code":"int[] maximizeXor(int[] nums, int[][] queries) {\n         Arrays.sort(nums);\n         int q = queries.length;\n         int[][] ord = new int[q][3];\n         for (int i = 0; i < q; i++) {\n             ord[i][0] = queries[i][1];\n             ord[i][1] = queries[i][0];\n             ord[i][2] = i;\n         }\n         Arrays.sort(ord, (a, b) -> Integer.compare(a[0], b[0]));\n         TrieNode root = new TrieNode();\n         int ptr = 0;\n         int[] ans = new int[q];\n         for (int[] row : ord) {\n             int m = row[0], x = row[1], idx = row[2];\n             while (ptr < nums.length && nums[ptr] <= m) {\n                 insert(root, nums[ptr++]);\n             }\n             ans[idx] = ptr == 0 ? -1 : query(root, x);\n         }\n         return ans;\n     }\n     static class TrieNode {\n         TrieNode[] next = new TrieNode[2];\n     }\n     void insert(TrieNode root, int x) {\n         TrieNode cur = root;\n         for (int b = 31; b >= 0; b--) {\n             int bit = (x >> b) & 1;\n             if (cur.next[bit] == null) cur.next[bit] = new TrieNode();\n             cur = cur.next[bit];\n         }\n     }\n     int query(TrieNode root, int x) {\n         TrieNode cur = root;\n         int ans = 0;\n         for (int b = 31; b >= 0; b--) {\n             int bit = (x >> b) & 1;\n             int want = 1 - bit;\n             if (cur.next[want] != null) {\n                 ans |= (1 << b);\n                 cur = cur.next[want];\n             } else cur = cur.next[bit];\n         }\n         return ans;\n     }"}]},{"id":198,"title":"Word Search II","module":"Tries","approaches":[{"label":"Brute force","explanation":"For each word, run standard grid DFS with backtracking to see if the word appears.","complexity":"O(W * n * m * 4^L) for W words, L max length.","code":"List<String> findWords(char[][] board, String[] words) {\n         List<String> ans = new ArrayList<>();\n         for (String w : words) if (exists(board, w)) ans.add(w);\n         return ans;\n     }\n     boolean exists(char[][] b, String w) {\n         for (int i = 0; i < b.length; i++)\n             for (int j = 0; j < b[0].length; j++)\n                 if (dfs(b, w, 0, i, j)) return true;\n         return false;\n     }\n     boolean dfs(char[][] b, String w, int k, int r, int c) {\n         if (k == w.length()) return true;\n         if (r < 0 || c < 0 || r >= b.length || c >= b[0].length) return false;\n         if (b[r][c] != w.charAt(k)) return false;\n         char tmp = b[r][c];\n         b[r][c] = '#';\n         boolean ok = dfs(b, w, k + 1, r + 1, c) || dfs(b, w, k + 1, r - 1, c)\n             || dfs(b, w, k + 1, r, c + 1) || dfs(b, w, k + 1, r, c - 1);\n         b[r][c] = tmp;\n         return ok;\n     }"},{"label":"Optimal","explanation":"Trie of words plus one DFS on the board. Prune when the trie has no branch for the next cell.","complexity":"O(n * m * 4^L) shared across words with pruning.","code":"List<String> findWords(char[][] board, String[] words) {\n         TrieNode root = build(words);\n         List<String> ans = new ArrayList<>();\n         boolean[][] vis = new boolean[board.length][board[0].length];\n         for (int i = 0; i < board.length; i++)\n             for (int j = 0; j < board[0].length; j++)\n                 walk(board, i, j, root, new StringBuilder(), ans, vis);\n         return ans;\n     }\n     static class TrieNode {\n         TrieNode[] next = new TrieNode[26];\n         String word;\n     }\n     TrieNode build(String[] words) {\n         TrieNode root = new TrieNode();\n         for (String w : words) {\n             TrieNode cur = root;\n             for (char ch : w.toCharArray()) {\n                 int i = ch - 'a';\n                 if (cur.next[i] == null) cur.next[i] = new TrieNode();\n                 cur = cur.next[i];\n             }\n             cur.word = w;\n         }\n         return root;\n     }\n     void walk(char[][] b, int r, int c, TrieNode node, StringBuilder path,\n             List<String> ans, boolean[][] vis) {\n         if (r < 0 || c < 0 || r >= b.length || c >= b[0].length || vis[r][c]) return;\n         TrieNode next = node.next[b[r][c] - 'a'];\n         if (next == null) return;\n         vis[r][c] = true;\n         if (next.word != null) { ans.add(next.word); next.word = null; }\n         walk(b, r + 1, c, next, path, ans, vis);\n         walk(b, r - 1, c, next, path, ans, vis);\n         walk(b, r, c + 1, next, path, ans, vis);\n         walk(b, r, c - 1, next, path, ans, vis);\n         vis[r][c] = false;\n     }"}]},{"id":199,"title":"Reverse Words in a String","module":"Strings","approaches":[{"label":"Brute","explanation":"Split  on  whitespace,  reverse  the  list  of  tokens,  and  join  with  a  single  space.  Extra  structures  make  the  logic obvious.","complexity":"O(n) time, O(n) extra space for the word list.","code":"String reverseWords(String s) {\n     String[] parts = s.trim().split(\"\\s+\");\n     Collections.reverse(Arrays.asList(parts));\n     return String.join(\" \", parts);\n }"},{"label":"Optimal","explanation":"Reverse the whole char array, then reverse each word in place. Two pointers skip spaces and bound each word while swapping ends inward.","complexity":"O(n) time, O(n) space for the char array (or O(1) extra if mutable).","code":"String reverseWords(String s) {\n     char[] a = s.trim().toCharArray();\n     reverse(a, 0, a.length - 1);\n     for (int i = 0; i < a.length; ) {\n         while (i < a.length && a[i] == ' ') i++;\n         if (i >= a.length) break;\n         int j = i;\n         while (j < a.length && a[j] != ' ') j++;\n         reverse(a, i, j - 1);\n         i = j;\n     }\n     return new String(a);\n }\n void reverse(char[] a, int l, int r) {\n     while (l < r) { char t = a[l]; a[l] = a[r]; a[r] = t; l++; r--; }\n }"}]},{"id":200,"title":"Valid Palindrome","module":"Strings","approaches":[{"label":"Brute","explanation":"Keep only alphanumeric characters in a new string, lower-case it, then compare with its reverse.","complexity":"O(n) time, O(n) extra space.","code":"boolean isPalindrome(String s) {\n     StringBuilder t = new StringBuilder();\n     for (int i = 0; i < s.length(); i++) {\n         char c = s.charAt(i);\n         if (Character.isLetterOrDigit(c)) t.append(Character.toLowerCase(c));\n     }\n     return t.toString().equals(t.reverse().toString());\n }"},{"label":"Optimal","explanation":"Two pointers walk inward, skipping non-alphanumeric characters. Compare lower-case letters without building a filtered copy.","complexity":"O(n) time, O(1) extra space.","code":"boolean isPalindrome(String s) {\n     int l = 0, r = s.length() - 1;\n     while (l < r) {\n         while (l < r && !Character.isLetterOrDigit(s.charAt(l))) l++;\n         while (l < r && !Character.isLetterOrDigit(s.charAt(r))) r--;\n         if (Character.toLowerCase(s.charAt(l)) != Character.toLowerCase(s.charAt(r)))\n             return false;\n         l++; r--;\n     }\n     return true;\n }"}]},{"id":201,"title":"Roman to Integer","module":"Strings","approaches":[{"label":"Brute","explanation":"Map each symbol to a value and sum left to right. Whenever a smaller symbol sits before a larger one, subtract twice the smaller (you added it once too many).","complexity":"O(n) time, O(1) space.","code":"int romanToInt(String s) {\n     Map<Character, Integer> m = Map.of(\n         'I', 1, 'V', 5, 'X', 10, 'L', 50,\n         'C', 100, 'D', 500, 'M', 1000);\n     int ans = 0, prev = 0;\n     for (int i = s.length() - 1; i >= 0; i--) {\n         int v = m.get(s.charAt(i));\n         ans += v < prev ? -v : v;\n         prev = v;\n     }\n     return ans;\n }"}]},{"id":202,"title":"String to Integer (atoi)","module":"Strings","approaches":[{"label":"Brute","explanation":"Simulate  the  specification:  skip  spaces,  read  sign,  consume  digits  while  building  the  value,  and  clamp  to  32-bit bounds on overflow.","complexity":"O(n) time, O(1) space.","code":"int myAtoi(String s) {\n     int i = 0, n = s.length();\n     while (i < n && s.charAt(i) == ' ') i++;\n     if (i >= n) return 0;\n     int sign = 1;\n     if (s.charAt(i) == '+' || s.charAt(i) == '-') {\n         sign = s.charAt(i) == '-' ? -1 : 1;\n         i++;\n     }\n     long val = 0;\n     while (i < n && Character.isDigit(s.charAt(i))) {\n         val = val * 10 + (s.charAt(i) - '0');\n         if (sign == 1 && val > Integer.MAX_VALUE) return Integer.MAX_VALUE;\n         if (sign == -1 && -val < Integer.MIN_VALUE) return Integer.MIN_VALUE;\n         i++;\n     }\n     return (int) (sign * val);\n }"}]},{"id":203,"title":"Longest Common Prefix","module":"Strings","approaches":[{"label":"Brute","explanation":"Compare characters column by column across all strings. Stop at the first mismatch or when a string ends.","complexity":"O(n * m) time where m is max length, O(1) extra space.","code":"String longestCommonPrefix(String[] strs) {\n     if (strs.length == 0) return \"\";\n     for (int c = 0; c < strs[0].length(); c++) {\n         char ch = strs[0].charAt(c);\n         for (int i = 1; i < strs.length; i++) {\n             if (c == strs[i].length() || strs[i].charAt(c) != ch)\n                 return strs[0].substring(0, c);\n         }\n     }\n     return strs[0];\n }"},{"label":"Better","explanation":"Sort the array lexicographically. The common prefix of all strings equals the common prefix of the first and last after sorting, because every other string lies between them.","complexity":"O(n log n * m) time for sorting, O(1) extra besides sort.","code":"String longestCommonPrefix(String[] strs) {\n     Arrays.sort(strs);\n     String a = strs[0], b = strs[strs.length - 1];\n     int i = 0;\n         while (i < a.length() && i < b.length() && a.charAt(i) == b.charAt(i)) i++;\n     return a.substring(0, i);\n }"}]},{"id":204,"title":"KMP Pattern Matching","module":"Strings","approaches":[{"label":"Brute","explanation":"Try every start index in the text and compare pattern character by character.","complexity":"O(n * m) time, O(1) extra space.","code":"int strStr(String hay, String needle) {\n     int n = hay.length(), m = needle.length();\n     for (int i = 0; i <= n - m; i++) {\n         int j = 0;\n         while (j < m && hay.charAt(i + j) == needle.charAt(j)) j++;\n         if (j == m) return i;\n     }\n     return -1;\n }"},{"label":"Optimal","explanation":"Build the LPS (longest proper prefix which is also suffix) array for the pattern. On mismatch, shift the pattern by the LPS of the matched prefix instead of restarting the text pointer.","complexity":"O(n + m) time, O(m) space for LPS.","code":"int strStr(String hay, String needle) {\n     if (needle.isEmpty()) return 0;\n     int[] lps = buildLps(needle);\n     int i = 0, j = 0;\n     while (i < hay.length()) {\n         if (hay.charAt(i) == needle.charAt(j)) { i++; j++; }\n         else if (j > 0) j = lps[j - 1];\n         else i++;\n         if (j == needle.length()) return i - j;\n     }\n     return -1;\n }\n int[] buildLps(String p) {\n     int[] lps = new int[p.length()];\n     int len = 0, i = 1;\n     while (i < p.length()) {\n         if (p.charAt(i) == p.charAt(len)) lps[i++] = ++len;\n         else if (len > 0) len = lps[len - 1];\n         else lps[i++] = 0;\n     }\n     return lps;\n }"}]},{"id":205,"title":"Z-Algorithm","module":"Strings","approaches":[{"label":"Better","explanation":"Build Z[i]: length of longest substring starting at i that matches a prefix of s. Maintain the Z-box [l, r] farthest right; values inside copy from the mirror position with clipping.","complexity":"O(n) time, O(n) space.","code":"int[] zFunction(String s) {\n     int n = s.length();\n     int[] z = new int[n];\n     int l = 0, r = 0;\n     for (int i = 1; i < n; i++) {\n         if (i <= r) z[i] = Math.min(r - i + 1, z[i - l]);\n         while (i + z[i] < n && s.charAt(z[i]) == s.charAt(i + z[i])) z[i]++;\n         if (i + z[i] - 1 > r) { l = i; r = i + z[i] - 1; }\n     }\n     return z;\n }\n int zSearch(String text, String pat) {\n     String s = pat + \"$\" + text;\n     int[] z = zFunction(s);\n     int m = pat.length();\n     for (int i = m + 1; i < s.length(); i++)\n         if (z[i] == m) return i - m - 1;\n     return -1;\n }"}]},{"id":206,"title":"Rabin-Karp","module":"Strings","approaches":[{"label":"Brute","explanation":"Same as naive matching: every text offset, compare the pattern.","complexity":"O(n * m) time, O(1) extra space.","code":"int rkBrute(String s, String p) {\n     int n = s.length(), m = p.length();\n     for (int i = 0; i <= n - m; i++) {\n         if (s.regionMatches(i, p, 0, m)) return i;\n     }\n     return -1;\n }"},{"label":"Optimal","explanation":"Rolling  hash  of  the  window  of  length  m.  Equal  hashes  suggest  a  match;  confirm  with  character  comparison  to handle collisions.","complexity":"O(n + m) expected time, O(1) extra space.","code":"int strStrRabinKarp(String s, String p) {\n     int n = s.length(), m = p.length();\n     if (m == 0) return 0;\n     long base = 256, mod = 1_000_000_007;\n     long ph = 0, sh = 0, pow = 1;\n     for (int i = 0; i < m; i++) {\n         ph = (ph * base + p.charAt(i)) % mod;\n         sh = (sh * base + s.charAt(i)) % mod;\n         if (i < m - 1) pow = (pow * base) % mod;\n     }\n     for (int i = 0; i <= n - m; i++) {\n         if (ph == sh && s.regionMatches(i, p, 0, m)) return i;\n         if (i < n - m) {\n             sh = (sh - s.charAt(i) * pow % mod + mod) % mod;\n             sh = (sh * base + s.charAt(i + m)) % mod;\n         }\n     }\n     return -1;\n }"}]},{"id":207,"title":"Valid Anagram","module":"Strings","approaches":[{"label":"Brute","explanation":"Sort both strings and compare. Anagrams have identical sorted forms.","complexity":"O(n log n) time, O(n) space for char arrays.","code":"boolean isAnagram(String s, String t) {\n     if (s.length() != t.length()) return false;\n     char[] a = s.toCharArray(), b = t.toCharArray();\n     Arrays.sort(a);\n     Arrays.sort(b);\n     return Arrays.equals(a, b);\n }"},{"label":"Optimal","explanation":"Count letter frequencies in one pass. Increment for s, decrement for t; all counts must be zero.","complexity":"O(n) time, O(1) space (26 letters).","code":"boolean isAnagram(String s, String t) {\n     if (s.length() != t.length()) return false;\n     int[] cnt = new int[26];\n     for (int i = 0; i < s.length(); i++) {\n         cnt[s.charAt(i) - 'a']++;\n         cnt[t.charAt(i) - 'a']--;\n     }\n     for (int c : cnt) if (c != 0) return false;\n     return true;\n }"}]},{"id":208,"title":"Group Anagrams","module":"Strings","approaches":[{"label":"Brute","explanation":"For each word, sort its letters and use the sorted string as a hash key. Words sharing a key are anagrams.","complexity":"O(n * k log k) time for n words of length k.","code":"List<List<String>> groupAnagrams(String[] strs) {\n     Map<String, List<String>> map = new HashMap<>();\n     for (String w : strs) {\n         char[] a = w.toCharArray();\n         Arrays.sort(a);\n         String key = new String(a);\n         map.computeIfAbsent(key, x -> new ArrayList<>()).add(w);\n     }\n     return new ArrayList<>(map.values());\n }"},{"label":"Optimal","explanation":"Use a frequency signature (26 counts) as key instead of sorting. Same bucket, fewer log factors.","complexity":"O(n * k) time, O(n * k) space for stored words.","code":"List<List<String>> groupAnagrams(String[] strs) {\n     Map<String, List<String>> map = new HashMap<>();\n     for (String w : strs) {\n         int[] cnt = new int[26];\n         for (int i = 0; i < w.length(); i++) cnt[w.charAt(i) - 'a']++;\n         StringBuilder sb = new StringBuilder();\n         for (int i = 0; i < 26; i++) { sb.append('#'); sb.append(cnt[i]); }\n         map.computeIfAbsent(sb.toString(), x -> new ArrayList<>()).add(w);\n     }\n     return new ArrayList<>(map.values());\n }"}]},{"id":209,"title":"Count and Say","module":"Strings","approaches":[{"label":"Brute","explanation":"Build term i from term i-1 by reading runs of equal digits (count, digit). Repeat until the nth term.","complexity":"O(n * L) time where L is final string length; O(L) space.","code":"String countAndSay(int n) {\n     String cur = \"1\";\n     for (int k = 2; k <= n; k++) {\n         StringBuilder nxt = new StringBuilder();\n         int i = 0;\n         while (i < cur.length()) {\n             int j = i;\n             while (j < cur.length() && cur.charAt(j) == cur.charAt(i)) j++;\n             nxt.append(j - i).append(cur.charAt(i));\n             i = j;\n         }\n         cur = nxt.toString();\n     }\n     return cur;\n }"}]},{"id":210,"title":"Longest Palindromic Substring","module":"Strings","approaches":[{"label":"Brute","explanation":"Every pair (l, r) with l <= r is a candidate substring; test palindrome by two pointers.","complexity":"O(n^3) time, O(1) extra space.","code":"String longestPalindrome(String s) {\n     int bestL = 0, bestLen = 1;\n     for (int l = 0; l < s.length(); l++) {\n         for (int r = l; r < s.length(); r++) {\n             if (isPal(s, l, r) && r - l + 1 > bestLen) {\n                 bestL = l;\n                 bestLen = r - l + 1;\n             }\n         }\n     }\n     return s.substring(bestL, bestL + bestLen);\n }\n boolean isPal(String s, int l, int r) {\n     while (l < r) {\n         if (s.charAt(l++) != s.charAt(r--)) return false;\n     }\n     return true;\n }"},{"label":"Better","explanation":"Expand around every center (odd and even). A palindrome is symmetric, so walk outward while characters match.","complexity":"O(n^2) time, O(1) extra space.","code":"String longestPalindrome(String s) {\n     int start = 0, len = 0;\n     for (int i = 0; i < s.length(); i++) {\n         int l1 = expand(s, i, i), l2 = expand(s, i, i + 1);\n         int cur = Math.max(l1, l2);\n         if (cur > len) {\n             len = cur;\n             start = i - (cur - 1) / 2;\n         }\n     }\n     return s.substring(start, start + len);\n }\n int expand(String s, int l, int r) {\n     while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) { l--; r++; }\n     return r - l - 1;\n }"}]},{"id":211,"title":"Minimum Characters to Prepend for Palindrome","module":"Strings","approaches":[{"label":"Brute","explanation":"Try every suffix s[i..] that is a palindrome; answer is i (prepend the reverse of s[0..i-1]).","complexity":"O(n^2) time, O(1) extra space.","code":"int minCharsPrepend(String s) {\n     int n = s.length();\n     for (int i = 0; i < n; i++) {\n         if (isPal(s, i, n - 1)) return i;\n     }\n     return n - 1;\n }\n boolean isPal(String s, int l, int r) {\n     while (l < r) if (s.charAt(l++) != s.charAt(r--)) return false;\n     return true;\n }"},{"label":"Optimal","explanation":"Form t = s + '#' + reverse(s). The LPS at the last index equals the longest palindromic prefix of s. Prepend length is n minus that LPS.","complexity":"O(n) time, O(n) space.","code":"int minCharsPrepend(String s) {\n     String rev = new StringBuilder(s).reverse().toString();\n     String t = s + \"#\" + rev;\n     int[] lps = buildLps(t);\n     return s.length() - lps[t.length() - 1];\n }\n int[] buildLps(String p) {\n     int[] lps = new int[p.length()];\n     for (int i = 1, len = 0; i < p.length(); ) {\n         if (p.charAt(i) == p.charAt(len)) lps[i++] = ++len;\n         else if (len > 0) len = lps[len - 1];\n         else lps[i++] = 0;\n     }\n     return lps;\n }"}]},{"id":212,"title":"Single Number I","module":"Bit Manipulation","approaches":[{"label":"Brute","explanation":"For each value, count occurrences in the array. The unique element appears once.","complexity":"O(n^2) time, O(1) extra space.","code":"int singleNumber(int[] nums) {\n     for (int x : nums) {\n         int c = 0;\n         for (int y : nums) if (y == x) c++;\n         if (c == 1) return x;\n     }\n     return -1;\n }"},{"label":"Optimal","explanation":"XOR every number. Pairs cancel to 0; the survivor is the lone element.","complexity":"O(n) time, O(1) space.","code":"int singleNumber(int[] nums) {\n     int ans = 0;\n     for (int x : nums) ans ^= x;\n     return ans;\n }"}]},{"id":213,"title":"Single Number II","module":"Bit Manipulation","approaches":[{"label":"Brute","explanation":"HashMap counts frequencies and return the key with count 1.","complexity":"O(n) time, O(n) space.","code":"int singleNumber(int[] nums) {\n     Map<Integer, Integer> cnt = new HashMap<>();\n     for (int x : nums) cnt.merge(x, 1, Integer::sum);\n     for (var e : cnt.entrySet()) if (e.getValue() == 1) return e.getKey();\n     return -1;\n }"},{"label":"Optimal","explanation":"Track ones and twos bitsets: each bit counts mod 3. When a bit hits 3 in ones, clear it from ones and twos.","complexity":"O(n) time, O(1) space.","code":"int singleNumber(int[] nums) {\n     int ones = 0, twos = 0;\n     for (int x : nums) {\n         ones = (ones ^ x) & ~twos;\n         twos = (twos ^ x) & ~ones;\n     }\n     return ones;\n }"}]},{"id":214,"title":"Single Number III","module":"Bit Manipulation","approaches":[{"label":"Better","explanation":"XOR all numbers to get a ^ b. Any set bit in that XOR separates a and b into two groups with different XOR results.","complexity":"O(n) time, O(1) space.","code":"int[] singleNumber(int[] nums) {\n     int xor = 0;\n     for (int x : nums) xor ^= x;\n     int diff = xor & -xor;\n     int a = 0, b = 0;\n     for (int x : nums) {\n         if ((x & diff) != 0) a ^= x;\n         else b ^= x;\n     }\n     return new int[]{a, b};\n }"}]},{"id":215,"title":"Number of 1 Bits","module":"Bit Manipulation","approaches":[{"label":"Brute","explanation":"Check each of the 32 bit positions.","complexity":"O(32) time, O(1) space.","code":"int hammingWeight(int n) {\n     int ans = 0;\n     for (int i = 0; i < 32; i++) if (((n >>> i) & 1) == 1) ans++;\n     return ans;\n }"},{"label":"Optimal","explanation":"Clear the lowest set bit with n &= n - 1. Each step removes one 1-bit.","complexity":"O(number of set bits) time, O(1) space.","code":"int hammingWeight(int n) {\n     int ans = 0;\n     while (n != 0) {\n         n &= n - 1;\n         ans++;\n     }\n     return ans;\n }"}]},{"id":216,"title":"Counting Bits for 0..n","module":"Bit Manipulation","approaches":[{"label":"Brute","explanation":"For each i, count bits with the popcount loop.","complexity":"O(n log n) time, O(1) extra besides output.","code":"int[] countBits(int n) {\n     int[] ans = new int[n + 1];\n     for (int i = 0; i <= n; i++) {\n         int x = i, c = 0;\n         while (x != 0) { x &= x - 1; c++; }\n         ans[i] = c;\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"ans[i] = ans[i >> 1] + (i & 1). Drop the last bit and add its value.","complexity":"O(n) time, O(n) space for output.","code":"int[] countBits(int n) {\n     int[] ans = new int[n + 1];\n     for (int i = 1; i <= n; i++) ans[i] = ans[i >> 1] + (i & 1);\n     return ans;\n }"}]},{"id":217,"title":"Set Bits Sum from 1 to n","module":"Bit Manipulation","approaches":[{"label":"Brute","explanation":"Add popcount for every integer from 1 through n.","complexity":"O(n log n) time, O(1) extra space.","code":"int countSetBits1ToN(int n) {\n     int sum = 0;\n     for (int i = 1; i <= n; i++) {\n         int x = i;\n         while (x != 0) { sum++; x &= x - 1; }\n     }\n     return sum;\n }"},{"label":"Optimal","explanation":"For each bit position, count how many numbers in [1, n] have it set using a periodic pattern of length 2^(k+1).","complexity":"O(log n) time, O(1) space.","code":"int countSetBits1ToN(int n) {\n     int ans = 0;\n     for (int k = 0; (1L << k) <= n; k++) {\n         long period = 1L << (k + 1);\n         long full = (n + 1) / period;\n         ans += full * (1L << k);\n         long rem = (n + 1) % period;\n         ans += Math.max(0, rem - (1L << k));\n     }\n     return ans;\n }"}]},{"id":218,"title":"Divide Two Integers","module":"Bit Manipulation","approaches":[{"label":"Brute","explanation":"Repeatedly subtract |divisor| from |dividend| while tracking sign. Slow but direct.","complexity":"O(|dividend| / |divisor|) time, O(1) space.","code":"int divide(int dividend, int divisor) {\n     if (dividend == Integer.MIN_VALUE && divisor == -1) return Integer.MAX_VALUE;\n     boolean neg = (dividend < 0) ^ (divisor < 0);\n     long a = Math.abs((long) dividend), b = Math.abs((long) divisor);\n     int q = 0;\n     while (a >= b) { a -= b; q++; }\n     return neg ? -q : q;\n }"},{"label":"Optimal","explanation":"Binary long division: if a >= b*2^k, subtract b<<k and add 2^k to quotient. Halve k when the chunk is too big.","complexity":"O(log^2 |dividend|) time, O(1) space.","code":"int divide(int dividend, int divisor) {\n     if (dividend == Integer.MIN_VALUE && divisor == -1) return Integer.MAX_VALUE;\n     boolean neg = (dividend < 0) ^ (divisor < 0);\n     long a = Math.abs((long) dividend), b = Math.abs((long) divisor);\n     int q = 0;\n     while (a >= b) {\n         long temp = b, k = 1;\n         while (a >= temp << 1) { temp <<= 1; k <<= 1; }\n         a -= temp;\n         q += k;\n     }\n     return neg ? -q : q;\n }"}]},{"id":219,"title":"Power Set Using Bits","module":"Bit Manipulation","approaches":[{"label":"Brute","explanation":"Recursively choose or skip each index to build every subset.","complexity":"O(n * 2^n) time and output size.","code":"List<List<Integer>> subsets(int[] nums) {\n     List<List<Integer>> ans = new ArrayList<>();\n     build(nums, 0, new ArrayList<>(), ans);\n     return ans;\n }\n void build(int[] nums, int i, List<Integer> cur, List<List<Integer>> ans) {\n     if (i == nums.length) { ans.add(new ArrayList<>(cur)); return; }\n     cur.add(nums[i]);\n     build(nums, i + 1, cur, ans);\n     cur.remove(cur.size() - 1);\n     build(nums, i + 1, cur, ans);\n }"},{"label":"Optimal","explanation":"Mask from 0 to 2^n - 1: bit j selects nums[j]. Each mask is one subset.","complexity":"O(n * 2^n) time, O(1) extra besides output.","code":"List<List<Integer>> subsets(int[] nums) {\n     List<List<Integer>> ans = new ArrayList<>();\n     int n = nums.length;\n     for (int mask = 0; mask < (1 << n); mask++) {\n         List<Integer> sub = new ArrayList<>();\n         for (int j = 0; j < n; j++)\n             if ((mask & (1 << j)) != 0) sub.add(nums[j]);\n         ans.add(sub);\n     }\n     return ans;\n }"}]},{"id":220,"title":"XOR from L to R","module":"Bit Manipulation","approaches":[{"label":"Brute","explanation":"XOR every integer from L to R inclusive.","complexity":"O(R - L + 1) time, O(1) space.","code":"int xorRange(int L, int R) {\n     int ans = 0;\n     for (int i = L; i <= R; i++) ans ^= i;\n     return ans;\n }"},{"label":"Optimal","explanation":"Prefix XOR: xor(1..n) has a period-4 pattern. Answer is prefix(R) ^ prefix(L - 1).","complexity":"O(1) time, O(1) space.","code":"int xorRange(int L, int R) {\n     return prefix(R) ^ prefix(L - 1);\n }\n int prefix(int n) {\n     int r = n % 4;\n     if (r == 0) return n;\n     if (r == 1) return 1;\n     if (r == 2) return n + 1;\n     return 0;\n }"}]},{"id":221,"title":"Minimum Flips to Make a OR b Equal to c","module":"Bit Manipulation","approaches":[{"label":"Brute","explanation":"Try all flip combinations on bits of a and b where (a|b) differs from c — impractical; instead flip greedily per bit when c needs 0 but both are 1.","complexity":"O(32) time, O(1) space.","code":"int minFlips(int a, int b, int c) {\n     int flips = 0;\n     for (int k = 0; k < 31; k++) {\n         int ab = (a >> k & 1), bb = (b >> k & 1), cb = (c >> k & 1);\n         if (cb == 0) {\n             flips += ab + bb;\n         } else {\n             if (ab == 0 && bb == 0) flips++;\n         }\n     }\n     return flips;\n }"}]},{"id":222,"title":"Greatest Common Divisor","module":"Mathematics","approaches":[{"label":"Brute","explanation":"Every divisor of the smaller number that also divides the larger is a common divisor; take the maximum.","complexity":"O(min(a, b)) time, O(1) space.","code":"int gcdBrute(int a, int b) {\n     a = Math.abs(a); b = Math.abs(b);\n     int g = 1;\n     for (int d = 1; d <= Math.min(a, b); d++)\n         if (a % d == 0 && b % d == 0) g = d;\n     return g;\n }"},{"label":"Optimal","explanation":"Euclid: gcd(a, b) = gcd(b, a mod b). The remainder strictly shrinks the pair until it hits zero.","complexity":"O(log min(a, b)) time, O(1) space.","code":"int gcd(int a, int b) {\n     a = Math.abs(a); b = Math.abs(b);\n     while (b != 0) {\n         int t = a % b;\n         a = b;\n         b = t;\n     }\n     return a;\n }"}]},{"id":223,"title":"Sieve of Eratosthenes","module":"Mathematics","approaches":[{"label":"Brute","explanation":"For each x up to n, test primality by trial division up to sqrt(x).","complexity":"O(n sqrt n) time, O(1) extra besides output.","code":"List<Integer> primesBrute(int n) {\n     List<Integer> ans = new ArrayList<>();\n     for (int x = 2; x <= n; x++) {\n         boolean ok = true;\n         for (int d = 2; d * d <= x; d++)\n             if (x % d == 0) { ok = false; break; }\n         if (ok) ans.add(x);\n     }\n     return ans;\n }"},{"label":"Optimal","explanation":"Mark multiples of each prime starting at p*p. The smallest unmarked index is the next prime.","complexity":"O(n log log n) time, O(n) space.","code":"List<Integer> sieve(int n) {\n     boolean[] comp = new boolean[n + 1];\n     List<Integer> primes = new ArrayList<>();\n     for (int p = 2; p <= n; p++) {\n         if (comp[p]) continue;\n         primes.add(p);\n         for (long m = (long) p * p; m <= n; m += p) comp[(int) m] = true;\n     }\n     return primes;\n }"}]},{"id":224,"title":"Prime Factorization","module":"Mathematics","approaches":[{"label":"Brute","explanation":"Try every divisor d from 2 upward; divide out all copies of d before moving on.","complexity":"O(sqrt n) time, O(1) extra space.","code":"List<Integer> primeFactors(int n) {\n     List<Integer> f = new ArrayList<>();\n     for (int d = 2; d * d <= n; d++) {\n         while (n % d == 0) {\n             f.add(d);\n             n /= d;\n         }\n     }\n     if (n > 1) f.add(n);\n     return f;\n }"},{"label":"Better","explanation":"After stripping 2, only odd trial divisors are needed. If nothing divides up to sqrt(n), the remainder is prime.","complexity":"O(sqrt n) time, O(1) extra besides factors.","code":"List<Integer> primeFactorsOdd(int n) {\n     List<Integer> f = new ArrayList<>();\n     while (n % 2 == 0) { f.add(2); n /= 2; }\n     for (int d = 3; d * d <= n; d += 2) {\n         while (n % d == 0) { f.add(d); n /= d; }\n     }\n     if (n > 1) f.add(n);\n     return f;\n }"}]},{"id":225,"title":"Modular Exponentiation","module":"Mathematics","approaches":[{"label":"Brute","explanation":"Multiply base by itself x times, reducing mod m each step.","complexity":"O(x log m) time for big integers, O(1) space.","code":"long modPowBrute(long base, long exp, int mod) {\n     long ans = 1 % mod;\n     base %= mod;\n     for (long i = 0; i < exp; i++) ans = ans * base % mod;\n     return ans;\n }"},{"label":"Optimal","explanation":"Binary exponentiation: if exp is odd multiply ans by base; square base; halve exp. Every bit of exp is processed once.","complexity":"O(log exp) time, O(1) space.","code":"long modPow(long base, long exp, int mod) {\n     long ans = 1 % mod;\n     base %= mod;\n     while (exp > 0) {\n         if ((exp & 1) == 1) ans = ans * base % mod;\n         base = base * base % mod;\n         exp >>= 1;\n     }\n     return ans;\n }"}]},{"id":226,"title":"Trailing Zeros in n!","module":"Mathematics","approaches":[{"label":"Brute","explanation":"Compute  n!  (or  iterate  multiplication)  and  count  factors  of  10  by  dividing  the  product  —  overflows  without  big integers.","complexity":"O(n) multiplications; impractical for large n.","code":"int trailingZeroesBrute(int n) {\n     long fact = 1;\n     for (int i = 2; i <= n; i++) fact *= i;\n     int z = 0;\n     while (fact % 10 == 0) { z++; fact /= 10; }\n     return z;\n }"},{"label":"Optimal","explanation":"Each trailing zero needs a factor 10 = 2*5. There are always more twos; count fives: n/5 + n/25 + ...","complexity":"O(log n) time, O(1) space.","code":"int trailingZeroes(int n) {\n     int z = 0;\n     for (long p = 5; p <= n; p *= 5) z += n / p;\n     return z;\n }"}]},{"id":227,"title":"Numbers With Same Trailing Zeros as n!","module":"Mathematics","approaches":[{"label":"Brute","explanation":"Compute z = trailingZeroes(n). Scan m from 1 upward and count m where trailingZeroes(m) equals z.","complexity":"O(n log n) time if each factorial zero count is O(log m).","code":"int countSameTrailingZerosBrute(int n) {\n     int z = trailingZeroes(n);\n     int cnt = 0;\n     for (int m = 1; m <= n; m++)\n         if (trailingZeroes(m) == z) cnt++;\n     return cnt;\n }\n int trailingZeroes(int m) {\n     int z = 0;\n     for (long p = 5; p <= m; p *= 5) z += m / p;\n     return z;\n }"},{"label":"Optimal","explanation":"Trailing zeros depend only on v5(m). Count integers in [1, n] whose 5-adic valuation matches v5(n!). Use inclusion on the highest power of 5 dividing n!.","complexity":"O(log n) time, O(1) space.","code":"int countSameTrailingZeros(int n) {\n     int z = trailingZeroes(n);\n     int cnt = 0;\n     for (int m = 1; m <= n; m++) {\n         int v = 0;\n         for (long x = m; x % 5 == 0; x /= 5) v++;\n         if (v == z) cnt++;\n     }\n     return cnt;\n }"}]},{"id":228,"title":"Count Primes Less Than n","module":"Mathematics","approaches":[{"label":"Brute","explanation":"Trial division primality for every x < n.","complexity":"O(n sqrt n) time, O(1) extra space.","code":"int countPrimesBrute(int n) {\n     int cnt = 0;\n     for (int x = 2; x < n; x++) {\n         boolean prime = true;\n         for (int d = 2; d * d <= x; d++)\n             if (x % d == 0) { prime = false; break; }\n         if (prime) cnt++;\n     }\n     return cnt;\n }"},{"label":"Optimal","explanation":"Sieve boolean array; answer is n minus the number of composites marked.","complexity":"O(n log log n) time, O(n) space.","code":"int countPrimes(int n) {\n     if (n <= 2) return 0;\n     boolean[] comp = new boolean[n];\n     int cnt = 0;\n     for (int p = 2; p < n; p++) {\n         if (comp[p]) continue;\n         cnt++;\n         for (long m = (long) p * p; m < n; m += p) comp[(int) m] = true;\n     }\n     return cnt;\n }"}]},{"id":229,"title":"Fast Fibonacci (nth)","module":"Mathematics","approaches":[{"label":"Brute","explanation":"Iterative DP: each term is sum of the previous two.","complexity":"O(n) time, O(1) space.","code":"int fibBrute(int n) {\n     if (n <= 1) return n;\n     int a = 0, b = 1;\n     for (int i = 2; i <= n; i++) {\n         int c = a + b;\n         a = b;\n         b = c;\n     }\n     return b;\n }"},{"label":"Better","explanation":"Matrix [[1,1],[1,0]]^n multiplied by [F1, F0]^T gives F(n+1), F(n). Use binary matrix exponentiation.","complexity":"O(log n) time, O(1) space.","code":"int fib(int n) {\n     if (n <= 1) return n;\n     long[][] M = {{1, 1}, {1, 0}};\n     long[][] P = matPow(M, n);\n     return (int) P[0][1];\n }\n long[][] matPow(long[][] a, int exp) {\n     long[][] res = {{1, 0}, {0, 1}};\n     while (exp > 0) {\n         if ((exp & 1) == 1) res = matMul(res, a);\n         a = matMul(a, a);\n         exp >>= 1;\n     }\n     return res;\n }\n long[][] matMul(long[][] x, long[][] y) {\n     return new long[][]{\n         {x[0][0] * y[0][0] + x[0][1] * y[1][0], x[0][0] * y[0][1] + x[0][1] * y[1][1]},\n         {x[1][0] * y[0][0] + x[1][1] * y[1][0], x[1][0] * y[0][1] + x[1][1] * y[1][1]}\n     };\n }"}]}];
  const escapeHtml = (value = "") => value.replace(/[&<>"']/g, (character) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;"
  }[character]));

  window.LECTURES = window.LECTURES || [];
  problems.forEach((problem) => {
    const approaches = problem.approaches;
    const last = approaches[approaches.length - 1];
    const xs = approaches.map((_, index) => (index - (approaches.length - 1) / 2) * 4.2);
    window.LECTURES.push({
      course: "striver",
      id: problem.id,
      title: problem.title,
      category: problem.module,
      tagline: approaches.map((approach) => approach.label).join(" → "),
      summary: approaches[0].explanation,
      theory: approaches.map((approach) => ({
        heading: approach.label,
        body: [
          `<span>${escapeHtml(approach.explanation)}</span>`,
          approach.complexity ? `<strong class="complexity">Complexity: ${escapeHtml(approach.complexity)}</strong>` : "",
          approach.code ? `<pre><code>${escapeHtml(approach.code)}</code></pre>` : ""
        ].filter(Boolean).join("")
      })),
      keyTerms: approaches.map((approach) => ({
        term: approach.label,
        def: approach.complexity || "See the explanation and Java implementation."
      })),
      tradeoffs: approaches.length > 1 ? [{
        pro: `${last.label} reaches ${last.complexity || "the preferred solution"}.`,
        con: `${approaches[0].label} is easier to derive, but usually costs more time or space.`
      }] : [],
      interviewTips: [
        `Start with the ${approaches[0].label.toLowerCase()} idea, then explain what makes it expensive.`,
        `State the final complexity: ${last.complexity || "derive it from the implementation"}.`,
        "Code the Java function only after naming the invariant or recurrence."
      ],
      scene: {
        nodes: [
          { id: "problem", label: problem.title, type: "note", pos: [0, 0, -5.2], showAt: 0 },
          ...approaches.map((approach, index) => ({
            id: `approach-${index}`,
            label: approach.label,
            type: index === approaches.length - 1 ? "worker" : "server",
            pos: [xs[index], 0, 1.2],
            showAt: index
          }))
        ],
        edges: approaches.slice(1).map((_, index) => ({
          from: `approach-${index}`,
          to: `approach-${index + 1}`,
          label: "improve",
          showAt: index + 1
        })),
        steps: approaches.map((approach, index) => ({
          title: approach.label,
          text: `${approach.explanation}${approach.complexity ? ` Complexity: ${approach.complexity}` : ""}`,
          highlight: [`approach-${index}`],
          flows: index ? [{ from: `approach-${index - 1}`, to: `approach-${index}`, label: "optimize" }] : []
        }))
      }
    });
  });
})();
